CREATE OR REPLACE FUNCTION "public"."_assert_final_discovery_valid"("p_property_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_geom_ok boolean; v_conf timestamptz; v_total int; v_final int; v_primary int; v_bad int;
BEGIN
  SELECT (geom_exact IS NOT NULL), location_confirmed_at
    INTO v_geom_ok, v_conf FROM public.properties WHERE id = p_property_id;
  IF v_geom_ok IS NULL THEN RAISE EXCEPTION 'property not found'; END IF;
  IF NOT v_geom_ok OR v_conf IS NULL THEN RAISE EXCEPTION 'exact location not confirmed'; END IF;

  SELECT count(*),
         count(*) FILTER (WHERE a.relationship IS NULL),
         count(*) FILTER (WHERE a.is_primary),
         count(*) FILTER (WHERE a.is_primary AND g.kind NOT IN ('search_region','settlement'))
    INTO v_total, v_final, v_primary, v_bad
    FROM public.property_geo_associations a
    JOIN public.geo_places g ON g.id = a.geo_place_id
    WHERE a.property_id = p_property_id;

  IF v_total = 0 OR v_final <> v_total THEN
    RAISE EXCEPTION 'discovery set must be all-final with at least one association';
  END IF;
  IF v_primary <> 1 THEN RAISE EXCEPTION 'exactly one primary association required'; END IF;
  IF v_bad > 0 THEN RAISE EXCEPTION 'primary association must be search_region/settlement'; END IF;
END;
$$;


ALTER FUNCTION "public"."_assert_final_discovery_valid"("p_property_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_build_rating_side_v2"("p_total" bigint, "p_reach_pos" bigint, "p_reach_den" bigint, "p_acc_pos" bigint, "p_acc_den" bigint, "p_prog_pos" bigint, "p_prog_den" bigint, "p_resp_pos" bigint, "p_resp_den" bigint, "p_trust_pos" bigint, "p_trust_den" bigint) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN p_total = 0 THEN NULL
    WHEN p_total < 3 THEN jsonb_build_object('total', p_total, 'metrics', NULL)
    ELSE jsonb_build_object(
      'total', p_total,
      'metrics', jsonb_build_object(
        'easy_to_reach',   jsonb_build_object('pct', round(100.0 * p_reach_pos / NULLIF(p_reach_den,0))::int, 'denom', p_reach_den),
        'details_matched', jsonb_build_object('pct', round(100.0 * p_acc_pos   / NULLIF(p_acc_den,0))::int,   'denom', p_acc_den),
        'respectful',      jsonb_build_object('pct', round(100.0 * p_resp_pos  / NULLIF(p_resp_den,0))::int,  'denom', p_resp_den),
        'deal_again',      jsonb_build_object('pct', round(100.0 * p_trust_pos / NULLIF(p_trust_den,0))::int, 'denom', p_trust_den),
        'moved_forward', CASE
          WHEN p_prog_den = 0 THEN jsonb_build_object('status','none')
          WHEN p_prog_den < 3 THEN jsonb_build_object('status','insufficient')
          ELSE jsonb_build_object('status','ok','pct', round(100.0 * p_prog_pos / NULLIF(p_prog_den,0))::int, 'denom', p_prog_den)
        END
      )
    )
  END
$$;


ALTER FUNCTION "public"."_build_rating_side_v2"("p_total" bigint, "p_reach_pos" bigint, "p_reach_den" bigint, "p_acc_pos" bigint, "p_acc_den" bigint, "p_prog_pos" bigint, "p_prog_den" bigint, "p_resp_pos" bigint, "p_resp_den" bigint, "p_trust_pos" bigint, "p_trust_den" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_geo_insert_aliases"("p_geo_place_id" "uuid", "p_aliases" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE a text;
BEGIN
  IF p_aliases IS NULL THEN RETURN; END IF;
  FOREACH a IN ARRAY p_aliases LOOP
    IF btrim(COALESCE(a,'')) = '' THEN CONTINUE; END IF;
    INSERT INTO public.geo_place_aliases (geo_place_id, alias, normalized_alias)
      VALUES (p_geo_place_id, btrim(a), lower(btrim(a)))
      ON CONFLICT (geo_place_id, normalized_alias) DO NOTHING;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."_geo_insert_aliases"("p_geo_place_id" "uuid", "p_aliases" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_comment"("p_comment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_c public.property_comments;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED';
  END IF;

  SELECT * INTO v_c FROM public.property_comments WHERE id = p_comment_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'COMMENT_NOT_FOUND';
  END IF;
  IF v_c.hidden_reason = 'user_deleted' THEN
    RAISE EXCEPTION 'CANNOT_DELETE_USER_DELETED';
  END IF;
  IF v_c.is_deleted AND v_c.hidden_reason = 'admin_hidden' THEN
    RAISE EXCEPTION 'ALREADY_DELETED';
  END IF;

  UPDATE public.property_comments
  SET is_deleted = true, hidden_reason = 'admin_hidden' WHERE id = p_comment_id;

  UPDATE public.comment_reports
  SET resolution = 'upheld', resolved_at = now(), resolved_by = auth.uid()
  WHERE comment_id = p_comment_id AND resolution IS NULL;

  INSERT INTO public.comment_moderation_actions (comment_id, admin_id, action)
  VALUES (p_comment_id, auth.uid(), 'delete');

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."admin_delete_comment"("p_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_draft_property"("p_property_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT status INTO v_status
  FROM public.properties
  WHERE id = p_property_id
  FOR UPDATE;

  IF v_status IS NULL THEN
    RAISE EXCEPTION 'Property not found';
  END IF;

  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'Only draft properties can be deleted (current status: %)', v_status;
  END IF;

  DELETE FROM public.properties WHERE id = p_property_id;
END;
$$;


ALTER FUNCTION "public"."admin_delete_draft_property"("p_property_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_delete_draft_property"("p_property_id" "uuid") IS 'Admin-only. Hard-deletes a draft property with pre-check for applications/visits. Phase 1.5 Prompt 12 G1.';



CREATE OR REPLACE FUNCTION "public"."admin_unhide_comment"("p_comment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_c public.property_comments;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED';
  END IF;

  SELECT * INTO v_c FROM public.property_comments WHERE id = p_comment_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'COMMENT_NOT_FOUND';
  END IF;
  IF v_c.hidden_reason = 'user_deleted' THEN
    RAISE EXCEPTION 'CANNOT_RESTORE_USER_DELETED';
  END IF;
  IF NOT (v_c.is_deleted AND v_c.hidden_reason IN ('auto_hidden_reports','admin_hidden')) THEN
    RAISE EXCEPTION 'COMMENT_NOT_HIDDEN';
  END IF;

  UPDATE public.property_comments
  SET is_deleted = false, hidden_reason = NULL WHERE id = p_comment_id;

  UPDATE public.comment_reports
  SET resolution = 'dismissed', resolved_at = now(), resolved_by = auth.uid()
  WHERE comment_id = p_comment_id AND resolution IS NULL;

  INSERT INTO public.comment_moderation_actions (comment_id, admin_id, action)
  VALUES (p_comment_id, auth.uid(), 'unhide');

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."admin_unhide_comment"("p_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_final_property_location"("p_property_id" "uuid", "p_actor_user_id" "uuid", "p_actor_type" "text", "p_location" "jsonb", "p_final_associations" "jsonb", "p_streetview" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_owner uuid; v_status text;
  v_lat double precision; v_lng double precision; v_cc text;
  v_ex_src text; v_ex_place text; v_ex_name text;
  v_in_name text; v_in_src text; v_in_place text;
  v_final_name text; v_final_src text; v_final_place text; v_address_mode text;
  v_sv_available boolean; v_sv_pano text;
BEGIN
  IF p_actor_type NOT IN ('owner','admin') THEN RAISE EXCEPTION 'invalid actor_type %', p_actor_type; END IF;
  SELECT owner_id, status::text, building_name_source, place_id, building_name
    INTO v_owner, v_status, v_ex_src, v_ex_place, v_ex_name
    FROM public.properties WHERE id = p_property_id FOR UPDATE;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'property not found'; END IF;
  IF p_actor_type = 'owner' THEN
    IF p_actor_user_id IS DISTINCT FROM v_owner THEN RAISE EXCEPTION 'actor does not own property'; END IF;
    IF v_status NOT IN ('draft','changes_requested') THEN RAISE EXCEPTION 'owner location edits not allowed in %', v_status; END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_actor_user_id AND role::text IN ('admin','super_admin')) THEN
      RAISE EXCEPTION 'actor is not an admin';
    END IF;
  END IF;

  v_lat := (p_location->>'latitude')::double precision;
  v_lng := (p_location->>'longitude')::double precision;
  v_cc  := p_location->>'country_code';
  IF v_lat IS NULL OR v_lng IS NULL
     OR v_lat <> v_lat OR v_lng <> v_lng
     OR v_lat < -90 OR v_lat > 90 OR v_lng < -180 OR v_lng > 180 THEN
    RAISE EXCEPTION 'invalid final coordinates';
  END IF;
  IF v_cc IS DISTINCT FROM 'IN' THEN RAISE EXCEPTION 'country_code must be IN'; END IF;

  v_in_name  := NULLIF(btrim(COALESCE(p_location->>'building_name','')), '');
  v_in_src   := p_location->>'building_name_source';
  v_in_place := NULLIF(btrim(COALESCE(p_location->>'place_id','')), '');
  IF v_ex_src = 'admin' AND p_actor_type = 'owner' THEN
    v_final_name := v_ex_name; v_final_src := v_ex_src; v_final_place := v_ex_place;
  ELSE
    IF v_in_src = 'admin' AND p_actor_type <> 'admin' THEN
      RAISE EXCEPTION 'owner cannot set admin building source';
    END IF;
    IF v_in_src = 'google' AND v_in_place IS NULL THEN
      RAISE EXCEPTION 'google building source requires provider place_id evidence';
    END IF;
    IF v_in_src IS NOT NULL AND v_in_src NOT IN ('google','owner','admin') THEN
      RAISE EXCEPTION 'invalid building_name_source %', v_in_src;
    END IF;
    v_final_name  := v_in_name;
    v_final_src   := CASE WHEN v_in_name IS NULL THEN NULL ELSE v_in_src END;
    v_final_place := v_in_place;
  END IF;
  v_address_mode := CASE WHEN v_final_place IS NOT NULL THEN 'google_place' ELSE 'manual' END;

  v_sv_available := COALESCE((p_streetview->>'available')::boolean, false);
  v_sv_pano := p_streetview->>'pano_id';

  PERFORM set_config('reeve.system_action', 'geo_apply_v2', true);

  UPDATE public.properties SET
    latitude = v_lat, longitude = v_lng,
    formatted_address = p_location->>'formatted_address',
    city = p_location->>'city', locality = p_location->>'locality',
    street_address = p_location->>'street_address', street_number = p_location->>'street_number',
    route = p_location->>'route',
    sublocality_1 = p_location->>'sublocality_1', sublocality_2 = p_location->>'sublocality_2',
    neighborhood = p_location->>'neighborhood',
    district = p_location->>'district', state = p_location->>'state', pincode = p_location->>'pincode',
    plus_code = p_location->>'plus_code',
    country = p_location->>'country', country_code = 'IN',
    viewport_ne_lat = (p_location->>'viewport_ne_lat')::double precision,
    viewport_ne_lng = (p_location->>'viewport_ne_lng')::double precision,
    viewport_sw_lat = (p_location->>'viewport_sw_lat')::double precision,
    viewport_sw_lng = (p_location->>'viewport_sw_lng')::double precision,
    place_id = v_final_place,
    building_name = v_final_name,
    building_name_source = v_final_src,
    address_mode = v_address_mode,
    location_verified_by_owner = (p_actor_type = 'owner'),
    location_verified_at = CASE WHEN p_actor_type = 'owner' THEN now() ELSE NULL END,
    location_confirmed_at = now(),
    streetview_available = v_sv_available,
    streetview_pano_id = CASE WHEN v_sv_available THEN v_sv_pano ELSE NULL END,
    streetview_checked_at = now(),
    streetview_show_in_listing = CASE WHEN p_streetview ? 'show_in_listing'
                                      THEN (p_streetview->>'show_in_listing')::boolean
                                      ELSE streetview_show_in_listing END,
    owner_pin_adjusted_at =
      CASE
        WHEN p_location ? 'owner_pin_adjusted_at'
        THEN (p_location->>'owner_pin_adjusted_at')::timestamptz
        ELSE owner_pin_adjusted_at
      END,
    owner_pin_adjustment_distance_m =
      CASE
        WHEN p_location ? 'owner_pin_adjustment_distance_m'
        THEN (p_location->>'owner_pin_adjustment_distance_m')::numeric
        ELSE owner_pin_adjustment_distance_m
      END
  WHERE id = p_property_id;

  PERFORM public.replace_property_discovery_geography(p_property_id, COALESCE(p_final_associations, '[]'::jsonb));
END;
$$;


ALTER FUNCTION "public"."apply_final_property_location"("p_property_id" "uuid", "p_actor_user_id" "uuid", "p_actor_type" "text", "p_location" "jsonb", "p_final_associations" "jsonb", "p_streetview" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_final_property_location"("p_property_id" "uuid", "p_actor_user_id" "uuid", "p_actor_type" "text", "p_location" "jsonb", "p_final_associations" "jsonb", "p_streetview" "jsonb") IS 'Phase-2 atomic trusted commit: final pin + factual/admin + building identity + Street View + FINAL Discovery associations (composes replace_property_discovery_geography) + lifecycle reset. Service-role only. Actor-validated; enforces IN + coord + building-provenance invariants; location_confirmed_at derived server-side.';



CREATE OR REPLACE FUNCTION "public"."approve_edit_request"("p_edit_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_admin_id uuid := (SELECT auth.uid());
  v_property_id uuid;
  v_status text;
  v_payload jsonb;
  v_clean jsonb;
  v_base jsonb;
  v_photo_add jsonb;
  p_row public.properties%ROWTYPE;
  v_new_amenities jsonb;
  v_new_fd jsonb;
  v_changed_keys jsonb;
  k text;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  SELECT property_id, status, payload INTO v_property_id, v_status, v_payload
    FROM public.property_edit_requests WHERE id = p_edit_request_id FOR UPDATE;
  IF v_property_id IS NULL THEN RAISE EXCEPTION 'Edit request not found'; END IF;
  IF v_status <> 'pending' THEN RAISE EXCEPTION 'Edit request is no longer pending (current: %)', v_status; END IF;

  v_clean := COALESCE(v_payload->'field_changes', '{}'::jsonb);
  v_base := COALESCE(v_payload->'base_values', '{}'::jsonb);
  v_photo_add := COALESCE(v_payload->'photo_changes'->'add', '[]'::jsonb);

  SELECT * INTO p_row FROM public.properties WHERE id = v_property_id FOR UPDATE;

  FOR k IN SELECT jsonb_object_keys(v_base) LOOP
    IF COALESCE((CASE k
          WHEN 'building_notes' THEN to_jsonb(p_row.building_notes)
          WHEN 'building_rules' THEN to_jsonb(p_row.building_rules)
          WHEN 'parking_notes' THEN to_jsonb(p_row.parking_notes)
          WHEN 'rera_registration_number' THEN to_jsonb(p_row.rera_registration_number)
          WHEN 'youtube_walkthrough_url' THEN to_jsonb(p_row.youtube_walkthrough_url)
          WHEN 'bhk' THEN to_jsonb(p_row.bhk::text)
          WHEN 'property_type' THEN to_jsonb(p_row.property_type) END), 'null'::jsonb)
       IS DISTINCT FROM COALESCE((v_base->k), 'null'::jsonb) THEN
      RAISE EXCEPTION 'stale: field % changed since submission, resubmit', k;
    END IF;
  END LOOP;

  IF v_clean ? 'amenities_building_add' THEN
    SELECT jsonb_set(COALESCE(p_row.amenities, '{}'::jsonb), '{building}',
      (SELECT COALESCE(jsonb_agg(DISTINCT v), '[]'::jsonb) FROM (
         SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(p_row.amenities->'building')='array' THEN p_row.amenities->'building' ELSE '[]'::jsonb END) v
         UNION SELECT jsonb_array_elements_text(v_clean->'amenities_building_add') v) s), true)
      INTO v_new_amenities;
  ELSE v_new_amenities := p_row.amenities; END IF;

  IF v_clean ? 'furnishing_detail_add' THEN
    SELECT COALESCE(jsonb_agg(elem ORDER BY ord), '[]'::jsonb) INTO v_new_fd
    FROM (SELECT elem, ord, row_number() OVER (PARTITION BY lower(btrim(elem->>'item')) ORDER BY ord) rn
      FROM (SELECT e AS elem, 0 AS ord FROM jsonb_array_elements(COALESCE(p_row.furnishing_detail,'[]'::jsonb)) e
            UNION ALL SELECT e AS elem, 1 AS ord FROM jsonb_array_elements(v_clean->'furnishing_detail_add') e) u) d
    WHERE rn = 1;
  ELSE v_new_fd := p_row.furnishing_detail; END IF;

  UPDATE public.properties SET
    building_notes = CASE WHEN v_clean ? 'building_notes' THEN v_clean->>'building_notes' ELSE building_notes END,
    building_rules = CASE WHEN v_clean ? 'building_rules' THEN v_clean->>'building_rules' ELSE building_rules END,
    parking_notes = CASE WHEN v_clean ? 'parking_notes' THEN v_clean->>'parking_notes' ELSE parking_notes END,
    rera_registration_number = CASE WHEN v_clean ? 'rera_registration_number' THEN v_clean->>'rera_registration_number' ELSE rera_registration_number END,
    youtube_walkthrough_url = CASE WHEN v_clean ? 'youtube_walkthrough_url' THEN v_clean->>'youtube_walkthrough_url' ELSE youtube_walkthrough_url END,
    bhk = CASE WHEN v_clean ? 'bhk' THEN (v_clean->>'bhk')::bhk_type ELSE bhk END,
    property_type = CASE WHEN v_clean ? 'property_type' THEN v_clean->>'property_type' ELSE property_type END,
    amenities = v_new_amenities,
    furnishing_detail = v_new_fd,
    status = 'listed'
  WHERE id = v_property_id;

  IF jsonb_array_length(v_photo_add) > 0 THEN
    INSERT INTO public.property_images (property_id, uploaded_by, url, section, caption, is_primary, is_floor_plan, sort_order)
    SELECT v_property_id, v_admin_id, d.url, d.section, d.caption, false, d.is_floor_plan, d.sort_order
    FROM (
      SELECT DISTINCT ON ((elem->>'url'))
        (elem->>'url')::text AS url,
        NULLIF(elem->>'section','') AS section,
        NULLIF(elem->>'caption','') AS caption,
        COALESCE((elem->>'is_floor_plan')::boolean, false) AS is_floor_plan,
        COALESCE((elem->>'sort_order')::integer, 0) AS sort_order
      FROM jsonb_array_elements(v_photo_add) AS elem
      ORDER BY (elem->>'url'), COALESCE((elem->>'sort_order')::integer, 0)
    ) d
    WHERE NOT EXISTS (
      SELECT 1 FROM public.property_images pi
      WHERE pi.property_id = v_property_id AND pi.url = d.url
    );
  END IF;

  UPDATE public.property_edit_requests SET status = 'approved', reviewed_by = v_admin_id, reviewed_at = now() WHERE id = p_edit_request_id;

  v_changed_keys := (SELECT jsonb_agg(kk) FROM jsonb_object_keys(v_clean) AS kk);
  INSERT INTO public.property_activity_log (property_id, actor_id, actor_role, action, payload, is_public)
  VALUES (v_property_id, v_admin_id, 'admin', 'edit_approved',
    jsonb_build_object('summary','Your edit was approved','edit_request_id', p_edit_request_id::text,
      'admin_id', v_admin_id::text, 'changed_field_keys', COALESCE(v_changed_keys, '[]'::jsonb)), false);
END;
$$;


ALTER FUNCTION "public"."approve_edit_request"("p_edit_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_cancel_requests_on_archive"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only fire when transitioning INTO archived (not on repeated updates while archived)
  IF NEW.status = 'archived' AND OLD.status <> 'archived' THEN
    UPDATE public.contact_requests
    SET
      status            = 'auto_cancelled',
      auto_cancelled_at = now(),
      updated_at        = now()
    WHERE property_id = NEW.id
      AND status      = 'pending';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_cancel_requests_on_archive"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."auto_cancel_requests_on_archive"() IS 'AFTER UPDATE on properties. When a property transitions to archived, all pending contact_requests for that property are set to auto_cancelled. Only pending requests are cancelled — approved requests are left intact (both parties already have contact details). unlisted, changes_requested, edit_pending_review do NOT trigger this — those are temporary states; requests survive with contextual UI messaging.';



CREATE OR REPLACE FUNCTION "public"."cancel_pending_edit_request"("p_property_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_owner_id        uuid;
  v_edit_request_id uuid;
  v_caller          uuid := (SELECT auth.uid());
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT owner_id INTO v_owner_id
    FROM public.properties
   WHERE id = p_property_id
   FOR UPDATE;

  IF v_owner_id IS NULL THEN
    RAISE EXCEPTION 'Property not found';
  END IF;

  IF v_owner_id <> v_caller AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT id INTO v_edit_request_id
    FROM public.property_edit_requests
   WHERE property_id = p_property_id AND status = 'pending'
   FOR UPDATE;

  IF v_edit_request_id IS NULL THEN
    RAISE EXCEPTION 'No pending edit found';
  END IF;

  UPDATE public.property_edit_requests
     SET status = 'withdrawn'
   WHERE id = v_edit_request_id;

  UPDATE public.properties
     SET status = 'listed'
   WHERE id = p_property_id
     AND status = 'edit_pending_review';

  INSERT INTO public.property_activity_log
    (property_id, actor_id, actor_role, action, payload, is_public)
  VALUES (
    p_property_id,
    v_caller,
    'owner',
    'edit_resolved',
    jsonb_build_object(
      'summary',         'You cancelled your pending edit',
      'edit_request_id', v_edit_request_id::text
    ),
    false
  );
END;
$$;


ALTER FUNCTION "public"."cancel_pending_edit_request"("p_property_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_contact_request_limits"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  decided_count    integer;
  last_declined_at timestamptz;
  cooldown_until   timestamptz;
BEGIN
  -- ── 1. Count only owner-declined attempts (only these burn the counter) ────
  -- withdrawn and auto_cancelled are excluded — they are free retries.
  SELECT COUNT(*) INTO decided_count
  FROM contact_requests
  WHERE tenant_id   = NEW.tenant_id
    AND property_id = NEW.property_id
    AND status      = 'declined';

  IF decided_count >= 3 THEN
    RAISE EXCEPTION 'Maximum contact requests reached for this property';
  END IF;

  -- ── 2. Enforce 24h cooldown after each decline ────────────────────────────
  SELECT declined_at INTO last_declined_at
  FROM contact_requests
  WHERE tenant_id   = NEW.tenant_id
    AND property_id = NEW.property_id
    AND status      = 'declined'
  ORDER BY declined_at DESC NULLS LAST
  LIMIT 1;

  IF last_declined_at IS NOT NULL THEN
    cooldown_until := last_declined_at + interval '24 hours';
    IF now() < cooldown_until THEN
      RAISE EXCEPTION 'Contact request not allowed until %', cooldown_until;
    END IF;
  END IF;

  -- ── 3. Auto-set attempt_number (client value is ignored) ─────────────────
  -- Count all non-free rows to derive next attempt number.
  -- Free rows: withdrawn and auto_cancelled (do not count).
  SELECT COUNT(*) + 1 INTO NEW.attempt_number
  FROM contact_requests
  WHERE tenant_id   = NEW.tenant_id
    AND property_id = NEW.property_id
    AND status NOT IN ('withdrawn', 'auto_cancelled');

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_contact_request_limits"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_contact_request_limits"() IS 'BEFORE INSERT trigger on contact_requests. Enforces 3-attempt max (only declined burns an attempt), 24h flat cooldown after each decline, and auto-sets attempt_number. Adapted from check_application_limits() — semantics intentionally differ: withdrawn/auto_cancelled are free retries; there is no accepted-as-terminal equivalent.';



CREATE OR REPLACE FUNCTION "public"."confirm_availability_of_rental"("p_property_id" "uuid") RETURNS TABLE("property_id" "uuid", "confirmed_at" timestamp with time zone, "next_confirmation_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_prop record; v_caller_id uuid := auth.uid(); v_confirmed_at timestamptz; v_effective timestamptz;
BEGIN
  IF v_caller_id IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING DETAIL = 'You must be signed in to confirm availability.'; END IF;
  SELECT p.id, p.owner_id, p.listing_type, p.is_active, p.status, p.availability_confirmed_at, p.current_listed_period_started_at, p.listed_at
  INTO v_prop FROM public.properties p WHERE p.id = p_property_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING DETAIL = 'Property not found.'; END IF;
  IF v_prop.owner_id != v_caller_id THEN RAISE EXCEPTION 'not_owner' USING DETAIL = 'Only the property owner can confirm availability.'; END IF;
  IF v_prop.listing_type != 'rent' THEN RAISE EXCEPTION 'not_rental' USING DETAIL = 'Availability confirmation applies to rental listings only.'; END IF;
  IF NOT v_prop.is_active THEN RAISE EXCEPTION 'not_active' USING DETAIL = 'Property must be active to confirm availability.'; END IF;
  IF v_prop.status NOT IN ('listed', 'edit_pending_review') THEN RAISE EXCEPTION 'not_listed' USING DETAIL = 'Property must be publicly listed to confirm availability.'; END IF;
  v_effective := COALESCE(v_prop.availability_confirmed_at, v_prop.current_listed_period_started_at, v_prop.listed_at);
  IF v_effective IS NOT NULL AND now() < v_effective + interval '7 days' THEN
    RAISE EXCEPTION 'cooldown_active' USING DETAIL = format('Next confirmation available at %s.', to_char(v_effective + interval '7 days', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  END IF;
  PERFORM set_config('reeve.system_action', 'confirm_rent', true);
  UPDATE public.properties SET availability_confirmed_at = now() WHERE id = p_property_id RETURNING availability_confirmed_at INTO v_confirmed_at;
  INSERT INTO public.property_activity_log (property_id, actor_id, actor_role, action, payload, is_public)
  VALUES (p_property_id, v_caller_id, 'owner', 'availability_confirmed', jsonb_build_object('summary', 'You confirmed this rental is still available'), false);
  RETURN QUERY SELECT p_property_id, v_confirmed_at, v_confirmed_at + interval '7 days';
END; $$;


ALTER FUNCTION "public"."confirm_availability_of_rental"("p_property_id" "uuid") OWNER TO "postgres";


