CREATE OR REPLACE FUNCTION "public"."confirm_sale_listing"("p_property_id" "uuid") RETURNS TABLE("property_id" "uuid", "confirmed_at" timestamp with time zone, "next_confirmation_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_prop record; v_caller_id uuid := auth.uid(); v_confirmed_at timestamptz; v_effective timestamptz;
BEGIN
  IF v_caller_id IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING DETAIL = 'You must be signed in to confirm your listing.'; END IF;
  SELECT p.id, p.owner_id, p.listing_type, p.is_active, p.status, p.sale_listing_confirmed_at, p.current_listed_period_started_at, p.listed_at
  INTO v_prop FROM public.properties p WHERE p.id = p_property_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING DETAIL = 'Property not found.'; END IF;
  IF v_prop.owner_id != v_caller_id THEN RAISE EXCEPTION 'not_owner' USING DETAIL = 'Only the property owner can confirm this listing.'; END IF;
  IF v_prop.listing_type != 'sale' THEN RAISE EXCEPTION 'not_sale' USING DETAIL = 'Sale-listing confirmation applies to sale listings only.'; END IF;
  IF NOT v_prop.is_active THEN RAISE EXCEPTION 'not_active' USING DETAIL = 'Property must be active to confirm the listing.'; END IF;
  IF v_prop.status NOT IN ('listed', 'edit_pending_review') THEN RAISE EXCEPTION 'not_listed' USING DETAIL = 'Property must be publicly listed to confirm the listing.'; END IF;
  v_effective := COALESCE(v_prop.sale_listing_confirmed_at, v_prop.current_listed_period_started_at, v_prop.listed_at);
  IF v_effective IS NOT NULL AND now() < v_effective + interval '15 days' THEN
    RAISE EXCEPTION 'cooldown_active' USING DETAIL = format('Next confirmation available at %s.', to_char(v_effective + interval '15 days', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  END IF;
  PERFORM set_config('reeve.system_action', 'confirm_sale', true);
  UPDATE public.properties SET sale_listing_confirmed_at = now() WHERE id = p_property_id RETURNING sale_listing_confirmed_at INTO v_confirmed_at;
  INSERT INTO public.property_activity_log (property_id, actor_id, actor_role, action, payload, is_public)
  VALUES (p_property_id, v_caller_id, 'owner', 'sale_listing_confirmed', jsonb_build_object('summary', 'You confirmed this sale listing is still available'), false);
  RETURN QUERY SELECT p_property_id, v_confirmed_at, v_confirmed_at + interval '15 days';
END; $$;


ALTER FUNCTION "public"."confirm_sale_listing"("p_property_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_own_comment"("p_comment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_comment  public.property_comments;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  SELECT * INTO v_comment
  FROM public.property_comments
  WHERE id = p_comment_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'COMMENT_NOT_FOUND';
  END IF;

  IF v_comment.user_id != v_user_id THEN
    RAISE EXCEPTION 'NOT_YOUR_COMMENT';
  END IF;

  IF v_comment.is_deleted THEN
    RAISE EXCEPTION 'ALREADY_DELETED';
  END IF;

  UPDATE public.property_comments
  SET is_deleted    = true,
      hidden_reason = 'user_deleted'
  WHERE id = p_comment_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."delete_own_comment"("p_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_property_photo"("p_image_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := (SELECT auth.uid());
  v_prop_id uuid; v_owner uuid; v_status property_status; v_is_admin boolean := public.is_admin();
  v_was_primary boolean; v_total integer; v_next_id uuid;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT pi.property_id, p.owner_id, p.status, pi.is_primary INTO v_prop_id, v_owner, v_status, v_was_primary
    FROM public.property_images pi JOIN public.properties p ON p.id = pi.property_id
    WHERE pi.id = p_image_id FOR UPDATE OF p;
  IF v_prop_id IS NULL THEN RAISE EXCEPTION 'Image not found'; END IF;
  IF v_owner <> v_caller AND NOT v_is_admin THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF NOT v_is_admin AND v_status NOT IN ('listed','edit_pending_review') THEN
    RAISE EXCEPTION 'Photo deletion is not allowed in % status', v_status;
  END IF;
  SELECT COUNT(*) INTO v_total FROM public.property_images WHERE property_id = v_prop_id;
  IF NOT v_is_admin AND (v_total - 1) < 3 THEN RAISE EXCEPTION 'At least 3 photos required — cannot delete'; END IF;
  PERFORM set_config('reeve.system_action', 'photo_op', true);
  DELETE FROM public.property_images WHERE id = p_image_id;
  IF v_was_primary THEN
    SELECT id INTO v_next_id FROM public.property_images WHERE property_id = v_prop_id ORDER BY sort_order ASC, created_at ASC LIMIT 1;
    IF v_next_id IS NOT NULL THEN UPDATE public.property_images SET is_primary = true WHERE id = v_next_id; END IF;
  END IF;
END;
$$;


ALTER FUNCTION "public"."delete_property_photo"("p_image_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_building_name_source_provenance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF public.is_admin() OR COALESCE(current_setting('reeve.system_action', true), '') <> '' THEN
    RETURN NEW;
  END IF;
  IF NEW.building_name_source IS NOT NULL AND NEW.building_name_source <> 'owner' THEN
    IF TG_OP = 'INSERT' OR NEW.building_name_source IS DISTINCT FROM OLD.building_name_source THEN
      RAISE EXCEPTION 'building_name_source % requires the trusted/admin path', NEW.building_name_source;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_building_name_source_provenance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_canonical_location_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF COALESCE(current_setting('reeve.system_action', true), '') <> '' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.place_id IS NOT NULL OR NEW.formatted_address IS NOT NULL
       OR NEW.latitude IS NOT NULL OR NEW.longitude IS NOT NULL
       OR NEW.geom_exact IS NOT NULL
       OR NEW.address_mode IS NOT NULL OR NEW.city IS NOT NULL OR NEW.locality IS NOT NULL
       OR NEW.street_address IS NOT NULL OR NEW.street_number IS NOT NULL OR NEW.route IS NOT NULL
       OR NEW.sublocality_1 IS NOT NULL OR NEW.sublocality_2 IS NOT NULL OR NEW.neighborhood IS NOT NULL
       OR NEW.district IS NOT NULL OR NEW.state IS NOT NULL OR NEW.pincode IS NOT NULL OR NEW.plus_code IS NOT NULL
       OR NEW.country_code IS NOT NULL
       OR NEW.viewport_ne_lat IS NOT NULL OR NEW.viewport_ne_lng IS NOT NULL
       OR NEW.viewport_sw_lat IS NOT NULL OR NEW.viewport_sw_lng IS NOT NULL
       OR NEW.building_name IS NOT NULL OR NEW.building_name_source IS NOT NULL
       OR NEW.location_verified_by_owner IS TRUE OR NEW.location_verified_at IS NOT NULL
       OR NEW.location_confirmed_at IS NOT NULL OR NEW.discovery_confirmed_at IS NOT NULL
       OR NEW.discovery_finalized_at IS NOT NULL THEN
      RAISE EXCEPTION 'canonical location must be set via the trusted location flow';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.place_id IS DISTINCT FROM OLD.place_id
     OR NEW.formatted_address IS DISTINCT FROM OLD.formatted_address
     OR NEW.latitude IS DISTINCT FROM OLD.latitude OR NEW.longitude IS DISTINCT FROM OLD.longitude
     OR NEW.geom_exact IS DISTINCT FROM OLD.geom_exact
     OR NEW.address_mode IS DISTINCT FROM OLD.address_mode
     OR NEW.city IS DISTINCT FROM OLD.city OR NEW.locality IS DISTINCT FROM OLD.locality
     OR NEW.street_address IS DISTINCT FROM OLD.street_address
     OR NEW.street_number IS DISTINCT FROM OLD.street_number OR NEW.route IS DISTINCT FROM OLD.route
     OR NEW.sublocality_1 IS DISTINCT FROM OLD.sublocality_1 OR NEW.sublocality_2 IS DISTINCT FROM OLD.sublocality_2
     OR NEW.neighborhood IS DISTINCT FROM OLD.neighborhood OR NEW.district IS DISTINCT FROM OLD.district
     OR NEW.state IS DISTINCT FROM OLD.state OR NEW.pincode IS DISTINCT FROM OLD.pincode
     OR NEW.plus_code IS DISTINCT FROM OLD.plus_code
     OR NEW.country_code IS DISTINCT FROM OLD.country_code
     OR NEW.viewport_ne_lat IS DISTINCT FROM OLD.viewport_ne_lat OR NEW.viewport_ne_lng IS DISTINCT FROM OLD.viewport_ne_lng
     OR NEW.viewport_sw_lat IS DISTINCT FROM OLD.viewport_sw_lat OR NEW.viewport_sw_lng IS DISTINCT FROM OLD.viewport_sw_lng
     OR NEW.building_name IS DISTINCT FROM OLD.building_name
     OR NEW.building_name_source IS DISTINCT FROM OLD.building_name_source
     OR NEW.location_verified_by_owner IS DISTINCT FROM OLD.location_verified_by_owner
     OR NEW.location_verified_at IS DISTINCT FROM OLD.location_verified_at
     OR NEW.location_confirmed_at IS DISTINCT FROM OLD.location_confirmed_at
     OR NEW.discovery_confirmed_at IS DISTINCT FROM OLD.discovery_confirmed_at
     OR NEW.discovery_finalized_at IS DISTINCT FROM OLD.discovery_finalized_at THEN
    RAISE EXCEPTION 'canonical location must be changed via the trusted location flow';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_canonical_location_lock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_geo_association_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_kind text;
  v_secondary_count int;
BEGIN
  SELECT kind INTO v_kind FROM public.geo_places WHERE id = NEW.geo_place_id;
  IF v_kind IS NULL THEN
    RAISE EXCEPTION 'geo_place % does not exist', NEW.geo_place_id;
  END IF;

  IF NEW.relationship IS NOT NULL THEN
    IF NEW.relationship IN ('primary_city','secondary_city') AND v_kind NOT IN ('city','search_region','settlement') THEN
      RAISE EXCEPTION 'relationship % requires city/search_region/settlement, got kind %', NEW.relationship, v_kind;
    END IF;
    IF NEW.relationship = 'area_road' AND v_kind NOT IN ('area','locality','road') THEN
      RAISE EXCEPTION 'relationship area_road requires area/locality/road, got kind %', v_kind;
    END IF;
    IF NEW.relationship = 'secondary_city' THEN
      SELECT count(*) INTO v_secondary_count
      FROM public.property_geo_associations
      WHERE property_id = NEW.property_id AND relationship = 'secondary_city' AND id <> NEW.id;
      IF v_secondary_count >= 2 THEN
        RAISE EXCEPTION 'At most 2 secondary cities per property';
      END IF;
    END IF;
    NEW.is_primary := (NEW.relationship = 'primary_city');
    RETURN NEW;
  END IF;

  IF v_kind NOT IN ('search_region','settlement','locality','road') THEN
    RAISE EXCEPTION 'final association requires a final kind, got %', v_kind;
  END IF;
  IF NEW.source NOT IN ('system','owner','admin') THEN
    RAISE EXCEPTION 'final association source must be system/owner/admin, got %', NEW.source;
  END IF;
  IF NEW.evidence_type IS NULL THEN
    RAISE EXCEPTION 'final association requires evidence_type';
  END IF;
  IF NEW.is_primary AND v_kind NOT IN ('search_region','settlement') THEN
    RAISE EXCEPTION 'primary association must be search_region/settlement, got %', v_kind;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_geo_association_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_geo_place_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_tol double precision := 0.000001;
  v_center_changed boolean;
  v_rep_changed boolean;
BEGIN
  IF NEW.display_name IS NOT NULL THEN
    NEW.normalized_name := lower(btrim(NEW.display_name));
  END IF;

  IF (NEW.center_lat IS NULL) <> (NEW.center_lng IS NULL) THEN
    RAISE EXCEPTION 'geo_places center_lat/center_lng must both be set or both null';
  END IF;
  IF NEW.center_lat IS NOT NULL AND (NEW.center_lat < -90 OR NEW.center_lat > 90) THEN
    RAISE EXCEPTION 'center_lat % out of range', NEW.center_lat;
  END IF;
  IF NEW.center_lng IS NOT NULL AND (NEW.center_lng < -180 OR NEW.center_lng > 180) THEN
    RAISE EXCEPTION 'center_lng % out of range', NEW.center_lng;
  END IF;

  IF NEW.search_region_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.geo_places sr WHERE sr.id = NEW.search_region_id AND sr.kind = 'search_region') THEN
      RAISE EXCEPTION 'search_region_id % must reference a search_region', NEW.search_region_id;
    END IF;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.center_lat IS NOT NULL AND NEW.representative_point IS NULL THEN
      NEW.representative_point := extensions.ST_SetSRID(extensions.ST_MakePoint(NEW.center_lng::float8, NEW.center_lat::float8), 4326);
    ELSIF NEW.center_lat IS NULL AND NEW.representative_point IS NOT NULL THEN
      NEW.center_lat := extensions.ST_Y(NEW.representative_point)::double precision;
      NEW.center_lng := extensions.ST_X(NEW.representative_point)::double precision;
    ELSIF NEW.center_lat IS NOT NULL AND NEW.representative_point IS NOT NULL THEN
      IF abs(extensions.ST_X(NEW.representative_point) - NEW.center_lng::float8) > v_tol
         OR abs(extensions.ST_Y(NEW.representative_point) - NEW.center_lat::float8) > v_tol THEN
        RAISE EXCEPTION 'representative_point inconsistent with center_lat/lng';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  v_center_changed := (NEW.center_lat IS DISTINCT FROM OLD.center_lat) OR (NEW.center_lng IS DISTINCT FROM OLD.center_lng);
  v_rep_changed    := (NEW.representative_point IS DISTINCT FROM OLD.representative_point);

  IF v_center_changed AND v_rep_changed THEN
    IF NEW.center_lat IS NULL AND NEW.representative_point IS NULL THEN
      NULL;
    ELSIF NEW.center_lat IS NOT NULL AND NEW.representative_point IS NULL THEN
      NEW.representative_point := extensions.ST_SetSRID(extensions.ST_MakePoint(NEW.center_lng::float8, NEW.center_lat::float8), 4326);
    ELSIF NEW.center_lat IS NULL AND NEW.representative_point IS NOT NULL THEN
      NEW.center_lat := extensions.ST_Y(NEW.representative_point)::double precision;
      NEW.center_lng := extensions.ST_X(NEW.representative_point)::double precision;
    ELSE
      IF abs(extensions.ST_X(NEW.representative_point) - NEW.center_lng::float8) > v_tol
         OR abs(extensions.ST_Y(NEW.representative_point) - NEW.center_lat::float8) > v_tol THEN
        RAISE EXCEPTION 'representative_point inconsistent with center_lat/lng';
      END IF;
    END IF;
  ELSIF v_center_changed THEN
    IF NEW.center_lat IS NOT NULL THEN
      NEW.representative_point := extensions.ST_SetSRID(extensions.ST_MakePoint(NEW.center_lng::float8, NEW.center_lat::float8), 4326);
    ELSE
      NEW.representative_point := NULL;
    END IF;
  ELSIF v_rep_changed THEN
    IF NEW.representative_point IS NOT NULL THEN
      NEW.center_lat := extensions.ST_Y(NEW.representative_point)::double precision;
      NEW.center_lng := extensions.ST_X(NEW.representative_point)::double precision;
    ELSE
      NEW.center_lat := NULL;
      NEW.center_lng := NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_geo_place_sync"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_owner_edit_partition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  identity_changed boolean;
  live_changed     boolean;
  review_text_add  boolean;
BEGIN
  IF public.is_admin() OR COALESCE(current_setting('reeve.system_action', true), '') <> '' THEN
    RETURN NEW;
  END IF;

  identity_changed := (
    NEW.building_name IS DISTINCT FROM OLD.building_name OR NEW.street_address IS DISTINCT FROM OLD.street_address
    OR NEW.locality IS DISTINCT FROM OLD.locality OR NEW.city IS DISTINCT FROM OLD.city
    OR NEW.state IS DISTINCT FROM OLD.state OR NEW.pincode IS DISTINCT FROM OLD.pincode
    OR NEW.latitude IS DISTINCT FROM OLD.latitude OR NEW.longitude IS DISTINCT FROM OLD.longitude
    OR NEW.place_id IS DISTINCT FROM OLD.place_id OR NEW.formatted_address IS DISTINCT FROM OLD.formatted_address
    OR NEW.address_mode IS DISTINCT FROM OLD.address_mode OR NEW.street_number IS DISTINCT FROM OLD.street_number
    OR NEW.route IS DISTINCT FROM OLD.route OR NEW.sublocality_1 IS DISTINCT FROM OLD.sublocality_1
    OR NEW.sublocality_2 IS DISTINCT FROM OLD.sublocality_2 OR NEW.neighborhood IS DISTINCT FROM OLD.neighborhood
    OR NEW.district IS DISTINCT FROM OLD.district OR NEW.country IS DISTINCT FROM OLD.country
    OR NEW.plus_code IS DISTINCT FROM OLD.plus_code
    OR NEW.viewport_ne_lat IS DISTINCT FROM OLD.viewport_ne_lat OR NEW.viewport_ne_lng IS DISTINCT FROM OLD.viewport_ne_lng
    OR NEW.viewport_sw_lat IS DISTINCT FROM OLD.viewport_sw_lat OR NEW.viewport_sw_lng IS DISTINCT FROM OLD.viewport_sw_lng
    OR NEW.landmark IS DISTINCT FROM OLD.landmark
    OR NEW.legal_owner_name IS DISTINCT FROM OLD.legal_owner_name
    OR NEW.streetview_available IS DISTINCT FROM OLD.streetview_available
    OR NEW.streetview_pano_id IS DISTINCT FROM OLD.streetview_pano_id
    OR NEW.streetview_checked_at IS DISTINCT FROM OLD.streetview_checked_at
    OR NEW.location_verified_by_owner IS DISTINCT FROM OLD.location_verified_by_owner
    OR NEW.location_verified_at IS DISTINCT FROM OLD.location_verified_at
    OR NEW.listing_type IS DISTINCT FROM OLD.listing_type OR NEW.lister_role IS DISTINCT FROM OLD.lister_role
    OR NEW.lister_flat_number IS DISTINCT FROM OLD.lister_flat_number
    OR NEW.google_maps_url IS DISTINCT FROM OLD.google_maps_url
    OR NEW.title IS DISTINCT FROM OLD.title OR NEW.description IS DISTINCT FROM OLD.description
    OR NEW.building_name_source IS DISTINCT FROM OLD.building_name_source
  );

  IF OLD.status NOT IN ('draft', 'changes_requested') AND identity_changed THEN
    RAISE EXCEPTION 'Identity/location and listing-type fields are admin-only after publication';
  END IF;

  IF OLD.status IN ('draft', 'changes_requested') THEN
    RETURN NEW;
  END IF;

  live_changed := (
    NEW.listed_rent IS DISTINCT FROM OLD.listed_rent OR NEW.sale_price IS DISTINCT FROM OLD.sale_price
    OR NEW.price_negotiable IS DISTINCT FROM OLD.price_negotiable
    OR NEW.expected_price_per_sqft IS DISTINCT FROM OLD.expected_price_per_sqft
    OR NEW.security_deposit_amount IS DISTINCT FROM OLD.security_deposit_amount
    OR NEW.security_deposit_months IS DISTINCT FROM OLD.security_deposit_months
    OR NEW.society_maintenance_approx IS DISTINCT FROM OLD.society_maintenance_approx
    OR NEW.maintenance_included_in_rent IS DISTINCT FROM OLD.maintenance_included_in_rent
    OR NEW.move_in_charges_amount IS DISTINCT FROM OLD.move_in_charges_amount
    OR NEW.annual_rent_increase_pct IS DISTINCT FROM OLD.annual_rent_increase_pct
    OR NEW.lock_in_months IS DISTINCT FROM OLD.lock_in_months
    OR NEW.notice_period_days IS DISTINCT FROM OLD.notice_period_days
    OR NEW.notice_period_months IS DISTINCT FROM OLD.notice_period_months
    OR NEW.sale_brokerage_pct IS DISTINCT FROM OLD.sale_brokerage_pct
    OR NEW.rent_brokerage_fixed_amount IS DISTINCT FROM OLD.rent_brokerage_fixed_amount
    OR NEW.rent_brokerage_months IS DISTINCT FROM OLD.rent_brokerage_months
    OR NEW.rent_brokerage_type IS DISTINCT FROM OLD.rent_brokerage_type
    OR NEW.available_from IS DISTINCT FROM OLD.available_from
    OR NEW.possession_status IS DISTINCT FROM OLD.possession_status
    OR NEW.possession_date IS DISTINCT FROM OLD.possession_date
    OR NEW.floor_number IS DISTINCT FROM OLD.floor_number OR NEW.total_floors IS DISTINCT FROM OLD.total_floors
    OR NEW.square_footage IS DISTINCT FROM OLD.square_footage
    OR NEW.super_built_up_area IS DISTINCT FROM OLD.super_built_up_area
    OR NEW.bathrooms IS DISTINCT FROM OLD.bathrooms OR NEW.balconies IS DISTINCT FROM OLD.balconies
    OR NEW.facing IS DISTINCT FROM OLD.facing OR NEW.building_age_years IS DISTINCT FROM OLD.building_age_years
    OR NEW.khata_type IS DISTINCT FROM OLD.khata_type
    OR NEW.property_tax_paid_upto IS DISTINCT FROM OLD.property_tax_paid_upto
    OR NEW.parking_2w IS DISTINCT FROM OLD.parking_2w OR NEW.parking_4w IS DISTINCT FROM OLD.parking_4w
    OR NEW.parking_2w_count IS DISTINCT FROM OLD.parking_2w_count
    OR NEW.parking_4w_count IS DISTINCT FROM OLD.parking_4w_count
    OR NEW.utility_water_included IS DISTINCT FROM OLD.utility_water_included
    OR NEW.utility_gas_included IS DISTINCT FROM OLD.utility_gas_included
    OR NEW.utility_electricity_included IS DISTINCT FROM OLD.utility_electricity_included
    OR NEW.gas_type IS DISTINCT FROM OLD.gas_type OR NEW.water_source IS DISTINCT FROM OLD.water_source
    OR NEW.water_storage IS DISTINCT FROM OLD.water_storage
    OR NEW.main_door_lock_type IS DISTINCT FROM OLD.main_door_lock_type
    OR NEW.furnishing IS DISTINCT FROM OLD.furnishing OR NEW.pet_policy IS DISTINCT FROM OLD.pet_policy
    OR NEW.streetview_show_in_listing IS DISTINCT FROM OLD.streetview_show_in_listing
  );

  review_text_add := (
    (NEW.building_notes IS DISTINCT FROM OLD.building_notes AND btrim(COALESCE(NEW.building_notes,'')) <> '')
    OR (NEW.building_rules IS DISTINCT FROM OLD.building_rules AND btrim(COALESCE(NEW.building_rules,'')) <> '')
    OR (NEW.parking_notes IS DISTINCT FROM OLD.parking_notes AND btrim(COALESCE(NEW.parking_notes,'')) <> '')
    OR (NEW.rera_registration_number IS DISTINCT FROM OLD.rera_registration_number AND btrim(COALESCE(NEW.rera_registration_number,'')) <> '')
    OR (NEW.youtube_walkthrough_url IS DISTINCT FROM OLD.youtube_walkthrough_url AND btrim(COALESCE(NEW.youtube_walkthrough_url,'')) <> '')
  );

  IF OLD.status IN ('pending_review', 'unlisted', 'archived') THEN
    IF OLD.status = NEW.status AND (
      live_changed
      OR NEW.building_notes IS DISTINCT FROM OLD.building_notes
      OR NEW.building_rules IS DISTINCT FROM OLD.building_rules
      OR NEW.parking_notes IS DISTINCT FROM OLD.parking_notes
      OR NEW.rera_registration_number IS DISTINCT FROM OLD.rera_registration_number
      OR NEW.youtube_walkthrough_url IS DISTINCT FROM OLD.youtube_walkthrough_url
      OR NEW.bhk IS DISTINCT FROM OLD.bhk OR NEW.property_type IS DISTINCT FROM OLD.property_type
      OR NEW.amenities IS DISTINCT FROM OLD.amenities
      OR NEW.furnishing_detail IS DISTINCT FROM OLD.furnishing_detail
    ) THEN
      RAISE EXCEPTION 'Property content is frozen in % status', OLD.status;
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status IN ('listed', 'edit_pending_review') THEN
    IF review_text_add THEN
      RAISE EXCEPTION 'This field requires review — submit it via submit_property_edit_request';
    END IF;
    IF NEW.bhk IS DISTINCT FROM OLD.bhk OR NEW.property_type IS DISTINCT FROM OLD.property_type THEN
      RAISE EXCEPTION 'BHK / property type corrections require review';
    END IF;
    IF public.reeve_introduces_new_custom(OLD.furnishing_detail, NEW.furnishing_detail, OLD.amenities, NEW.amenities) THEN
      RAISE EXCEPTION 'New custom furnishing/amenity items require review';
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_owner_edit_partition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_property_geom_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_trusted boolean := COALESCE(current_setting('reeve.system_action', true), '') <> '';
  v_geom_from_latlng extensions.geometry(Point,4326);
  v_tol double precision := 0.000001;
BEGIN
  IF NEW.latitude IS NOT NULL AND (NEW.latitude < -90 OR NEW.latitude > 90) THEN
    RAISE EXCEPTION 'latitude % out of range [-90,90]', NEW.latitude;
  END IF;
  IF NEW.longitude IS NOT NULL AND (NEW.longitude < -180 OR NEW.longitude > 180) THEN
    RAISE EXCEPTION 'longitude % out of range [-180,180]', NEW.longitude;
  END IF;

  IF NEW.latitude IS NOT NULL AND NEW.longitude IS NOT NULL THEN
    v_geom_from_latlng := extensions.ST_SetSRID(
      extensions.ST_MakePoint(NEW.longitude::float8, NEW.latitude::float8), 4326);
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NOT v_trusted THEN
      NEW.geom_exact := v_geom_from_latlng;
    ELSE
      IF NEW.latitude IS NOT NULL AND NEW.geom_exact IS NULL THEN
        NEW.geom_exact := v_geom_from_latlng;
      ELSIF NEW.latitude IS NULL AND NEW.geom_exact IS NOT NULL THEN
        NEW.latitude  := extensions.ST_Y(NEW.geom_exact)::numeric;
        NEW.longitude := extensions.ST_X(NEW.geom_exact)::numeric;
      ELSIF NEW.latitude IS NOT NULL AND NEW.geom_exact IS NOT NULL THEN
        IF abs(extensions.ST_X(NEW.geom_exact) - NEW.longitude::float8) > v_tol
           OR abs(extensions.ST_Y(NEW.geom_exact) - NEW.latitude::float8) > v_tol THEN
          RAISE EXCEPTION 'geom_exact is inconsistent with latitude/longitude on insert';
        END IF;
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF NOT v_trusted THEN
    NEW.geom_exact := v_geom_from_latlng;
  ELSE
    IF NEW.geom_exact IS DISTINCT FROM OLD.geom_exact
       AND NEW.latitude IS NOT DISTINCT FROM OLD.latitude
       AND NEW.longitude IS NOT DISTINCT FROM OLD.longitude THEN
      NEW.latitude  := extensions.ST_Y(NEW.geom_exact)::numeric;
      NEW.longitude := extensions.ST_X(NEW.geom_exact)::numeric;
    ELSIF (NEW.latitude IS DISTINCT FROM OLD.latitude OR NEW.longitude IS DISTINCT FROM OLD.longitude)
          AND NEW.geom_exact IS NOT DISTINCT FROM OLD.geom_exact THEN
      NEW.geom_exact := v_geom_from_latlng;
    ELSIF (NEW.latitude IS DISTINCT FROM OLD.latitude OR NEW.longitude IS DISTINCT FROM OLD.longitude)
          AND NEW.geom_exact IS DISTINCT FROM OLD.geom_exact THEN
      IF v_geom_from_latlng IS NULL AND NEW.geom_exact IS NULL THEN
        NULL;
      ELSIF v_geom_from_latlng IS NULL OR NEW.geom_exact IS NULL
            OR abs(extensions.ST_X(NEW.geom_exact) - NEW.longitude::float8) > v_tol
            OR abs(extensions.ST_Y(NEW.geom_exact) - NEW.latitude::float8) > v_tol THEN
        RAISE EXCEPTION 'geom_exact is inconsistent with latitude/longitude on update';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_property_geom_sync"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_property_image_policy"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status_new property_status;
  v_status_old property_status;
BEGIN
  IF public.is_admin() OR COALESCE(current_setting('reeve.system_action', true), '') <> '' THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF TG_OP = 'INSERT' THEN
    SELECT status INTO v_status_new FROM public.properties WHERE id = NEW.property_id;
    IF v_status_new IN ('pending_review','listed','edit_pending_review','unlisted','archived') THEN
      RAISE EXCEPTION 'New photos on a % listing must go through review', v_status_new;
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    SELECT status INTO v_status_old FROM public.properties WHERE id = OLD.property_id;
    IF v_status_old IN ('pending_review','listed','edit_pending_review','unlisted','archived') THEN
      RAISE EXCEPTION 'Use delete_property_photo to remove photos from a % listing', v_status_old;
    END IF;
    RETURN OLD;
  ELSE
    IF OLD.property_id IS DISTINCT FROM NEW.property_id THEN
      RAISE EXCEPTION 'Cannot move an image between properties';
    END IF;
    SELECT status INTO v_status_old FROM public.properties WHERE id = OLD.property_id;
    IF v_status_old IN ('listed','edit_pending_review') THEN
      IF NEW.url IS DISTINCT FROM OLD.url
         OR NEW.thumbnail_url IS DISTINCT FROM OLD.thumbnail_url
         OR NEW.caption IS DISTINCT FROM OLD.caption
         OR NEW.is_floor_plan IS DISTINCT FROM OLD.is_floor_plan
         OR NEW.is_primary IS DISTINCT FROM OLD.is_primary
         OR NEW.section IS DISTINCT FROM OLD.section
         OR NEW.uploaded_by IS DISTINCT FROM OLD.uploaded_by THEN
        RAISE EXCEPTION 'On a live listing only photo order may change directly; use set_primary_property_photo for the cover';
      END IF;
      RETURN NEW;
    ELSIF v_status_old IN ('pending_review','unlisted','archived') THEN
      RAISE EXCEPTION 'Photos are frozen in % status', v_status_old;
    END IF;
    RETURN NEW;
  END IF;
END;
$$;


ALTER FUNCTION "public"."enforce_property_image_policy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_property_owner_transitions"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  photo_count integer;
  draft_count integer;
BEGIN
  IF public.is_admin() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'draft' THEN
      SELECT COUNT(*) INTO draft_count
        FROM public.properties
       WHERE owner_id = NEW.owner_id AND status = 'draft';
      IF draft_count >= 20 THEN
        RAISE EXCEPTION 'Draft limit reached: 20 properties in draft status per owner';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status IS DISTINCT FROM NEW.status THEN
    IF NOT (
      (OLD.status = 'draft'               AND NEW.status IN ('pending_review', 'archived'))
      OR (OLD.status = 'pending_review'   AND NEW.status IN ('draft', 'archived'))
      OR (OLD.status = 'changes_requested' AND NEW.status IN ('pending_review', 'archived'))
      OR (OLD.status = 'listed'           AND NEW.status IN ('edit_pending_review', 'unlisted', 'archived'))
      OR (OLD.status = 'edit_pending_review' AND NEW.status IN ('listed', 'archived'))
      OR (OLD.status = 'unlisted'         AND NEW.status IN ('listed', 'archived'))
    ) THEN
      RAISE EXCEPTION 'Owner cannot transition property from % to %', OLD.status, NEW.status;
    END IF;

    IF NEW.status = 'pending_review' THEN
      IF NEW.bhk IS NULL THEN
        RAISE EXCEPTION 'location_not_ready:bhk_missing';
      END IF;

      -- Building-by-type (single authoritative rule; applies to the FINAL location branch below).
      IF NEW.property_type IN ('apartment','duplex_apartment')
         AND NULLIF(btrim(COALESCE(NEW.building_name,'')),'') IS NULL THEN
        RAISE EXCEPTION 'location_not_ready:building_name_required';
      END IF;

      -- FINAL canonical location contract (legacy branch removed — M3).
      IF NOT (
        NEW.geom_exact IS NOT NULL
        AND NEW.location_confirmed_at IS NOT NULL
        AND NEW.country_code = 'IN'
        AND NEW.location_verified_by_owner IS TRUE
        AND NEW.discovery_confirmed_at IS NOT NULL
        AND NEW.address_mode IN ('google_place','manual')
        AND (
          SELECT count(*)
            FROM public.property_geo_associations a
            JOIN public.geo_places g ON g.id = a.geo_place_id
           WHERE a.property_id = NEW.id
             AND a.is_primary IS TRUE
             AND a.relationship IS NULL
             AND g.kind IN ('settlement','search_region')
        ) = 1
      ) THEN
        RAISE EXCEPTION 'location_not_ready:location_incomplete';
      END IF;

      IF NEW.listing_type = 'sale' THEN
        IF NEW.sale_price IS NULL OR NEW.possession_status IS NULL THEN
          RAISE EXCEPTION 'Cannot submit for review (sale): required fields missing (sale_price, possession_status)';
        END IF;
        IF NEW.possession_status = 'under_construction' AND NEW.possession_date IS NULL THEN
          RAISE EXCEPTION 'Cannot submit for review (sale): possession_date required when possession_status is under_construction';
        END IF;
      ELSE
        IF NEW.listed_rent IS NULL OR NEW.security_deposit_amount IS NULL OR NEW.furnishing IS NULL OR NEW.available_from IS NULL THEN
          RAISE EXCEPTION 'Cannot submit for review (rent): required fields missing (listed_rent, security_deposit_amount, furnishing, available_from)';
        END IF;
      END IF;

      SELECT COUNT(*) INTO photo_count FROM public.property_images WHERE property_id = NEW.id;
      IF photo_count < 3 THEN
        RAISE EXCEPTION 'Cannot submit for review: at least 3 photos required';
      END IF;
    END IF;
  END IF;

  IF OLD.status = 'unlisted' AND NEW.status = 'unlisted' THEN
    IF NEW.description IS DISTINCT FROM OLD.description
       OR NEW.title IS DISTINCT FROM OLD.title
       OR NEW.building_rules IS DISTINCT FROM OLD.building_rules
       OR NEW.building_notes IS DISTINCT FROM OLD.building_notes
       OR NEW.amenities IS DISTINCT FROM OLD.amenities
    THEN
      RAISE EXCEPTION 'Cannot edit properties in unlisted state — re-list first';
    END IF;

    IF OLD.listing_type = 'sale' THEN
      IF NEW.sale_price IS DISTINCT FROM OLD.sale_price
         OR NEW.price_negotiable IS DISTINCT FROM OLD.price_negotiable
         OR NEW.expected_price_per_sqft IS DISTINCT FROM OLD.expected_price_per_sqft
         OR NEW.possession_status IS DISTINCT FROM OLD.possession_status
         OR NEW.possession_date IS DISTINCT FROM OLD.possession_date
         OR NEW.rera_registration_number IS DISTINCT FROM OLD.rera_registration_number
         OR NEW.khata_type IS DISTINCT FROM OLD.khata_type
         OR NEW.property_tax_paid_upto IS DISTINCT FROM OLD.property_tax_paid_upto
      THEN
        RAISE EXCEPTION 'Cannot edit properties in unlisted state — re-list first';
      END IF;
    ELSE
      IF NEW.listed_rent IS DISTINCT FROM OLD.listed_rent
         OR NEW.security_deposit_amount IS DISTINCT FROM OLD.security_deposit_amount
         OR NEW.security_deposit_months IS DISTINCT FROM OLD.security_deposit_months
         OR NEW.furnishing IS DISTINCT FROM OLD.furnishing
         OR NEW.available_from IS DISTINCT FROM OLD.available_from
         OR NEW.pet_policy IS DISTINCT FROM OLD.pet_policy
         OR NEW.furnishing_detail IS DISTINCT FROM OLD.furnishing_detail
      THEN
        RAISE EXCEPTION 'Cannot edit properties in unlisted state — re-list first';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_property_owner_transitions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_publish_location_invariant"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total       int;
  v_non_final   int;
  v_primary     int;
  v_bad_primary int;
  final_ok  boolean;
BEGIN
  IF NOT (NEW.status = 'listed' AND OLD.status IS DISTINCT FROM 'listed') THEN
    RETURN NEW;
  END IF;

  IF NEW.property_type IN ('apartment','duplex_apartment')
     AND NULLIF(btrim(COALESCE(NEW.building_name,'')),'') IS NULL THEN
    RAISE EXCEPTION 'location_not_ready:publish_location_incomplete';
  END IF;

  SELECT count(*),
         count(*) FILTER (WHERE a.relationship IS NOT NULL OR a.confidence IS NOT NULL),
         count(*) FILTER (WHERE a.is_primary),
         count(*) FILTER (WHERE a.is_primary AND g.kind NOT IN ('settlement','search_region'))
    INTO v_total, v_non_final, v_primary, v_bad_primary
    FROM public.property_geo_associations a
    JOIN public.geo_places g ON g.id = a.geo_place_id
   WHERE a.property_id = NEW.id;

  final_ok := (
    NEW.geom_exact IS NOT NULL
    AND NEW.location_confirmed_at IS NOT NULL
    AND NEW.country_code = 'IN'
    AND NEW.address_mode IN ('google_place','manual')
    AND NEW.discovery_finalized_at IS NOT NULL
    AND v_total > 0
    AND v_non_final = 0
    AND v_primary = 1
    AND v_bad_primary = 0
  );

  IF NOT final_ok THEN
    RAISE EXCEPTION 'location_not_ready:publish_location_incomplete';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_publish_location_invariant"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_single_primary_on_publish"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_primaries integer;
BEGIN
  IF public.is_admin() THEN RETURN NEW; END IF;
  IF NEW.status = 'pending_review' AND OLD.status IS DISTINCT FROM NEW.status THEN
    SELECT COUNT(*) INTO v_primaries FROM public.property_images WHERE property_id = NEW.id AND is_primary;
    IF v_primaries <> 1 THEN
      RAISE EXCEPTION 'Exactly one cover photo is required before submitting for review (found %)', v_primaries;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_single_primary_on_publish"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_property_discovery_geography"("p_property_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM 1 FROM public.properties WHERE id = p_property_id FOR UPDATE;
  PERFORM public._assert_final_discovery_valid(p_property_id);
  PERFORM set_config('reeve.system_action', 'geo_finalize', true);
  UPDATE public.properties SET discovery_finalized_at = now() WHERE id = p_property_id;
END;
$$;


ALTER FUNCTION "public"."finalize_property_discovery_geography"("p_property_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_pseudonym"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_adj   text;
  v_noun  text;
  v_num   int;
  v_pseud text;
  v_attempts int := 0;
BEGIN
  LOOP
    v_attempts := v_attempts + 1;
    IF v_attempts > 10 THEN
      RAISE EXCEPTION 'generate_pseudonym: exhausted 10 retries — word bank may need expansion';
    END IF;

    SELECT word INTO v_adj  FROM public.pseudonym_adjectives ORDER BY random() LIMIT 1;
    SELECT word INTO v_noun FROM public.pseudonym_nouns      ORDER BY random() LIMIT 1;
    v_num   := floor(random() * 900000 + 100000)::int;
    v_pseud := v_adj || '_' || v_noun || '_' || v_num::text;

    IF NOT EXISTS (SELECT 1 FROM public.users WHERE pseudonym = v_pseud) THEN
      RETURN v_pseud;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."generate_pseudonym"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_comment_report_details"("p_comment_id" "uuid") RETURNS TABLE("report_id" "uuid", "reason" "text", "notes" "text", "created_at" timestamp with time zone, "resolution" "text", "resolved_at" timestamp with time zone, "reporter_id" "uuid", "reporter_pseudonym" "text", "reporter_full_name" "text", "reporter_is_active" boolean, "reporter_is_property_owner" boolean, "reporter_lifetime_reports" bigint, "reporter_dismissed_count" bigint, "reporter_upheld_count" bigint, "reporter_reports_on_property" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_property_id uuid;
  v_owner_id    uuid;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;

  SELECT c.property_id, p.owner_id INTO v_property_id, v_owner_id
  FROM public.property_comments c
  LEFT JOIN public.properties p ON p.id = c.property_id
  WHERE c.id = p_comment_id;

  RETURN QUERY
  SELECT r.id, r.reason, r.notes, r.created_at, r.resolution, r.resolved_at,
    r.reporter_id, ru.pseudonym, ru.full_name::text, ru.is_active,
    COALESCE(r.reporter_id = v_owner_id, false),
    (SELECT count(*) FROM public.comment_reports r2 WHERE r2.reporter_id = r.reporter_id),
    (SELECT count(*) FROM public.comment_reports r2 WHERE r2.reporter_id = r.reporter_id AND r2.resolution = 'dismissed'),
    (SELECT count(*) FROM public.comment_reports r2 WHERE r2.reporter_id = r.reporter_id AND r2.resolution = 'upheld'),
    (SELECT count(*) FROM public.comment_reports r2 JOIN public.property_comments c2 ON c2.id = r2.comment_id
       WHERE r2.reporter_id = r.reporter_id AND c2.property_id = v_property_id)
  FROM public.comment_reports r
  JOIN public.users ru ON ru.id = r.reporter_id
  WHERE r.comment_id = p_comment_id
  ORDER BY r.created_at;
END;
$$;


ALTER FUNCTION "public"."get_admin_comment_report_details"("p_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_comment_review_queue"("p_search" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text", "p_author_type" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'oldest'::"text", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS TABLE("comment_id" "uuid", "property_id" "uuid", "parent_comment_id" "uuid", "is_reply" boolean, "depth" integer, "comment_text" "text", "comment_created_at" timestamp with time zone, "poster_id" "uuid", "poster_pseudonym" "text", "poster_full_name" "text", "poster_is_active" boolean, "poster_is_owner" boolean, "property_building" "text", "property_status" "text", "property_locality" "text", "property_city" "text", "owner_id" "uuid", "owner_pseudonym" "text", "owner_full_name" "text", "open_report_count" bigint, "lifetime_report_count" bigint, "hidden_at" timestamp with time zone, "burst_seconds" numeric, "open_reports" "jsonb", "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sort text := lower(coalesce(p_sort, 'oldest'));
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;
  p_limit  := LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100);
  p_offset := GREATEST(COALESCE(p_offset, 0), 0);
  IF v_sort NOT IN ('oldest','newest') THEN v_sort := 'oldest'; END IF;

  RETURN QUERY
  WITH base AS (
    SELECT c.id, c.property_id, c.parent_comment_id, c.depth, c.text, c.created_at,
           c.user_id AS poster_id, pu.pseudonym AS poster_pseudonym, pu.full_name AS poster_full_name,
           pu.is_active AS poster_is_active, p.building_name, p.status AS property_status, p.locality, p.city,
           p.owner_id, ou.pseudonym AS owner_pseudonym, ou.full_name AS owner_full_name,
           COALESCE(c.user_id = p.owner_id, false) AS poster_is_owner
    FROM public.property_comments c
    JOIN public.users pu ON pu.id = c.user_id
    LEFT JOIN public.properties p ON p.id = c.property_id
    LEFT JOIN public.users ou ON ou.id = p.owner_id
    WHERE c.is_deleted = true AND c.hidden_reason = 'auto_hidden_reports'
  ),
  agg AS (
    SELECT b.*,
      (SELECT count(*) FROM public.comment_reports r WHERE r.comment_id = b.id AND r.resolution IS NULL) AS open_report_count,
      (SELECT count(*) FROM public.comment_reports r WHERE r.comment_id = b.id) AS lifetime_report_count,
      (SELECT max(r.created_at) FROM public.comment_reports r WHERE r.comment_id = b.id AND r.resolution IS NULL) AS hidden_at,
      (SELECT EXTRACT(EPOCH FROM (max(r.created_at) - min(r.created_at))) FROM public.comment_reports r WHERE r.comment_id = b.id AND r.resolution IS NULL) AS burst_seconds,
      (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                 'reason', r.reason, 'notes', r.notes, 'created_at', r.created_at,
                 'reporter_pseudonym', ru.pseudonym, 'reporter_full_name', ru.full_name,
                 'reporter_is_owner', COALESCE(r.reporter_id = b.owner_id, false)
               ) ORDER BY r.created_at), '[]'::jsonb)
         FROM public.comment_reports r JOIN public.users ru ON ru.id = r.reporter_id
         WHERE r.comment_id = b.id AND r.resolution IS NULL) AS open_reports
    FROM base b
  ),
  filtered AS (
    SELECT * FROM agg a
    WHERE (p_search IS NULL OR btrim(p_search) = ''
           OR a.text ILIKE '%' || p_search || '%' OR a.poster_pseudonym ILIKE '%' || p_search || '%'
           OR a.poster_full_name ILIKE '%' || p_search || '%' OR a.building_name ILIKE '%' || p_search || '%')
      AND (p_reason IS NULL OR p_reason = '' OR p_reason = 'all'
           OR EXISTS (SELECT 1 FROM public.comment_reports r WHERE r.comment_id = a.id AND r.resolution IS NULL AND r.reason = p_reason))
      AND (p_author_type IS NULL OR p_author_type = '' OR p_author_type = 'all'
           OR (p_author_type = 'owner' AND a.poster_is_owner)
           OR (p_author_type = 'member' AND NOT a.poster_is_owner))
  )
  SELECT f.id, f.property_id, f.parent_comment_id, (f.parent_comment_id IS NOT NULL), f.depth,
    f.text, f.created_at, f.poster_id, f.poster_pseudonym, f.poster_full_name::text, f.poster_is_active, f.poster_is_owner,
    f.building_name::text, f.property_status::text, f.locality::text, f.city::text,
    f.owner_id, f.owner_pseudonym, f.owner_full_name::text,
    f.open_report_count, f.lifetime_report_count, f.hidden_at, f.burst_seconds, f.open_reports,
    count(*) OVER() AS total_count
  FROM filtered f
  ORDER BY
    CASE WHEN v_sort = 'oldest' THEN f.hidden_at END ASC NULLS LAST,
    CASE WHEN v_sort = 'newest' THEN f.hidden_at END DESC NULLS LAST,
    f.id
  LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."get_admin_comment_review_queue"("p_search" "text", "p_reason" "text", "p_author_type" "text", "p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_comments_page"("p_search" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text", "p_report_bucket" "text" DEFAULT NULL::"text", "p_author_type" "text" DEFAULT NULL::"text", "p_property_status" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'newest'::"text", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS TABLE("comment_id" "uuid", "property_id" "uuid", "parent_comment_id" "uuid", "is_reply" boolean, "comment_text" "text", "state" "text", "comment_created_at" timestamp with time zone, "comment_updated_at" timestamp with time zone, "poster_id" "uuid", "poster_pseudonym" "text", "poster_full_name" "text", "poster_is_active" boolean, "poster_is_owner" boolean, "property_building" "text", "property_status" "text", "property_locality" "text", "property_city" "text", "owner_id" "uuid", "owner_pseudonym" "text", "owner_full_name" "text", "report_count" bigint, "open_report_count" bigint, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sort text := lower(coalesce(p_sort, 'newest'));
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;
  p_limit  := LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100);
  p_offset := GREATEST(COALESCE(p_offset, 0), 0);
  IF v_sort NOT IN ('newest','oldest','most_reported') THEN v_sort := 'newest'; END IF;

  RETURN QUERY
  WITH base AS (
    SELECT c.id, c.property_id, c.parent_comment_id, c.text, c.is_deleted, c.hidden_reason,
           c.created_at, c.updated_at, c.user_id AS poster_id, pu.pseudonym AS poster_pseudonym,
           pu.full_name AS poster_full_name, pu.is_active AS poster_is_active,
           p.building_name, p.status AS property_status, p.locality, p.city, p.owner_id,
           ou.pseudonym AS owner_pseudonym, ou.full_name AS owner_full_name,
           COALESCE(c.user_id = p.owner_id, false) AS poster_is_owner,
           (SELECT count(*) FROM public.comment_reports r WHERE r.comment_id = c.id) AS report_count,
           (SELECT count(*) FROM public.comment_reports r WHERE r.comment_id = c.id AND r.resolution IS NULL) AS open_report_count,
           CASE WHEN NOT c.is_deleted THEN 'visible'
                WHEN c.hidden_reason = 'auto_hidden_reports' THEN 'auto_hidden'
                WHEN c.hidden_reason = 'admin_hidden' THEN 'admin_hidden'
                WHEN c.hidden_reason = 'user_deleted' THEN 'user_deleted'
                ELSE 'visible' END AS state
    FROM public.property_comments c
    JOIN public.users pu ON pu.id = c.user_id
    LEFT JOIN public.properties p ON p.id = c.property_id
    LEFT JOIN public.users ou ON ou.id = p.owner_id
  ),
  filtered AS (
    SELECT * FROM base b
    WHERE (p_search IS NULL OR btrim(p_search) = ''
           OR b.text ILIKE '%' || p_search || '%' OR b.poster_pseudonym ILIKE '%' || p_search || '%'
           OR b.poster_full_name ILIKE '%' || p_search || '%' OR b.building_name ILIKE '%' || p_search || '%')
      AND (p_state IS NULL OR p_state = '' OR p_state = 'all' OR b.state = p_state)
      AND (p_author_type IS NULL OR p_author_type = '' OR p_author_type = 'all'
           OR (p_author_type = 'owner' AND b.poster_is_owner)
           OR (p_author_type = 'member' AND NOT b.poster_is_owner))
      AND (p_property_status IS NULL OR p_property_status = '' OR p_property_status = 'all'
           OR b.property_status::text = p_property_status)
      AND (p_report_bucket IS NULL OR p_report_bucket = '' OR p_report_bucket = 'all'
           OR (p_report_bucket = '0' AND b.report_count = 0)
           OR (p_report_bucket = '1' AND b.report_count = 1)
           OR (p_report_bucket = '2' AND b.report_count = 2)
           OR (p_report_bucket = '3_plus' AND b.report_count >= 3))
  )
  SELECT f.id, f.property_id, f.parent_comment_id, (f.parent_comment_id IS NOT NULL),
    f.text, f.state, f.created_at, f.updated_at,
    f.poster_id, f.poster_pseudonym, f.poster_full_name::text, f.poster_is_active, f.poster_is_owner,
    f.building_name::text, f.property_status::text, f.locality::text, f.city::text,
    f.owner_id, f.owner_pseudonym, f.owner_full_name::text, f.report_count, f.open_report_count,
    count(*) OVER() AS total_count
  FROM filtered f
  ORDER BY
    CASE WHEN v_sort = 'most_reported' THEN f.report_count END DESC NULLS LAST,
    CASE WHEN v_sort = 'oldest' THEN f.created_at END ASC NULLS LAST,
    CASE WHEN v_sort = 'newest' THEN f.created_at END DESC NULLS LAST,
    f.created_at DESC, f.id
  LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."get_admin_comments_page"("p_search" "text", "p_state" "text", "p_report_bucket" "text", "p_author_type" "text", "p_property_status" "text", "p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_properties_page"("p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_listing_type" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'latest'::"text", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS TABLE("property_id" "uuid", "building_name" "text", "locality" "text", "city" "text", "bhk" "text", "status" "text", "listing_type" "text", "listed_rent" numeric, "sale_price" numeric, "listed_at" timestamp with time zone, "updated_at" timestamp with time zone, "owner_name" "text", "owner_email" "text", "owner_phone" "text", "accepted_contact_requests" bigint, "pending_contact_requests" bigint, "rejected_contact_requests" bigint, "total_contact_requests" bigint, "view_count" bigint, "comment_count" bigint, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sort text := lower(coalesce(p_sort, 'latest'));
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  p_limit  := LEAST(GREATEST(COALESCE(p_limit, 25), 1), 25);
  p_offset := GREATEST(COALESCE(p_offset, 0), 0);
  IF v_sort NOT IN ('latest', 'views', 'contact') THEN
    v_sort := 'latest';
  END IF;

  RETURN QUERY
  WITH filtered AS (
    SELECT
      p.id,
      p.building_name,
      p.locality,
      p.city,
      p.bhk,
      p.status,
      p.listing_type,
      p.listed_rent,
      p.sale_price,
      p.listed_at,
      p.updated_at,
      o.full_name AS owner_name,
      o.email     AS owner_email,
      o.phone     AS owner_phone,
      COALESCE(cr.accepted, 0::bigint) AS accepted_cr,
      COALESCE(cr.pending,  0::bigint) AS pending_cr,
      COALESCE(cr.rejected, 0::bigint) AS rejected_cr,
      COALESCE(cr.accepted, 0::bigint) + COALESCE(cr.pending, 0::bigint) + COALESCE(cr.rejected, 0::bigint) AS total_cr,
      COALESCE((
        SELECT COUNT(DISTINCT COALESCE(pv.user_id::text, pv.visitor_id))
        FROM public.property_views pv
        WHERE pv.property_id = p.id
      ), 0::bigint) AS views_ct,
      COALESCE((
        SELECT COUNT(*)
        FROM public.property_comments pc
        WHERE pc.property_id = p.id AND pc.is_deleted = false
      ), 0::bigint) AS comments_ct
    FROM public.properties p
    LEFT JOIN public.users o ON o.id = p.owner_id
    LEFT JOIN LATERAL (
      SELECT
        COUNT(*) FILTER (WHERE c.status = 'approved') AS accepted,
        COUNT(*) FILTER (WHERE c.status = 'pending')  AS pending,
        COUNT(*) FILTER (WHERE c.status = 'declined') AS rejected
      FROM public.contact_requests c
      WHERE c.property_id = p.id
    ) cr ON true
    WHERE
      (
        p_status IS NULL OR p_status = 'all'
        OR (p_status <> 'all' AND p.status::text = p_status)
      )
      AND (p_city IS NULL OR btrim(p_city) = '' OR lower(btrim(p.city)) = lower(btrim(p_city)))
      AND (
        p_listing_type IS NULL OR p_listing_type = '' OR p_listing_type = 'all'
        OR (p_listing_type = 'sale' AND p.listing_type = 'sale')
        OR (p_listing_type = 'rent' AND (p.listing_type = 'rent' OR p.listing_type IS NULL))
      )
      AND (
        p_search IS NULL OR btrim(p_search) = ''
        OR p.building_name ILIKE '%' || p_search || '%'
        OR p.locality      ILIKE '%' || p_search || '%'
        OR p.city          ILIKE '%' || p_search || '%'
        OR o.full_name     ILIKE '%' || p_search || '%'
        OR o.email         ILIKE '%' || p_search || '%'
        OR o.phone         ILIKE '%' || p_search || '%'
      )
  )
  SELECT
    f.id,
    f.building_name::text,
    f.locality::text,
    f.city::text,
    f.bhk::text,
    f.status::text,
    f.listing_type::text,
    f.listed_rent,
    f.sale_price,
    f.listed_at,
    f.updated_at,
    f.owner_name::text,
    f.owner_email::text,
    f.owner_phone::text,
    f.accepted_cr,
    f.pending_cr,
    f.rejected_cr,
    f.total_cr,
    f.views_ct,
    f.comments_ct,
    COUNT(*) OVER() AS total_count
  FROM filtered f
  ORDER BY
    CASE WHEN v_sort = 'views'   THEN f.views_ct END DESC NULLS LAST,
    CASE WHEN v_sort = 'contact' THEN f.total_cr END DESC NULLS LAST,
    f.listed_at DESC NULLS LAST,
    f.updated_at DESC,
    f.id ASC
  LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."get_admin_properties_page"("p_search" "text", "p_status" "text", "p_city" "text", "p_listing_type" "text", "p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_property_cities"() RETURNS TABLE("city" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  RETURN QUERY
  SELECT min(btrim(p.city))::text AS city
  FROM public.properties p
  WHERE p.city IS NOT NULL AND btrim(p.city) <> ''
  GROUP BY lower(btrim(p.city))
  ORDER BY 1;
END;
$$;


ALTER FUNCTION "public"."get_admin_property_cities"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_user_signals"("p_search" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'reports_filed'::"text", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS TABLE("user_id" "uuid", "pseudonym" "text", "full_name" "text", "is_active" boolean, "comments_count" bigint, "comment_reports_received" bigint, "comments_auto_hidden" bigint, "comments_admin_deleted" bigint, "reports_filed" bigint, "reports_dismissed" bigint, "reports_upheld" bigint, "distinct_properties_reported" bigint, "max_reports_single_property" bigint, "reports_on_owned_property" bigint, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sort text := lower(coalesce(p_sort, 'reports_filed'));
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;
  p_limit  := LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100);
  p_offset := GREATEST(COALESCE(p_offset, 0), 0);
  IF v_sort NOT IN ('reports_filed','reports_received','comments') THEN v_sort := 'reports_filed'; END IF;

  RETURN QUERY
  WITH participants AS (
    SELECT pc.user_id AS uid FROM public.property_comments pc
    UNION
    SELECT cr.reporter_id AS uid FROM public.comment_reports cr
  ),
  metrics AS (
    SELECT u.id AS user_id, u.pseudonym, u.full_name, u.is_active,
      (SELECT count(*) FROM public.property_comments c WHERE c.user_id = u.id) AS comments_count,
      (SELECT count(*) FROM public.comment_reports r JOIN public.property_comments c ON c.id = r.comment_id WHERE c.user_id = u.id) AS comment_reports_received,
      (SELECT count(*) FROM public.property_comments c WHERE c.user_id = u.id AND c.is_deleted AND c.hidden_reason = 'auto_hidden_reports') AS comments_auto_hidden,
      (SELECT count(*) FROM public.property_comments c WHERE c.user_id = u.id AND c.is_deleted AND c.hidden_reason = 'admin_hidden') AS comments_admin_deleted,
      (SELECT count(*) FROM public.comment_reports r WHERE r.reporter_id = u.id) AS reports_filed,
      (SELECT count(*) FROM public.comment_reports r WHERE r.reporter_id = u.id AND r.resolution = 'dismissed') AS reports_dismissed,
      (SELECT count(*) FROM public.comment_reports r WHERE r.reporter_id = u.id AND r.resolution = 'upheld') AS reports_upheld,
      (SELECT count(DISTINCT c.property_id) FROM public.comment_reports r JOIN public.property_comments c ON c.id = r.comment_id WHERE r.reporter_id = u.id) AS distinct_properties_reported,
      COALESCE((SELECT max(q.cnt) FROM (SELECT count(*) AS cnt FROM public.comment_reports r JOIN public.property_comments c ON c.id = r.comment_id WHERE r.reporter_id = u.id GROUP BY c.property_id) q), 0) AS max_reports_single_property,
      (SELECT count(*) FROM public.comment_reports r JOIN public.property_comments c ON c.id = r.comment_id JOIN public.properties p ON p.id = c.property_id WHERE r.reporter_id = u.id AND p.owner_id = u.id) AS reports_on_owned_property
    FROM public.users u
    WHERE u.id IN (SELECT uid FROM participants)
  ),
  filtered AS (
    SELECT * FROM metrics m
    WHERE (p_search IS NULL OR btrim(p_search) = ''
           OR m.pseudonym ILIKE '%' || p_search || '%' OR m.full_name ILIKE '%' || p_search || '%')
  )
  SELECT f.user_id, f.pseudonym, f.full_name::text, f.is_active,
    f.comments_count, f.comment_reports_received, f.comments_auto_hidden, f.comments_admin_deleted,
    f.reports_filed, f.reports_dismissed, f.reports_upheld, f.distinct_properties_reported,
    f.max_reports_single_property, f.reports_on_owned_property,
    count(*) OVER() AS total_count
  FROM filtered f
  ORDER BY
    CASE WHEN v_sort = 'reports_filed' THEN f.reports_filed END DESC NULLS LAST,
    CASE WHEN v_sort = 'reports_received' THEN f.comment_reports_received END DESC NULLS LAST,
    CASE WHEN v_sort = 'comments' THEN f.comments_count END DESC NULLS LAST,
    f.reports_filed DESC, f.user_id
  LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."get_admin_user_signals"("p_search" "text", "p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_daily_request_remaining"() RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT GREATEST(
    0,
    10 - COUNT(*)::integer
  )
  FROM public.contact_requests
  WHERE tenant_id = auth.uid()
    AND status <> 'auto_cancelled'
    AND (created_at AT TIME ZONE 'Asia/Kolkata')::date
        = (now() AT TIME ZONE 'Asia/Kolkata')::date;
$$;


ALTER FUNCTION "public"."get_my_daily_request_remaining"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_my_daily_request_remaining"() IS 'Phase 3: Client-callable RPC. Returns how many contact requests the authenticated tenant can still submit today. Returns 0 when at or above limit. Used to render "X of 10 remaining today" counter in PropertyDetail CTA. GREATEST(0,...) ensures negative values never surface to client.';



CREATE OR REPLACE FUNCTION "public"."get_my_rateable_interactions_v2"() RETURNS TABLE("contact_request_id" "uuid", "property_id" "uuid", "building_name" "text", "locality" "text", "counterparty_name" "text", "counterparty_user_id" "uuid", "i_am" "text", "my_submitted" boolean, "property_viewable" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  RETURN QUERY
  SELECT
    ir.contact_request_id,
    ir.property_id,
    p.building_name::text,
    p.locality::text,
    (CASE WHEN ir.owner_id = v_caller THEN tu.full_name ELSE ou.full_name END)::text,
    (CASE WHEN ir.owner_id = v_caller THEN ir.tenant_id ELSE ir.owner_id END),
    (CASE WHEN ir.owner_id = v_caller THEN 'owner' ELSE 'seeker' END)::text,
    (CASE WHEN ir.owner_id = v_caller THEN ir.o_v2_submitted_at IS NOT NULL ELSE ir.t_v2_submitted_at IS NOT NULL END),
    (p.status::text = ANY (ARRAY['listed','edit_pending_review']) AND p.is_active)
  FROM public.interaction_ratings ir
  JOIN public.contact_requests cr ON cr.id = ir.contact_request_id AND cr.approved_at IS NOT NULL
  JOIN public.properties p ON p.id = ir.property_id
  JOIN public.users ou ON ou.id = ir.owner_id
  JOIN public.users tu ON tu.id = ir.tenant_id
  WHERE ir.owner_id = v_caller OR ir.tenant_id = v_caller
  ORDER BY (CASE WHEN ir.owner_id = v_caller THEN ir.o_v2_submitted_at IS NOT NULL ELSE ir.t_v2_submitted_at IS NOT NULL END) ASC,
           cr.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_my_rateable_interactions_v2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_owner_response_rate"("p_owner_id" "uuid") RETURNS TABLE("all_time_handled" bigint, "all_time_responded" bigint, "all_time_rate" numeric, "last_7d_handled" bigint, "last_7d_responded" bigint, "last_7d_rate" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_all_total    bigint;
  v_all_handled  bigint;
  v_7d_total     bigint;
  v_7d_handled   bigint;
BEGIN
  -- All-time: denominator excludes withdrawn and auto_cancelled (not owner actions)
  SELECT
    COUNT(*) FILTER (WHERE status NOT IN ('withdrawn', 'auto_cancelled')),
    COUNT(*) FILTER (WHERE status IN ('approved', 'declined'))
  INTO v_all_total, v_all_handled
  FROM public.contact_requests
  WHERE owner_id = p_owner_id;

  -- Last 7 days: same exclusion logic
  SELECT
    COUNT(*) FILTER (WHERE status NOT IN ('withdrawn', 'auto_cancelled')),
    COUNT(*) FILTER (WHERE status IN ('approved', 'declined'))
  INTO v_7d_total, v_7d_handled
  FROM public.contact_requests
  WHERE owner_id = p_owner_id
    AND created_at >= now() - interval '7 days';

  RETURN QUERY SELECT
    v_all_handled,
    v_all_handled,  -- responded = same as handled (approved or declined)
    CASE WHEN v_all_total = 0 THEN 0::numeric
         ELSE ROUND(v_all_handled::numeric / v_all_total * 100, 0)
    END,
    v_7d_handled,
    v_7d_handled,
    CASE WHEN v_7d_total = 0 THEN 0::numeric
         ELSE ROUND(v_7d_handled::numeric / v_7d_total * 100, 0)
    END;
END;
$$;


ALTER FUNCTION "public"."get_owner_response_rate"("p_owner_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_owner_response_rate"("p_owner_id" "uuid") IS 'Phase 3: Returns all-time and 7-day response metrics for an owner. Response = approved OR declined. pending/withdrawn/auto_cancelled excluded. Caller must check all_time_handled < 5 and show New Owner badge if true. Used on PropertyDetail (near owner name) and /u/:ownerId (PublicProfile).';



CREATE OR REPLACE FUNCTION "public"."get_pending_ratings_for_me"() RETURNS TABLE("contact_request_id" "uuid", "property_id" "uuid", "building_name" "text", "locality" "text", "window_opens_at" timestamp with time zone, "window_closes_at" timestamp with time zone, "counterparty_name" "text", "i_am" "text", "other_submitted" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
BEGIN
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  RETURN QUERY
  SELECT
    ir.contact_request_id,
    ir.property_id,
    p.building_name::text,
    p.locality::text,
    ir.window_opens_at,
    ir.window_closes_at,
    -- Counterparty real name (transactional context — identity appropriate)
    CASE
      WHEN ir.owner_id = v_caller_id THEN tu.full_name::text  -- caller is owner, counterparty is tenant
      ELSE                                ou.full_name::text  -- caller is tenant, counterparty is owner
    END AS counterparty_name,
    CASE
      WHEN ir.owner_id = v_caller_id THEN 'owner'::text
      ELSE                                'tenant'::text
    END AS i_am,
    CASE
      WHEN ir.owner_id  = v_caller_id THEN (ir.t_submitted_at IS NOT NULL)
      ELSE                                 (ir.o_submitted_at IS NOT NULL)
    END AS other_submitted
  FROM public.interaction_ratings ir
  JOIN public.properties p  ON p.id  = ir.property_id
  JOIN public.users       ou ON ou.id = ir.owner_id
  JOIN public.users       tu ON tu.id = ir.tenant_id
  WHERE
    -- Caller is a participant
    (ir.owner_id = v_caller_id OR ir.tenant_id = v_caller_id)
    -- Window is currently open
    AND now() >= ir.window_opens_at
    AND now() <= ir.window_closes_at
    -- Caller's side not yet submitted
    AND (
      (ir.owner_id  = v_caller_id AND ir.o_submitted_at IS NULL)
      OR
      (ir.tenant_id = v_caller_id AND ir.t_submitted_at IS NULL)
    )
  ORDER BY ir.window_closes_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_pending_ratings_for_me"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pending_requests_for_digest"() RETURNS TABLE("owner_user_id" "uuid", "owner_email" character varying, "owner_name" character varying, "new_request_count" bigint, "new_requests" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    u.id                                 AS owner_user_id,
    u.email                              AS owner_email,
    u.full_name                          AS owner_name,
    COUNT(cr.id)                         AS new_request_count,
    JSONB_AGG(
      JSONB_BUILD_OBJECT(
        'building_name',   p.building_name,
        'locality',        p.locality,
        'tenant_display',  COALESCE(prof.display_name, tenant_u.full_name),
        'attempt_number',  cr.attempt_number,
        'created_at',      cr.created_at
      )
      ORDER BY cr.created_at DESC
    )                                    AS new_requests
  FROM public.contact_requests cr
  JOIN public.properties p         ON p.id = cr.property_id
  JOIN public.users u              ON u.id = cr.owner_id
  JOIN public.users tenant_u       ON tenant_u.id = cr.tenant_id
  LEFT JOIN public.profiles prof   ON prof.user_id = cr.tenant_id
  WHERE cr.status = 'pending'
    AND cr.created_at >= NOW() - INTERVAL '24 hours'
  GROUP BY u.id, u.email, u.full_name;
$$;


ALTER FUNCTION "public"."get_pending_requests_for_digest"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_pending_requests_for_digest"() IS 'Phase 3: Scoped digest RPC called by n8n Contact Daily Digest workflow. SECURITY DEFINER bypasses RLS internally; returns fixed shape only. Safe to grant to anon — no ad-hoc query surface exposed.';



CREATE OR REPLACE FUNCTION "public"."get_phone_fallback"("p_user_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_phone text;
BEGIN
  -- Primary: auth.users.phone (populated for every phone-verified user).
  SELECT NULLIF(TRIM(u.phone), '')
  INTO v_phone
  FROM auth.users u
  WHERE u.id = p_user_id
    AND u.phone_confirmed_at IS NOT NULL;

  -- Secondary fallback: identity_data (covers any edge case where the top-level
  -- column is somehow empty but the identity carries it).
  IF v_phone IS NULL THEN
    SELECT NULLIF(TRIM(i.identity_data->>'phone'), '')
    INTO v_phone
    FROM auth.identities i
    WHERE i.user_id = p_user_id
      AND i.provider = 'phone'
    LIMIT 1;
  END IF;

  RETURN v_phone;
END;
$$;


ALTER FUNCTION "public"."get_phone_fallback"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_property_comments"("p_property_id" "uuid", "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 20) RETURNS TABLE("comment_id" "uuid", "parent_comment_id" "uuid", "depth" integer, "pseudonym" "text", "is_owner" boolean, "real_name" "text", "badges" "text"[], "text" "text", "hidden_reason" "text", "like_count" integer, "liked_by_me" boolean, "is_mine" boolean, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
  v_owner_id  uuid;
BEGIN
  SELECT owner_id INTO v_owner_id
  FROM public.properties WHERE id = p_property_id;

  RETURN QUERY
  SELECT
    c.id                                                          AS comment_id,
    c.parent_comment_id,
    c.depth,
    u.pseudonym,
    (c.user_id = v_owner_id)                                     AS is_owner,
    CASE WHEN c.user_id = v_owner_id THEN u.full_name
         ELSE NULL::text
    END                                                           AS real_name,
    CASE WHEN c.user_id = v_owner_id THEN ARRAY['owner']::text[]
         ELSE ARRAY[]::text[]
    END                                                           AS badges,
    CASE WHEN c.is_deleted THEN '[deleted]'::text
         ELSE c.text
    END                                                           AS text,
    c.hidden_reason,
    c.like_count,
    COALESCE(
      v_caller_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.comment_likes cl
        WHERE cl.comment_id = c.id AND cl.user_id = v_caller_id
      ),
      false
    )                                                             AS liked_by_me,
    COALESCE(c.user_id = v_caller_id, false)                     AS is_mine,
    c.created_at
  FROM public.property_comments c
  JOIN public.users u ON u.id = c.user_id
  WHERE c.property_id = p_property_id
    AND (p_cursor IS NULL OR c.created_at < p_cursor)
  ORDER BY c.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_property_comments"("p_property_id" "uuid", "p_cursor" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_property_counts"("p_property_ids" "uuid"[]) RETURNS TABLE("property_id" "uuid", "view_count" bigint, "comment_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    pid.id AS property_id,
    COALESCE(
      (SELECT COUNT(DISTINCT COALESCE(pv.user_id::text, pv.visitor_id))
       FROM public.property_views pv
       WHERE pv.property_id = pid.id),
      0
    ) AS view_count,
    COALESCE(
      (SELECT COUNT(*)
       FROM public.property_comments pc
       WHERE pc.property_id = pid.id AND pc.is_deleted = false),
      0
    ) AS comment_count
  FROM unnest(p_property_ids) AS pid(id);
END;
$$;


ALTER FUNCTION "public"."get_property_counts"("p_property_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_property_public_stats"("p_property_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_view_count    bigint;
  v_comment_count bigint;
BEGIN
  SELECT COUNT(DISTINCT COALESCE(user_id::text, visitor_id))
  INTO v_view_count
  FROM public.property_views
  WHERE property_id = p_property_id;

  SELECT COUNT(*)
  INTO v_comment_count
  FROM public.property_comments
  WHERE property_id = p_property_id
    AND is_deleted = false;

  RETURN jsonb_build_object(
    'view_count',    COALESCE(v_view_count, 0),
    'comment_count', COALESCE(v_comment_count, 0)
  );
END;
$$;


ALTER FUNCTION "public"."get_property_public_stats"("p_property_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_profile"("p_user_id" "uuid") RETURNS TABLE("user_id" "uuid", "full_name" "text", "profile_photo_url" "text", "bio" "text", "is_public" boolean, "created_at" timestamp with time zone, "phone_verified" boolean, "email_verified" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_viewer     uuid := auth.uid();
  v_v_phone    boolean;
  v_v_email    boolean;
  v_is_admin   boolean;
  v_is_public  boolean;
  v_found      boolean;
BEGIN
  -- 1. Auth
  IF v_viewer IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  -- 2. Viewer must be fully verified (phone AND email)
  SELECT u.phone_verified, u.email_verified
    INTO v_v_phone, v_v_email
    FROM public.users u
   WHERE u.id = v_viewer;

  IF NOT (COALESCE(v_v_phone, false) AND COALESCE(v_v_email, false)) THEN
    RAISE EXCEPTION 'NOT_FULLY_VERIFIED';
  END IF;

  v_is_admin := public.is_admin();

  -- 3. Resolve target. LEFT JOIN so a missing profile row is handled safely;
  --    a missing profile row / null is_public is treated as NON-public.
  SELECT true, COALESCE(p.is_public, false)
    INTO v_found, v_is_public
    FROM public.users tu
    LEFT JOIN public.profiles p ON p.user_id = tu.id
   WHERE tu.id = p_user_id;

  -- Nonexistent user -> return no row (distinct from private below)
  IF NOT COALESCE(v_found, false) THEN
    RETURN;
  END IF;

  -- 4. Authorized to see full identity: public profile, admin, or self
  IF v_is_public OR v_is_admin OR p_user_id = v_viewer THEN
    RETURN QUERY
      SELECT
        tu.id                        AS user_id,
        tu.full_name::text           AS full_name,
        p.profile_photo_url::text    AS profile_photo_url,
        p.bio::text                  AS bio,
        COALESCE(p.is_public, false) AS is_public,
        tu.created_at                AS created_at,
        tu.phone_verified            AS phone_verified,
        tu.email_verified            AS email_verified
      FROM public.users tu
      LEFT JOIN public.profiles p ON p.user_id = tu.id
      WHERE tu.id = p_user_id;
    RETURN;
  END IF;

  -- 5. Private profile, unauthorized viewer: minimal row so the frontend can
  --    distinguish "private" from "nonexistent". No identity/bio leaked.
  RETURN QUERY
    SELECT
      p_user_id,
      NULL::text,
      NULL::text,
      NULL::text,
      false,
      NULL::timestamptz,
      NULL::boolean,
      NULL::boolean;
END;
$$;


ALTER FUNCTION "public"."get_public_profile"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tenant_daily_request_count"("p_tenant_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COUNT(*)::integer
  FROM public.contact_requests
  WHERE tenant_id = p_tenant_id
    AND status <> 'auto_cancelled'
    AND (created_at AT TIME ZONE 'Asia/Kolkata')::date
        = (now() AT TIME ZONE 'Asia/Kolkata')::date;
$$;


ALTER FUNCTION "public"."get_tenant_daily_request_count"("p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_tenant_daily_request_count"("p_tenant_id" "uuid") IS 'Phase 3: Returns count of contact requests submitted by a tenant today (IST calendar day). auto_cancelled excluded (outside tenant control). All other statuses count. Called by submit-contact-request Edge Function. Rate limit: 10/day. IST midnight = 18:30 UTC previous calendar day.';



CREATE OR REPLACE FUNCTION "public"."get_unanswered_comment_counts"("p_property_ids" "uuid"[]) RETURNS TABLE("property_id" "uuid", "unanswered_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
BEGIN
  -- Security: caller must be authenticated
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  RETURN QUERY
  SELECT
    pid.id AS property_id,
    COALESCE(
      (
        -- Count top-level comments on this property that have no owner reply
        -- anywhere in their thread
        SELECT COUNT(DISTINCT top.id)
        FROM public.property_comments top
        WHERE top.property_id = pid.id
          AND top.parent_comment_id IS NULL   -- top-level only
          AND top.is_deleted = false
          AND NOT EXISTS (
            -- Any comment in the same property tree posted by the owner
            -- that is a descendant of this top-level comment
            SELECT 1
            FROM public.property_comments reply
            WHERE reply.property_id = pid.id
              AND reply.user_id = (
                SELECT owner_id FROM public.properties WHERE id = pid.id
              )
              AND reply.is_deleted = false
              -- Reply is in this thread: shares the same top-level ancestor
              -- We approximate: any owner reply whose root ancestor = top.id
              -- Simple approach: owner replied anywhere on this property's thread
              -- rooted at top.id — check parent chain via recursive CTE
              AND (
                reply.parent_comment_id = top.id
                OR reply.parent_comment_id IN (
                  -- Walk up to 5 levels deep (covers all practical cases)
                  SELECT id FROM public.property_comments
                  WHERE parent_comment_id = top.id
                  UNION ALL
                  SELECT c.id FROM public.property_comments c
                  JOIN public.property_comments p2 ON c.parent_comment_id = p2.id
                  WHERE p2.parent_comment_id = top.id
                  UNION ALL
                  SELECT c.id FROM public.property_comments c
                  JOIN public.property_comments p2 ON c.parent_comment_id = p2.id
                  JOIN public.property_comments p3 ON p2.parent_comment_id = p3.id
                  WHERE p3.parent_comment_id = top.id
                  UNION ALL
                  SELECT c.id FROM public.property_comments c
                  JOIN public.property_comments p2 ON c.parent_comment_id = p2.id
                  JOIN public.property_comments p3 ON p2.parent_comment_id = p3.id
                  JOIN public.property_comments p4 ON p3.parent_comment_id = p4.id
                  WHERE p4.parent_comment_id = top.id
                )
              )
          )
      ),
      0
    ) AS unanswered_count
  FROM unnest(p_property_ids) AS pid(id);
END;
$$;


ALTER FUNCTION "public"."get_unanswered_comment_counts"("p_property_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_rating_summary"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  -- Publish condition: both submitted OR window expired
  v_publish_condition text := '(t_submitted_at IS NOT NULL AND o_submitted_at IS NOT NULL) OR now() > window_closes_at';
  v_total_as_owner    bigint;
  v_yes_as_owner      bigint;
  v_reviews_as_owner  jsonb;
  v_total_as_tenant   bigint;
  v_yes_as_tenant     bigint;
  v_reviews_as_tenant jsonb;
BEGIN
  -- ── Owner side: tenant rates the owner ────────────────────────────────────
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE t_q3_deal_again = 'yes')
  INTO v_total_as_owner, v_yes_as_owner
  FROM public.interaction_ratings
  WHERE owner_id = p_user_id
    AND (
      (t_submitted_at IS NOT NULL AND o_submitted_at IS NOT NULL)
      OR now() > window_closes_at
    )
    AND t_q3_deal_again IS NOT NULL; -- only count rows with actual answer

  -- Published review texts (owner received from tenants)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'text',       t_review_text,
      'created_at', t_submitted_at
    ) ORDER BY t_submitted_at DESC
  ), '[]'::jsonb)
  INTO v_reviews_as_owner
  FROM public.interaction_ratings
  WHERE owner_id = p_user_id
    AND (
      (t_submitted_at IS NOT NULL AND o_submitted_at IS NOT NULL)
      OR now() > window_closes_at
    )
    AND t_review_text IS NOT NULL
    AND trim(t_review_text) != '';

  -- ── Tenant side: owner rates the tenant ───────────────────────────────────
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE o_q3_deal_again = 'yes')
  INTO v_total_as_tenant, v_yes_as_tenant
  FROM public.interaction_ratings
  WHERE tenant_id = p_user_id
    AND (
      (t_submitted_at IS NOT NULL AND o_submitted_at IS NOT NULL)
      OR now() > window_closes_at
    )
    AND o_q3_deal_again IS NOT NULL;

  -- Published review texts (tenant received from owners)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'text',       o_review_text,
      'created_at', o_submitted_at
    ) ORDER BY o_submitted_at DESC
  ), '[]'::jsonb)
  INTO v_reviews_as_tenant
  FROM public.interaction_ratings
  WHERE tenant_id = p_user_id
    AND (
      (t_submitted_at IS NOT NULL AND o_submitted_at IS NOT NULL)
      OR now() > window_closes_at
    )
    AND o_review_text IS NOT NULL
    AND trim(o_review_text) != '';

  -- ── Assemble result ────────────────────────────────────────────────────────
  -- Minimum 3 ratings on either side before showing aggregate
  -- If both sides have < 3, return 'new' status
  IF v_total_as_owner < 3 AND v_total_as_tenant < 3 THEN
    RETURN jsonb_build_object('status', 'new');
  END IF;

  RETURN jsonb_build_object(
    'status', 'active',
    'as_owner', jsonb_build_object(
      'total',          v_total_as_owner,
      'yes_count',      v_yes_as_owner,
      'deal_again_pct', CASE WHEN v_total_as_owner > 0
                             THEN round((v_yes_as_owner::numeric / v_total_as_owner) * 100)
                             ELSE NULL
                        END,
      'reviews',        v_reviews_as_owner
    ),
    'as_tenant', jsonb_build_object(
      'total',          v_total_as_tenant,
      'yes_count',      v_yes_as_tenant,
      'deal_again_pct', CASE WHEN v_total_as_tenant > 0
                             THEN round((v_yes_as_tenant::numeric / v_total_as_tenant) * 100)
                             ELSE NULL
                        END,
      'reviews',        v_reviews_as_tenant
    )
  );
END;
$$;


ALTER FUNCTION "public"."get_user_rating_summary"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_rating_summary_v2"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  l_total bigint; l_reach_pos bigint; l_reach_den bigint; l_acc_pos bigint; l_acc_den bigint;
  l_prog_pos bigint; l_prog_den bigint; l_resp_pos bigint; l_resp_den bigint; l_trust_pos bigint; l_trust_den bigint;
  s_total bigint; s_reach_pos bigint; s_reach_den bigint; s_acc_pos bigint; s_acc_den bigint;
  s_prog_pos bigint; s_prog_den bigint; s_resp_pos bigint; s_resp_den bigint; s_trust_pos bigint; s_trust_den bigint;
BEGIN
  -- As a lister: tenants' ratings ABOUT this owner (t_* cols), owner_id = target
  SELECT count(*),
    count(*) FILTER (WHERE t_reach='easily'),      count(*) FILTER (WHERE t_reach IS NOT NULL),
    count(*) FILTER (WHERE t_accuracy='matched'),  count(*) FILTER (WHERE t_accuracy IS NOT NULL),
    count(*) FILTER (WHERE t_progress='next_step'),count(*) FILTER (WHERE t_progress IS NOT NULL AND t_progress <> 'mutual_stop'),
    count(*) FILTER (WHERE t_respect='yes'),       count(*) FILTER (WHERE t_respect IS NOT NULL),
    count(*) FILTER (WHERE t_trust='yes'),         count(*) FILTER (WHERE t_trust IS NOT NULL)
  INTO l_total, l_reach_pos, l_reach_den, l_acc_pos, l_acc_den, l_prog_pos, l_prog_den, l_resp_pos, l_resp_den, l_trust_pos, l_trust_den
  FROM public.interaction_ratings
  WHERE owner_id = p_user_id AND t_v2_submitted_at IS NOT NULL;

  -- As a property seeker: owners' ratings ABOUT this tenant (o_* cols), tenant_id = target
  SELECT count(*),
    count(*) FILTER (WHERE o_reach='easily'),      count(*) FILTER (WHERE o_reach IS NOT NULL),
    count(*) FILTER (WHERE o_accuracy='matched'),  count(*) FILTER (WHERE o_accuracy IS NOT NULL),
    count(*) FILTER (WHERE o_progress='next_step'),count(*) FILTER (WHERE o_progress IS NOT NULL AND o_progress <> 'mutual_stop'),
    count(*) FILTER (WHERE o_respect='yes'),       count(*) FILTER (WHERE o_respect IS NOT NULL),
    count(*) FILTER (WHERE o_trust='yes'),         count(*) FILTER (WHERE o_trust IS NOT NULL)
  INTO s_total, s_reach_pos, s_reach_den, s_acc_pos, s_acc_den, s_prog_pos, s_prog_den, s_resp_pos, s_resp_den, s_trust_pos, s_trust_den
  FROM public.interaction_ratings
  WHERE tenant_id = p_user_id AND o_v2_submitted_at IS NOT NULL;

  RETURN jsonb_build_object(
    'as_lister', COALESCE(public._build_rating_side_v2(l_total, l_reach_pos,l_reach_den, l_acc_pos,l_acc_den, l_prog_pos,l_prog_den, l_resp_pos,l_resp_den, l_trust_pos,l_trust_den), 'null'::jsonb),
    'as_seeker', COALESCE(public._build_rating_side_v2(s_total, s_reach_pos,s_reach_den, s_acc_pos,s_acc_den, s_prog_pos,s_prog_den, s_resp_pos,s_resp_den, s_trust_pos,s_trust_den), 'null'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_user_rating_summary_v2"("p_user_id" "uuid") OWNER TO "postgres";


