CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only insert if email OR phone is already confirmed (prevents ghost users).
  IF NEW.email_confirmed_at IS NULL AND NEW.phone_confirmed_at IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.users (
    id, email, phone, full_name, role,
    auth_provider, email_verified, phone_verified,
    is_active, created_at, updated_at
  )
  VALUES (
    NEW.id,
    NEW.email,
    NEW.phone,
    COALESCE(NEW.raw_user_meta_data->>'full_name', ''),
    'user',
    CASE
      WHEN NEW.raw_app_meta_data->>'provider' = 'google' THEN 'google'::auth_provider
      WHEN NEW.phone IS NOT NULL                          THEN 'phone_otp'::auth_provider
      ELSE                                                     'email_otp'::auth_provider
    END,
    NEW.email_confirmed_at IS NOT NULL,
    NEW.phone_confirmed_at IS NOT NULL,
    true,
    NOW(),
    NOW()
  )
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.profiles (
    user_id,
    profile_photo_url, display_name,
    created_at, updated_at
  )
  VALUES (
    NEW.id,
    COALESCE(NEW.raw_user_meta_data->>'avatar_url', NEW.raw_user_meta_data->>'picture'),
    COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name'),
    NOW(), NOW()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    -- Refresh photo from Google if provided; otherwise keep existing.
    profile_photo_url = COALESCE(EXCLUDED.profile_photo_url, public.profiles.profile_photo_url),
    -- Preserve manual edits — only fill display_name if currently NULL.
    display_name      = COALESCE(public.profiles.display_name, EXCLUDED.display_name),
    updated_at        = NOW();

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_property_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- When status changes to 'listed': make active and visible on search.
  IF NEW.status = 'listed' AND OLD.status != 'listed' THEN
    NEW.is_active := true;
    IF NEW.listed_at IS NULL THEN
      NEW.listed_at := now();
    END IF;

    -- Fresh continuously-public listing period. Excludes edit_pending_review→listed
    -- (that is a review round-trip; the clock must continue). Counts as an
    -- immediate confirmation and resets the type-matching clock.
    IF OLD.status <> 'edit_pending_review' THEN
      PERFORM set_config('reeve.system_action', 'status_change', true);
      NEW.current_listed_period_started_at := now();
      IF NEW.listing_type = 'rent' THEN
        NEW.availability_confirmed_at := now();
      ELSIF NEW.listing_type = 'sale' THEN
        NEW.sale_listing_confirmed_at := now();
      END IF;
    END IF;
  END IF;

  -- When status changes to 'edit_pending_review': keep active (live listing stays
  -- live). No listed_at / period / confirmation change — the clock continues.
  IF NEW.status = 'edit_pending_review' AND OLD.status != 'edit_pending_review' THEN
    NEW.is_active := true;
  END IF;

  -- When status changes away from 'listed' (unlisted, archived, etc): hide from search.
  -- edit_pending_review is EXCLUDED here — it keeps is_active=true (set above).
  IF OLD.status = 'listed' AND NEW.status NOT IN ('listed', 'edit_pending_review') THEN
    NEW.is_active := false;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_property_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_user_updated"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_google_email text;
  v_google_name  text;
  v_final_email  text;
  v_final_name   text;
BEGIN
  -- ── Block 1: Phone OTP verification (phone_confirmed_at NULL → not-null) ──
  IF (OLD.phone_confirmed_at IS NULL AND NEW.phone_confirmed_at IS NOT NULL) THEN
    INSERT INTO public.users (
      id, phone, email, full_name, role,
      auth_provider, phone_verified, email_verified,
      is_active, created_at, updated_at
    )
    VALUES (
      NEW.id, NEW.phone, NEW.email,
      COALESCE(NEW.raw_user_meta_data->>'full_name', ''),
      'user',
      'phone_otp'::auth_provider,
      true,
      NEW.email_confirmed_at IS NOT NULL,
      true, NOW(), NOW()
    )
    ON CONFLICT (id) DO UPDATE SET
      phone          = EXCLUDED.phone,
      phone_verified = true,
      updated_at     = NOW();

    INSERT INTO public.profiles (
      user_id,
      profile_photo_url, display_name,
      created_at, updated_at
    )
    VALUES (
      NEW.id,
      COALESCE(NEW.raw_user_meta_data->>'avatar_url', NEW.raw_user_meta_data->>'picture'),
      COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name'),
      NOW(), NOW()
    )
    ON CONFLICT (user_id) DO UPDATE SET
      profile_photo_url = COALESCE(EXCLUDED.profile_photo_url, public.profiles.profile_photo_url),
      display_name      = COALESCE(public.profiles.display_name, EXCLUDED.display_name),
      updated_at        = NOW();
  END IF;

  -- ── Block 2: Email verification (email_confirmed_at NULL → not-null) ──
  -- Fires on Google OAuth signup or linkIdentity('google').
  IF (OLD.email_confirmed_at IS NULL AND NEW.email_confirmed_at IS NOT NULL) THEN
    -- Source authoritative email + name from the Google identity row.
    SELECT
      NULLIF(i.identity_data->>'email', ''),
      COALESCE(NULLIF(i.identity_data->>'full_name', ''), NULLIF(i.identity_data->>'name', ''))
    INTO v_google_email, v_google_name
    FROM auth.identities i
    WHERE i.user_id = NEW.id AND i.provider = 'google'
    ORDER BY i.created_at DESC
    LIMIT 1;

    v_final_email := COALESCE(NULLIF(NEW.email, ''), v_google_email);
    v_final_name  := COALESCE(
      NULLIF(NEW.raw_user_meta_data->>'full_name', ''),
      NULLIF(NEW.raw_user_meta_data->>'name', ''),
      v_google_name
    );

    INSERT INTO public.users (
      id, phone, email, full_name, role,
      auth_provider, phone_verified, email_verified,
      is_active, created_at, updated_at
    )
    VALUES (
      NEW.id, NEW.phone, v_final_email,
      COALESCE(v_final_name, ''),
      'user',
      CASE
        WHEN NEW.raw_app_meta_data->>'provider' = 'google' THEN 'google'::auth_provider
        WHEN NEW.phone IS NOT NULL                          THEN 'phone_otp'::auth_provider
        ELSE                                                     'email_otp'::auth_provider
      END,
      NEW.phone_confirmed_at IS NOT NULL,
      true, true, NOW(), NOW()
    )
    ON CONFLICT (id) DO UPDATE SET
      -- Never clobber an existing good email with NULL.
      email          = COALESCE(EXCLUDED.email, public.users.email),
      email_verified = true,
      -- Product rule: name comes from Google. Take Google's value when we have one;
      -- otherwise preserve whatever exists.
      full_name      = COALESCE(EXCLUDED.full_name, public.users.full_name),
      updated_at     = NOW();

    INSERT INTO public.profiles (
      user_id,
      profile_photo_url, display_name,
      created_at, updated_at
    )
    VALUES (
      NEW.id,
      COALESCE(NEW.raw_user_meta_data->>'avatar_url', NEW.raw_user_meta_data->>'picture'),
      v_final_name,
      NOW(), NOW()
    )
    ON CONFLICT (user_id) DO UPDATE SET
      profile_photo_url = COALESCE(EXCLUDED.profile_photo_url, public.profiles.profile_photo_url),
      display_name      = COALESCE(public.profiles.display_name, EXCLUDED.display_name),
      updated_at        = NOW();
  END IF;

  RETURN NEW;
END;
$$;


