CREATE OR REPLACE FUNCTION "public"."log_property_price_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  p_public     boolean;
  p_old_public boolean;
  v_new        numeric;
  v_old_live   numeric;
  v_base       numeric;
  v_actor_id   uuid := (SELECT auth.uid());
  v_actor_role text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.last_public_listed_rent := NULL;
    NEW.last_public_sale_price  := NULL;
  ELSE
    NEW.last_public_listed_rent := OLD.last_public_listed_rent;
    NEW.last_public_sale_price  := OLD.last_public_sale_price;
  END IF;

  IF NEW.listing_type IS NULL OR NEW.listing_type NOT IN ('rent', 'sale') THEN
    RETURN NEW;
  END IF;

  p_public := (NEW.status IN ('listed', 'edit_pending_review') AND NEW.is_active);
  v_new := CASE WHEN NEW.listing_type = 'rent' THEN NEW.listed_rent ELSE NEW.sale_price END;

  IF TG_OP = 'INSERT' THEN
    IF p_public AND v_new IS NOT NULL AND v_new > 0 THEN
      IF NEW.listing_type = 'rent' THEN NEW.last_public_listed_rent := v_new;
      ELSE NEW.last_public_sale_price := v_new; END IF;
    END IF;
    RETURN NEW;
  END IF;

  p_old_public := (OLD.status IN ('listed', 'edit_pending_review') AND OLD.is_active);
  IF NEW.listing_type = 'rent' THEN
    v_old_live := OLD.listed_rent; v_base := OLD.last_public_listed_rent;
  ELSE
    v_old_live := OLD.sale_price;  v_base := OLD.last_public_sale_price;
  END IF;

  IF OLD.listing_type IS DISTINCT FROM NEW.listing_type THEN
    IF p_public AND v_new IS NOT NULL AND v_new > 0 THEN
      IF NEW.listing_type = 'rent' THEN NEW.last_public_listed_rent := v_new;
      ELSE NEW.last_public_sale_price := v_new; END IF;
    ELSE
      IF NEW.listing_type = 'rent' THEN NEW.last_public_listed_rent := NULL;
      ELSE NEW.last_public_sale_price := NULL; END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF NOT p_public THEN RETURN NEW; END IF;
  IF v_new IS NULL OR v_new <= 0 THEN RETURN NEW; END IF;

  v_actor_role := CASE WHEN v_actor_id IS NULL THEN 'system'
                       WHEN public.is_admin() THEN 'admin'
                       ELSE 'owner' END;

  IF p_old_public THEN
    IF v_old_live IS NOT NULL AND v_old_live > 0 AND v_old_live IS DISTINCT FROM v_new THEN
      INSERT INTO public.property_activity_log
        (property_id, actor_id, actor_role, action, payload, is_public)
      VALUES
        (NEW.id, v_actor_id, v_actor_role, 'price_changed',
         jsonb_build_object('action', 'price_changed', 'listing_type', NEW.listing_type,
                            'from_price', v_old_live, 'to_price', v_new),
         true);
    END IF;
    IF NEW.listing_type = 'rent' THEN NEW.last_public_listed_rent := v_new;
    ELSE NEW.last_public_sale_price := v_new; END IF;
    RETURN NEW;
  END IF;

  IF v_base IS NOT NULL AND v_base > 0 AND v_base IS DISTINCT FROM v_new THEN
    INSERT INTO public.property_activity_log
      (property_id, actor_id, actor_role, action, payload, is_public)
    VALUES
      (NEW.id, v_actor_id, v_actor_role, 'price_changed',
       jsonb_build_object('action', 'price_changed', 'listing_type', NEW.listing_type,
                          'from_price', v_base, 'to_price', v_new),
       true);
  END IF;
  IF NEW.listing_type = 'rent' THEN NEW.last_public_listed_rent := v_new;
  ELSE NEW.last_public_sale_price := v_new; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_property_price_change"() OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."property_comments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "property_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "parent_comment_id" "uuid",
    "depth" integer DEFAULT 0 NOT NULL,
    "text" "text" NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "hidden_reason" "text",
    "like_count" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "property_comments_hidden_reason_check" CHECK (("hidden_reason" = ANY (ARRAY['user_deleted'::"text", 'auto_hidden_reports'::"text", 'admin_hidden'::"text"]))),
    CONSTRAINT "property_comments_text_check" CHECK ((("char_length"("text") >= 1) AND ("char_length"("text") <= 1000)))
);


ALTER TABLE "public"."property_comments" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_comment"("p_property_id" "uuid", "p_text" "text", "p_parent_comment_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."property_comments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_user_id      uuid := auth.uid();
  v_phone_ver    boolean;
  v_email_ver    boolean;
  v_prop_status  text;
  v_prop_active  boolean;
  v_prop_owner   uuid;
  v_is_owner     boolean := false;
  v_parent_depth integer;
  v_depth        integer := 0;
  v_result       public.property_comments;
  v_count        integer;
  v_normalized   text;
  v_tier_b_regex text;
BEGIN
  -- 1. Auth
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  -- 2. Verification
  SELECT phone_verified, email_verified
  INTO v_phone_ver, v_email_ver
  FROM public.users WHERE id = v_user_id;

  IF NOT v_phone_ver THEN
    RAISE EXCEPTION 'VERIFICATION_INCOMPLETE:phone';
  END IF;
  IF NOT v_email_ver THEN
    RAISE EXCEPTION 'VERIFICATION_INCOMPLETE:email';
  END IF;

  -- 3. Property status gate
  SELECT status, is_active, owner_id
  INTO v_prop_status, v_prop_active, v_prop_owner
  FROM public.properties WHERE id = p_property_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PROPERTY_NOT_FOUND';
  END IF;

  IF v_prop_status NOT IN ('listed', 'edit_pending_review') OR NOT v_prop_active THEN
    RAISE EXCEPTION 'PROPERTY_NOT_AVAILABLE';
  END IF;

  -- 3b. Ownership check — derives from auth.uid(), not from any client parameter.
  --     EXISTS always returns true or false, never null.
  SELECT EXISTS (
    SELECT 1 FROM public.properties
    WHERE id = p_property_id AND owner_id = v_user_id
  ) INTO v_is_owner;

  -- 4. Content filters

  -- English only
  IF p_text ~ '[^\x00-\x7F]' THEN
    IF EXISTS (
      SELECT 1 FROM regexp_split_to_table(p_text, '') AS ch
      WHERE ascii(ch) > 591
        AND ascii(ch) != 8377
        AND ascii(ch) NOT BETWEEN 8208 AND 8213
        AND ascii(ch) NOT BETWEEN 8216 AND 8223
    ) THEN
      RAISE EXCEPTION 'NON_ENGLISH';
    END IF;
  END IF;

  -- No emojis
  IF EXISTS (
    SELECT 1 FROM regexp_split_to_table(p_text, '') AS ch
    WHERE ascii(ch) BETWEEN 9728 AND 10175
      OR ascii(ch) BETWEEN 127744 AND 131071
      OR ascii(ch) BETWEEN 126976 AND 127743
      OR ascii(ch) BETWEEN 9000 AND 9999
  ) THEN
    RAISE EXCEPTION 'CONTAINS_EMOJI';
  END IF;

  -- No URLs
  IF p_text ~* 'https?://' OR p_text ~* 'www\.'
     OR p_text ~* '[a-z0-9-]+\.[a-z]{2,4}(\s|$|/)' THEN
    RAISE EXCEPTION 'CONTAINS_URL';
  END IF;

  -- No emails
  IF p_text ~* '[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}' THEN
    RAISE EXCEPTION 'CONTAINS_EMAIL';
  END IF;

  -- No phone numbers
  IF p_text ~ '(\+91|91)?[6-9][0-9]{9}' THEN
    RAISE EXCEPTION 'CONTAINS_PHONE';
  END IF;

  -- PASS 1: Tier A
  IF EXISTS (
    SELECT 1
    FROM public.comment_blocklist bl
    WHERE bl.tier = 'A'
      AND lower(p_text) ~ ('\m' || bl.word || '\M')
  ) THEN
    RAISE EXCEPTION 'BLOCKED_WORD';
  END IF;

  -- PASS 2: Normalize
  v_normalized := p_text;
  v_normalized := regexp_replace(v_normalized, E'[\xe2\x80\x8b\xe2\x80\x8c\xe2\x80\x8d\xef\xbb\xbf]', '', 'g');
  v_normalized := lower(v_normalized);
  v_normalized := translate(v_normalized, '013457@$+', 'oieats ast');
  v_normalized := replace(v_normalized, chr(1072), 'a');
  v_normalized := replace(v_normalized, chr(1077), 'e');
  v_normalized := replace(v_normalized, chr(1086), 'o');
  v_normalized := replace(v_normalized, chr(1088), 'r');
  v_normalized := replace(v_normalized, chr(1089), 'c');
  v_normalized := replace(v_normalized, chr(1091), 'y');
  v_normalized := replace(v_normalized, chr(1093), 'x');
  v_normalized := replace(v_normalized, chr(1110), 'i');
  v_normalized := replace(v_normalized, chr(1068), 'b');
  v_normalized := regexp_replace(v_normalized, '([a-z])\1{2,}', '\1\1', 'g');
  v_normalized := regexp_replace(v_normalized, '(?<=[a-z])[^a-z](?=[a-z])', '', 'g');
  v_normalized := regexp_replace(v_normalized, '(?<=[a-z])[^a-z](?=[a-z])', '', 'g');

  -- PASS 3: Tier B
  IF EXISTS (
    SELECT 1
    FROM public.comment_blocklist bl
    WHERE bl.tier = 'B'
      AND v_normalized ~ bl.word
      AND NOT EXISTS (
        SELECT 1
        FROM public.comment_allowlist al
        WHERE v_normalized ~ al.word
          AND al.word ~ bl.word
      )
  ) THEN
    RAISE EXCEPTION 'BLOCKED_WORD';
  END IF;

  -- Pattern spam
  IF p_text ~ '[A-Z]{21,}' THEN
    RAISE EXCEPTION 'PATTERN_SPAM';
  END IF;
  IF p_text ~ '(.)\1{3,}' THEN
    RAISE EXCEPTION 'PATTERN_SPAM';
  END IF;
  IF trim(p_text) = '' THEN
    RAISE EXCEPTION 'PATTERN_SPAM';
  END IF;

  -- 5. Rate limiting — waived for property owner on their own property only.
  --    Content moderation above applies to everyone including the owner.
  IF NOT v_is_owner THEN
    SELECT COUNT(*) INTO v_count
    FROM public.property_comments
    WHERE user_id = v_user_id
      AND created_at > now() - interval '1 hour'
      AND is_deleted = false;

    IF v_count >= 3 THEN
      RAISE EXCEPTION 'RATE_LIMIT_HOUR';
    END IF;

    SELECT COUNT(*) INTO v_count
    FROM public.property_comments
    WHERE user_id = v_user_id
      AND created_at > now() - interval '24 hours'
      AND is_deleted = false;

    IF v_count >= 10 THEN
      RAISE EXCEPTION 'RATE_LIMIT_DAY';
    END IF;
  END IF;

  -- 6. Depth
  IF p_parent_comment_id IS NOT NULL THEN
    SELECT depth INTO v_parent_depth
    FROM public.property_comments
    WHERE id = p_parent_comment_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PARENT_NOT_FOUND';
    END IF;

    v_depth := v_parent_depth + 1;
  END IF;

  -- 7. Insert
  INSERT INTO public.property_comments
    (property_id, user_id, parent_comment_id, depth, text)
  VALUES
    (p_property_id, v_user_id, p_parent_comment_id, v_depth, p_text)
  RETURNING * INTO v_result;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."post_comment"("p_property_id" "uuid", "p_text" "text", "p_parent_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_owner_updating_admin_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  m            text := COALESCE(current_setting('reeve.system_action', true), '');
  fresh_relist boolean := (NEW.status = 'listed' AND OLD.status <> 'listed');
BEGIN
  IF public.is_admin() THEN
    RETURN NEW;
  END IF;

  IF NEW.current_listed_period_started_at IS DISTINCT FROM OLD.current_listed_period_started_at
     AND NOT (m = 'status_change' AND fresh_relist) THEN
    RAISE EXCEPTION 'permission denied: current_listed_period_started_at is server-managed';
  END IF;

  IF NEW.availability_confirmed_at IS DISTINCT FROM OLD.availability_confirmed_at
     AND NOT (m = 'confirm_rent'
              OR (m = 'status_change' AND fresh_relist AND NEW.listing_type = 'rent')) THEN
    RAISE EXCEPTION 'permission denied: availability_confirmed_at is server-managed';
  END IF;

  IF NEW.sale_listing_confirmed_at IS DISTINCT FROM OLD.sale_listing_confirmed_at
     AND NOT (m = 'confirm_sale'
              OR (m = 'status_change' AND fresh_relist AND NEW.listing_type = 'sale')) THEN
    RAISE EXCEPTION 'permission denied: sale_listing_confirmed_at is server-managed';
  END IF;

  IF (NEW.flat_number                   IS DISTINCT FROM OLD.flat_number)                   OR
     (NEW.board_status                  IS DISTINCT FROM OLD.board_status)                  OR
     (NEW.flat_number_revealed          IS DISTINCT FROM OLD.flat_number_revealed)          OR
     (NEW.auto_accept_enabled           IS DISTINCT FROM OLD.auto_accept_enabled)           OR
     (NEW.owner_diet_preference         IS DISTINCT FROM OLD.owner_diet_preference)         OR
     (NEW.owner_pet_preference          IS DISTINCT FROM OLD.owner_pet_preference)          OR
     (NEW.owner_tenant_type_preference  IS DISTINCT FROM OLD.owner_tenant_type_preference)  OR
     (NEW.last_public_listed_rent       IS DISTINCT FROM OLD.last_public_listed_rent)       OR
     (NEW.last_public_sale_price        IS DISTINCT FROM OLD.last_public_sale_price)        THEN
    RAISE EXCEPTION 'permission denied: only admins may update admin-only property fields';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_owner_updating_admin_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_user_privilege_escalation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF current_user NOT IN ('authenticated','anon') THEN RETURN NEW; END IF;
  IF is_admin() THEN RETURN NEW; END IF;
  IF NEW.role IS DISTINCT FROM OLD.role THEN RAISE EXCEPTION 'Not authorized to modify role' USING ERRCODE='42501'; END IF;
  IF NEW.email_verified IS DISTINCT FROM OLD.email_verified THEN RAISE EXCEPTION 'Not authorized to modify email_verified' USING ERRCODE='42501'; END IF;
  IF NEW.phone_verified IS DISTINCT FROM OLD.phone_verified THEN RAISE EXCEPTION 'Not authorized to modify phone_verified' USING ERRCODE='42501'; END IF;
  IF NEW.auth_provider IS DISTINCT FROM OLD.auth_provider THEN RAISE EXCEPTION 'Not authorized to modify auth_provider' USING ERRCODE='42501'; END IF;
  IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN RAISE EXCEPTION 'Not authorized to modify is_active' USING ERRCODE='42501'; END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."prevent_user_privilege_escalation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."property_activity_log_writer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  actor_role_val      text;
  action_val          text;
  is_public_val       boolean;
  summary_val         text;
  changed_field_keys  jsonb;
BEGIN
  actor_role_val := CASE WHEN public.is_admin() THEN 'admin' ELSE 'owner' END;

  IF TG_OP = 'INSERT' AND NEW.status = 'draft' THEN
    INSERT INTO public.property_activity_log
      (property_id, actor_id, actor_role, action, payload, is_public)
    VALUES
      (NEW.id, (SELECT auth.uid()), actor_role_val, 'listing_started',
       jsonb_build_object('summary', 'You started this listing'), false);
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
    IF current_setting('reeve.system_action', true) = 'auto_unlist'
       AND (SELECT auth.uid()) IS NULL THEN
      RETURN NEW;
    END IF;

    IF NEW.status::text = 'changes_requested' THEN
      RETURN NEW;
    END IF;

    action_val := CASE NEW.status::text
      WHEN 'pending_review'      THEN 'listing_submitted'
      WHEN 'changes_requested'   THEN 'listing_rejected'
      WHEN 'listed'              THEN CASE OLD.status::text
                                        WHEN 'pending_review'      THEN 'listing_approved'
                                        WHEN 'edit_pending_review' THEN 'edit_resolved'
                                        WHEN 'unlisted'            THEN 'relisted'
                                        ELSE 'status_changed'
                                      END
      WHEN 'edit_pending_review' THEN 'edit_submitted'
      WHEN 'unlisted'            THEN 'unlisted'
      WHEN 'archived'            THEN 'archived'
      WHEN 'draft'               THEN CASE OLD.status::text
                                        WHEN 'pending_review' THEN 'listing_withdrawn'
                                        ELSE 'status_changed'
                                      END
      ELSE 'status_changed'
    END;

    is_public_val := (NEW.status::text = 'listed' AND OLD.status::text IN ('pending_review','unlisted'))
                     OR NEW.status::text = 'unlisted';

    summary_val := 'Status changed from ' || OLD.status::text || ' to ' || NEW.status::text;

    INSERT INTO public.property_activity_log
      (property_id, actor_id, actor_role, action, payload, is_public)
    VALUES
      (NEW.id, (SELECT auth.uid()), actor_role_val, action_val,
       jsonb_build_object('summary', summary_val, 'from_status', OLD.status::text, 'to_status', NEW.status::text),
       is_public_val);
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.status = NEW.status
     AND public.is_admin()
     AND (
          OLD.listed_rent                  IS DISTINCT FROM NEW.listed_rent
       OR OLD.security_deposit_amount      IS DISTINCT FROM NEW.security_deposit_amount
       OR OLD.security_deposit_months      IS DISTINCT FROM NEW.security_deposit_months
       OR OLD.society_maintenance_approx   IS DISTINCT FROM NEW.society_maintenance_approx
       OR OLD.maintenance_included_in_rent IS DISTINCT FROM NEW.maintenance_included_in_rent
       OR OLD.description                  IS DISTINCT FROM NEW.description
       OR OLD.title                        IS DISTINCT FROM NEW.title
       OR OLD.furnishing                   IS DISTINCT FROM NEW.furnishing
       OR OLD.furnishing_detail::text      IS DISTINCT FROM NEW.furnishing_detail::text
       OR OLD.amenities::text              IS DISTINCT FROM NEW.amenities::text
       OR OLD.available_from               IS DISTINCT FROM NEW.available_from
       OR OLD.pet_policy                   IS DISTINCT FROM NEW.pet_policy
       OR OLD.building_rules               IS DISTINCT FROM NEW.building_rules
       OR OLD.building_notes               IS DISTINCT FROM NEW.building_notes
       OR OLD.parking_2w                   IS DISTINCT FROM NEW.parking_2w
       OR OLD.parking_4w                   IS DISTINCT FROM NEW.parking_4w
     )
  THEN
    changed_field_keys := '[]'::jsonb;
    IF OLD.listed_rent                  IS DISTINCT FROM NEW.listed_rent                  THEN changed_field_keys := changed_field_keys || '["listed_rent"]'::jsonb; END IF;
    IF OLD.security_deposit_amount      IS DISTINCT FROM NEW.security_deposit_amount      THEN changed_field_keys := changed_field_keys || '["security_deposit_amount"]'::jsonb; END IF;
    IF OLD.security_deposit_months      IS DISTINCT FROM NEW.security_deposit_months      THEN changed_field_keys := changed_field_keys || '["security_deposit_months"]'::jsonb; END IF;
    IF OLD.society_maintenance_approx   IS DISTINCT FROM NEW.society_maintenance_approx   THEN changed_field_keys := changed_field_keys || '["society_maintenance_approx"]'::jsonb; END IF;
    IF OLD.maintenance_included_in_rent IS DISTINCT FROM NEW.maintenance_included_in_rent THEN changed_field_keys := changed_field_keys || '["maintenance_included_in_rent"]'::jsonb; END IF;
    IF OLD.description                  IS DISTINCT FROM NEW.description                  THEN changed_field_keys := changed_field_keys || '["description"]'::jsonb; END IF;
    IF OLD.title                        IS DISTINCT FROM NEW.title                        THEN changed_field_keys := changed_field_keys || '["title"]'::jsonb; END IF;
    IF OLD.furnishing                   IS DISTINCT FROM NEW.furnishing                   THEN changed_field_keys := changed_field_keys || '["furnishing"]'::jsonb; END IF;
    IF OLD.furnishing_detail::text      IS DISTINCT FROM NEW.furnishing_detail::text      THEN changed_field_keys := changed_field_keys || '["furnishing_detail"]'::jsonb; END IF;
    IF OLD.amenities::text              IS DISTINCT FROM NEW.amenities::text              THEN changed_field_keys := changed_field_keys || '["amenities"]'::jsonb; END IF;
    IF OLD.available_from               IS DISTINCT FROM NEW.available_from               THEN changed_field_keys := changed_field_keys || '["available_from"]'::jsonb; END IF;
    IF OLD.pet_policy                   IS DISTINCT FROM NEW.pet_policy                   THEN changed_field_keys := changed_field_keys || '["pet_policy"]'::jsonb; END IF;
    IF OLD.building_rules               IS DISTINCT FROM NEW.building_rules               THEN changed_field_keys := changed_field_keys || '["building_rules"]'::jsonb; END IF;
    IF OLD.building_notes               IS DISTINCT FROM NEW.building_notes               THEN changed_field_keys := changed_field_keys || '["building_notes"]'::jsonb; END IF;
    IF OLD.parking_2w                   IS DISTINCT FROM NEW.parking_2w                   THEN changed_field_keys := changed_field_keys || '["parking_2w"]'::jsonb; END IF;
    IF OLD.parking_4w                   IS DISTINCT FROM NEW.parking_4w                   THEN changed_field_keys := changed_field_keys || '["parking_4w"]'::jsonb; END IF;

    INSERT INTO public.property_activity_log
      (property_id, actor_id, actor_role, action, payload, is_public)
    VALUES
      (NEW.id, (SELECT auth.uid()), 'admin', 'admin_edit',
       jsonb_build_object('summary', 'Admin made a direct edit', 'admin_id', (SELECT auth.uid())::text, 'changed_field_keys', changed_field_keys),
       false);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."property_activity_log_writer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reeve_custom_building_amenities"("p_am" "jsonb") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(array_agg(DISTINCT lower(btrim(val))), '{}')
  FROM jsonb_array_elements_text(
    CASE WHEN jsonb_typeof(p_am -> 'building') = 'array' THEN p_am -> 'building' ELSE '[]'::jsonb END) AS val
  WHERE btrim(COALESCE(val,'')) <> ''
    AND lower(btrim(val)) <> ALL (ARRAY[
      'lift','security_24hr','power_backup','gym','swimming_pool','clubhouse','visitor_parking',
      'cctv','children_play_area','intercom','park','maintenance_staff','gated_access','garden',
      'sports_facility','community_hall','water_supply_24hr','ev_charging','garbage_collection']);
$$;


ALTER FUNCTION "public"."reeve_custom_building_amenities"("p_am" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reeve_custom_furnishing_names"("p_fd" "jsonb") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(array_agg(DISTINCT lower(btrim(elem->>'item'))), '{}')
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_fd) = 'array' THEN p_fd ELSE '[]'::jsonb END) AS elem
  WHERE btrim(COALESCE(elem->>'item','')) <> ''
    AND lower(btrim(elem->>'item')) <> ALL (ARRAY[
      'bed','mattress','ac','wardrobe','geyser','fridge','washing_machine','tv','sofa',
      'dining_table','microwave','modular_kitchen','water_purifier','curtain_rod','stove',
      'chimney','fan','exhaust_fan']);
$$;


ALTER FUNCTION "public"."reeve_custom_furnishing_names"("p_fd" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reeve_geo_is_plausible"("p_lat" double precision, "p_lng" double precision, "p_center_lat" double precision, "p_center_lng" double precision, "p_bbox_ne_lat" double precision, "p_bbox_ne_lng" double precision, "p_bbox_sw_lat" double precision, "p_bbox_sw_lng" double precision, "p_kind" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_max_m   double precision;
  v_pad_deg double precision;
  v_dist    double precision;
BEGIN
  IF p_lat IS NULL OR p_lng IS NULL OR p_center_lat IS NULL OR p_center_lng IS NULL THEN
    RETURN false;
  END IF;

  IF p_kind = 'road' THEN v_max_m := 10000; v_pad_deg := 0.02;
  ELSE                    v_max_m := 3000;  v_pad_deg := 0;
  END IF;

  IF p_bbox_ne_lat IS NOT NULL AND p_bbox_sw_lat IS NOT NULL THEN
    IF p_lat >= p_bbox_sw_lat - v_pad_deg AND p_lat <= p_bbox_ne_lat + v_pad_deg
       AND p_lng >= p_bbox_sw_lng - v_pad_deg AND p_lng <= p_bbox_ne_lng + v_pad_deg THEN
      RETURN true;
    END IF;
  END IF;

  v_dist := extensions.ST_Distance(
    extensions.ST_SetSRID(extensions.ST_MakePoint(p_lng, p_lat), 4326)::geography,
    extensions.ST_SetSRID(extensions.ST_MakePoint(p_center_lng, p_center_lat), 4326)::geography);
  RETURN v_dist <= v_max_m;
END;
$$;


ALTER FUNCTION "public"."reeve_geo_is_plausible"("p_lat" double precision, "p_lng" double precision, "p_center_lat" double precision, "p_center_lng" double precision, "p_bbox_ne_lat" double precision, "p_bbox_ne_lng" double precision, "p_bbox_sw_lat" double precision, "p_bbox_sw_lng" double precision, "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reeve_introduces_new_custom"("p_old_fd" "jsonb", "p_new_fd" "jsonb", "p_old_am" "jsonb", "p_new_am" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    EXISTS (SELECT 1 FROM unnest(public.reeve_custom_furnishing_names(p_new_fd)) n
            WHERE n <> ALL (public.reeve_custom_furnishing_names(p_old_fd)))
    OR EXISTS (SELECT 1 FROM unnest(public.reeve_custom_building_amenities(p_new_am)) n
            WHERE n <> ALL (public.reeve_custom_building_amenities(p_old_am)));
$$;


ALTER FUNCTION "public"."reeve_introduces_new_custom"("p_old_fd" "jsonb", "p_new_fd" "jsonb", "p_old_am" "jsonb", "p_new_am" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reeve_search_geo_by_ids"("p_ids" "uuid"[]) RETURNS TABLE("id" "uuid", "display_name" "text", "kind" "text", "settlement_subtype" "text", "parent_geo_place_id" "uuid", "parent_display_name" "text", "search_region_id" "uuid", "search_region_display_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT g.id, g.display_name, g.kind, g.settlement_subtype,
         g.parent_geo_place_id, par.display_name AS parent_display_name,
         g.search_region_id, sr.display_name AS search_region_display_name
  FROM public.geo_places g
  LEFT JOIN public.geo_places par ON par.id = g.parent_geo_place_id
  LEFT JOIN public.geo_places sr  ON sr.id  = g.search_region_id
  WHERE g.id = ANY(coalesce(p_ids, '{}'::uuid[]))
    AND g.kind IN ('search_region','settlement','locality','road');
END;
$$;


ALTER FUNCTION "public"."reeve_search_geo_by_ids"("p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reeve_search_geo_suggest"("p_query" "text", "p_kinds" "text"[] DEFAULT NULL::"text"[], "p_parent_geo_place_id" "uuid" DEFAULT NULL::"uuid", "p_search_region_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "display_name" "text", "kind" "text", "settlement_subtype" "text", "parent_geo_place_id" "uuid", "parent_display_name" "text", "search_region_id" "uuid", "search_region_display_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_q     text := lower(btrim(coalesce(p_query, '')));
  v_lim   integer := least(greatest(coalesce(p_limit, 10), 1), 20);
  v_kinds text[];
BEGIN
  IF v_q = '' THEN RETURN; END IF;

  v_kinds := ARRAY(
    SELECT k FROM unnest(coalesce(p_kinds, ARRAY['search_region','settlement','locality','road'])) AS k
    WHERE k IN ('search_region','settlement','locality','road')
  );
  IF array_length(v_kinds, 1) IS NULL THEN RETURN; END IF;

  RETURN QUERY
  WITH matched AS (
    SELECT g.id, g.display_name, g.kind, g.settlement_subtype,
           g.parent_geo_place_id, g.search_region_id,
           CASE WHEN g.normalized_name = v_q THEN 0
                WHEN g.normalized_name LIKE v_q || '%' THEN 1
                ELSE 2 END AS rank
    FROM public.geo_places g
    WHERE g.kind = ANY(v_kinds)
      AND (p_parent_geo_place_id IS NULL OR g.parent_geo_place_id = p_parent_geo_place_id)
      AND (p_search_region_id IS NULL OR g.search_region_id = p_search_region_id)
      AND (
        g.normalized_name LIKE '%' || v_q || '%'
        OR EXISTS (
          SELECT 1 FROM public.geo_place_aliases al
          WHERE al.geo_place_id = g.id AND al.normalized_alias LIKE '%' || v_q || '%'
        )
      )
  ),
  deduped AS (
    SELECT m.id, m.display_name, m.kind, m.settlement_subtype, m.parent_geo_place_id, m.search_region_id, m.rank
    FROM (
      SELECT m.*, row_number() OVER (PARTITION BY m.id ORDER BY m.rank, m.display_name) AS rn
      FROM matched m
    ) m
    WHERE m.rn = 1
  )
  SELECT d.id, d.display_name, d.kind, d.settlement_subtype,
         d.parent_geo_place_id, par.display_name AS parent_display_name,
         d.search_region_id, sr.display_name AS search_region_display_name
  FROM deduped d
  LEFT JOIN public.geo_places par ON par.id = d.parent_geo_place_id
  LEFT JOIN public.geo_places sr  ON sr.id  = d.search_region_id
  ORDER BY d.rank, d.display_name
  LIMIT v_lim;
END;
$$;


ALTER FUNCTION "public"."reeve_search_geo_suggest"("p_query" "text", "p_kinds" "text"[], "p_parent_geo_place_id" "uuid", "p_search_region_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reeve_search_property_ids_v2"("p_geo_place_ids" "uuid"[], "p_distance_km" numeric) RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_ids      uuid[];
  v_root     uuid[];
  v_detail   uuid[];
  v_locality uuid[];
  v_found    integer;
BEGIN
  IF p_distance_km IS NOT NULL AND p_distance_km NOT IN (2,5,10,20,30,50) THEN
    RAISE EXCEPTION 'invalid_radius';
  END IF;

  v_ids := ARRAY(SELECT DISTINCT x FROM unnest(coalesce(p_geo_place_ids, '{}'::uuid[])) x WHERE x IS NOT NULL);

  IF array_length(v_ids, 1) IS NULL THEN
    IF p_distance_km IS NOT NULL THEN RAISE EXCEPTION 'radius_requires_locality'; END IF;
    RETURN;
  END IF;

  SELECT count(*) INTO v_found
    FROM public.geo_places g
   WHERE g.id = ANY(v_ids) AND g.kind IN ('search_region','settlement','locality','road');
  IF v_found <> array_length(v_ids, 1) THEN RAISE EXCEPTION 'invalid_anchor'; END IF;

  v_root     := ARRAY(SELECT g.id FROM public.geo_places g WHERE g.id = ANY(v_ids) AND g.kind IN ('search_region','settlement'));
  v_detail   := ARRAY(SELECT g.id FROM public.geo_places g WHERE g.id = ANY(v_ids) AND g.kind IN ('locality','road'));
  v_locality := ARRAY(SELECT g.id FROM public.geo_places g WHERE g.id = ANY(v_ids) AND g.kind = 'locality');

  IF p_distance_km IS NOT NULL THEN
    IF array_length(v_locality, 1) IS NULL THEN RAISE EXCEPTION 'radius_requires_locality'; END IF;
    IF EXISTS (SELECT 1 FROM public.geo_places g WHERE g.id = ANY(v_locality) AND g.representative_point IS NULL) THEN
      RAISE EXCEPTION 'locality_no_representative_point';
    END IF;
    RETURN QUERY
      SELECT DISTINCT p.id
      FROM public.properties p
      JOIN public.geo_places g ON g.id = ANY(v_locality)
      WHERE p.geom_exact IS NOT NULL
        AND ST_DWithin(p.geom_exact::geography, g.representative_point::geography, (p_distance_km * 1000.0)::float8);
    RETURN;
  END IF;

  IF array_length(v_root, 1) IS NOT NULL AND array_length(v_detail, 1) IS NOT NULL THEN
    RETURN QUERY
      SELECT DISTINCT a.property_id FROM public.property_geo_associations a
      WHERE a.relationship IS NULL AND a.geo_place_id = ANY(v_detail)
        AND a.property_id IN (
          SELECT a2.property_id FROM public.property_geo_associations a2
          WHERE a2.relationship IS NULL AND a2.geo_place_id = ANY(v_root)
        );
  ELSIF array_length(v_root, 1) IS NOT NULL THEN
    RETURN QUERY
      SELECT DISTINCT a.property_id FROM public.property_geo_associations a
      WHERE a.relationship IS NULL AND a.geo_place_id = ANY(v_root);
  ELSE
    RETURN QUERY
      SELECT DISTINCT a.property_id FROM public.property_geo_associations a
      WHERE a.relationship IS NULL AND a.geo_place_id = ANY(v_detail);
  END IF;
  RETURN;
END;
$$;


ALTER FUNCTION "public"."reeve_search_property_ids_v2"("p_geo_place_ids" "uuid"[], "p_distance_km" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_edit_request"("p_edit_request_id" "uuid", "p_reason" "text", "p_reason_text" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_property_id uuid;
  v_status      text;
  v_admin_id    uuid := (SELECT auth.uid());
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT property_id, status
    INTO v_property_id, v_status
    FROM public.property_edit_requests
   WHERE id = p_edit_request_id
   FOR UPDATE;

  IF v_property_id IS NULL THEN
    RAISE EXCEPTION 'Edit request not found';
  END IF;

  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'Edit request is no longer pending';
  END IF;

  -- Property returns to listed (D-094).
  UPDATE public.properties
     SET status = 'listed'
   WHERE id = v_property_id
     AND status = 'edit_pending_review';

  UPDATE public.property_edit_requests
     SET status                = 'rejected',
         rejection_reason      = p_reason,
         rejection_reason_text = p_reason_text,
         reviewed_by           = v_admin_id,
         reviewed_at           = now()
   WHERE id = p_edit_request_id;

  INSERT INTO public.property_activity_log
    (property_id, actor_id, actor_role, action, payload, is_public)
  VALUES (
    v_property_id,
    v_admin_id,
    'admin',
    'edit_rejected',
    jsonb_build_object(
      'summary',         'Your edit was rejected',
      'edit_request_id', p_edit_request_id::text,
      'admin_id',        v_admin_id::text,
      'reason',          p_reason,
      'reason_text',     COALESCE(p_reason_text, '')
    ),
    false
  );
END;
$$;


ALTER FUNCTION "public"."reject_edit_request"("p_edit_request_id" "uuid", "p_reason" "text", "p_reason_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_property_listing"("p_property_id" "uuid", "p_reason" "text", "p_reason_text" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status   text;
  v_admin_id uuid := (SELECT auth.uid());
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'Rejection reason is required';
  END IF;

  SELECT status INTO v_status
    FROM public.properties
   WHERE id = p_property_id
   FOR UPDATE;

  IF v_status IS NULL THEN
    RAISE EXCEPTION 'Property not found';
  END IF;

  IF v_status <> 'pending_review' THEN
    RAISE EXCEPTION 'Property is not pending review (current status: %)', v_status;
  END IF;

  UPDATE public.properties
     SET status = 'changes_requested'
   WHERE id = p_property_id;

  INSERT INTO public.property_activity_log
    (property_id, actor_id, actor_role, action, payload, is_public)
  VALUES (
    p_property_id,
    v_admin_id,
    'admin',
    'listing_rejected',
    jsonb_build_object(
      'summary',      'Your listing needs changes',
      'from_status',  'pending_review',
      'to_status',    'changes_requested',
      'admin_id',     v_admin_id::text,
      'reason',       p_reason,
      'reason_text',  COALESCE(p_reason_text, '')
    ),
    false
  );
END;
$$;


ALTER FUNCTION "public"."reject_property_listing"("p_property_id" "uuid", "p_reason" "text", "p_reason_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reject_property_listing"("p_property_id" "uuid", "p_reason" "text", "p_reason_text" "text") IS 'Admin-only. Transitions property from pending_review to changes_requested. Persists reason in activity log for H1 persistent panel. Phase 1.5 Prompt 11.';



CREATE OR REPLACE FUNCTION "public"."replace_property_discovery_geography"("p_property_id" "uuid", "p_associations" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_owner uuid;
  v_geom extensions.geometry(Point,4326);
  v_elem jsonb;
  v_gp public.geo_places%ROWTYPE;
  v_seen uuid[] := '{}';
  v_gid uuid;
  v_primary_count int := 0;
BEGIN
  SELECT owner_id, geom_exact INTO v_owner, v_geom FROM public.properties WHERE id = p_property_id FOR UPDATE;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'property not found'; END IF;
  IF p_associations IS NULL OR jsonb_typeof(p_associations) <> 'array' THEN
    RAISE EXCEPTION 'associations must be a jsonb array';
  END IF;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_associations) LOOP
    IF v_elem ? 'relationship' OR v_elem ? 'confidence' THEN
      RAISE EXCEPTION 'final payload must not include legacy relationship/confidence';
    END IF;
    v_gid := (v_elem->>'geo_place_id')::uuid;
    IF v_gid = ANY(v_seen) THEN RAISE EXCEPTION 'duplicate geo_place_id % in payload', v_gid; END IF;
    v_seen := v_seen || v_gid;
    SELECT * INTO v_gp FROM public.geo_places WHERE id = v_gid;
    IF v_gp.id IS NULL THEN RAISE EXCEPTION 'geo_place % not found', v_gid; END IF;
    IF v_gp.kind NOT IN ('search_region','settlement','locality','road') THEN
      RAISE EXCEPTION 'geo_place % is not a final kind (%)', v_gid, v_gp.kind;
    END IF;
    IF COALESCE(v_elem->>'source','') NOT IN ('system','owner','admin') THEN
      RAISE EXCEPTION 'invalid source for geo_place %', v_gid;
    END IF;
    IF COALESCE(btrim(v_elem->>'evidence_type'),'') = '' THEN
      RAISE EXCEPTION 'evidence_type required for geo_place %', v_gid;
    END IF;
    IF (v_elem->>'is_primary')::boolean IS TRUE THEN
      v_primary_count := v_primary_count + 1;
      IF v_gp.kind NOT IN ('search_region','settlement') THEN
        RAISE EXCEPTION 'primary must be search_region/settlement, got % for %', v_gp.kind, v_gid;
      END IF;
    END IF;
  END LOOP;
  IF v_primary_count > 1 THEN RAISE EXCEPTION 'at most one primary association'; END IF;

  PERFORM set_config('reeve.system_action', 'geo_discovery', true);

  DELETE FROM public.property_geo_associations WHERE property_id = p_property_id;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_associations) LOOP
    SELECT * INTO v_gp FROM public.geo_places WHERE id = (v_elem->>'geo_place_id')::uuid;
    INSERT INTO public.property_geo_associations
      (property_id, geo_place_id, relationship, confidence, is_primary, source, evidence_type, distance_m)
    VALUES (
      p_property_id, v_gp.id, NULL, NULL,
      COALESCE((v_elem->>'is_primary')::boolean, false),
      v_elem->>'source', v_elem->>'evidence_type',
      CASE WHEN v_geom IS NOT NULL AND v_gp.representative_point IS NOT NULL
           THEN extensions.ST_Distance(v_geom::geography, v_gp.representative_point::geography)
           ELSE NULL END
    );
  END LOOP;

  UPDATE public.properties SET discovery_confirmed_at = NULL, discovery_finalized_at = NULL WHERE id = p_property_id;
END;
$$;


ALTER FUNCTION "public"."replace_property_discovery_geography"("p_property_id" "uuid", "p_associations" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."replace_property_discovery_geography"("p_property_id" "uuid", "p_associations" "jsonb") IS 'Trusted atomic replace of a property''s FINAL discovery associations (relationship/confidence NULL; server-computed distance_m). Resets discovery_confirmed_at/finalized_at.';



CREATE OR REPLACE FUNCTION "public"."report_comment"("p_comment_id" "uuid", "p_reason" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id     uuid := auth.uid();
  v_phone_ver   boolean;
  v_email_ver   boolean;
  v_is_deleted  boolean;
  v_auto_hidden boolean;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  SELECT phone_verified, email_verified
  INTO v_phone_ver, v_email_ver
  FROM public.users WHERE id = v_user_id;

  IF NOT (v_phone_ver AND v_email_ver) THEN
    RAISE EXCEPTION 'VERIFICATION_INCOMPLETE';
  END IF;

  SELECT is_deleted INTO v_is_deleted
  FROM public.property_comments
  WHERE id = p_comment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'COMMENT_NOT_FOUND';
  END IF;
  IF v_is_deleted THEN
    RAISE EXCEPTION 'COMMENT_UNAVAILABLE';
  END IF;

  IF p_reason NOT IN ('spam','abusive','false_information','other') THEN
    RAISE EXCEPTION 'INVALID_REASON';
  END IF;

  IF p_reason = 'other' AND (p_notes IS NULL OR trim(p_notes) = '') THEN
    RAISE EXCEPTION 'NOTES_REQUIRED';
  END IF;

  BEGIN
    INSERT INTO public.comment_reports (comment_id, reporter_id, reason, notes)
    VALUES (
      p_comment_id,
      v_user_id,
      p_reason,
      NULLIF(trim(COALESCE(p_notes, '')), '')
    );
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'ALREADY_REPORTED';
  END;

  SELECT (is_deleted AND hidden_reason = 'auto_hidden_reports')
  INTO v_auto_hidden
  FROM public.property_comments
  WHERE id = p_comment_id;

  RETURN jsonb_build_object('success', true, 'auto_hidden', COALESCE(v_auto_hidden, false));
END;
$$;


ALTER FUNCTION "public"."report_comment"("p_comment_id" "uuid", "p_reason" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_canonical_geo_place"("p_kind" "text", "p_display_name" "text", "p_settlement_subtype" "text" DEFAULT NULL::"text", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_anchor_quality" "text" DEFAULT NULL::"text", "p_parent_geo_place_id" "uuid" DEFAULT NULL::"uuid", "p_search_region_id" "uuid" DEFAULT NULL::"uuid", "p_provider" "text" DEFAULT NULL::"text", "p_provider_place_id" "text" DEFAULT NULL::"text", "p_provider_type" "text" DEFAULT NULL::"text", "p_aliases" "text"[] DEFAULT NULL::"text"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_norm text;
  v_id uuid;
  v_existing_kind text;
  v_ref_place uuid;
  v_existing_ref uuid;
  v_rep extensions.geometry(Point,4326);
  v_cand_ids uuid[];
  v_threshold double precision;
  v_count int;
BEGIN
  IF p_kind NOT IN ('search_region','settlement','locality','road') THEN
    RAISE EXCEPTION 'resolve_canonical_geo_place accepts final kinds only, got %', p_kind;
  END IF;
  IF btrim(COALESCE(p_display_name,'')) = '' THEN RAISE EXCEPTION 'display_name required'; END IF;
  IF (p_provider IS NULL) <> (p_provider_place_id IS NULL) THEN
    RAISE EXCEPTION 'provider and provider_place_id must both be set or both null';
  END IF;
  IF (p_lat IS NULL) <> (p_lng IS NULL) THEN
    RAISE EXCEPTION 'lat and lng must both be set or both null';
  END IF;
  IF p_lat IS NOT NULL AND (p_lat < -90 OR p_lat > 90 OR p_lng < -180 OR p_lng > 180) THEN
    RAISE EXCEPTION 'coordinates out of range';
  END IF;
  IF p_settlement_subtype IS NOT NULL THEN
    IF p_kind <> 'settlement' THEN RAISE EXCEPTION 'settlement_subtype only valid for settlement'; END IF;
    IF p_settlement_subtype NOT IN ('city','town','village') THEN RAISE EXCEPTION 'invalid settlement_subtype %', p_settlement_subtype; END IF;
  END IF;
  IF p_provider IS NOT NULL THEN
    p_provider := lower(btrim(p_provider));
    IF p_provider = '' OR btrim(p_provider_place_id) = '' THEN RAISE EXCEPTION 'provider/provider_place_id must be non-blank'; END IF;
  END IF;
  IF p_search_region_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.geo_places WHERE id = p_search_region_id AND kind = 'search_region') THEN
      RAISE EXCEPTION 'search_region_id must reference a search_region';
    END IF;
  END IF;

  v_norm := lower(btrim(p_display_name));
  IF p_lat IS NOT NULL THEN
    v_rep := extensions.ST_SetSRID(extensions.ST_MakePoint(p_lng, p_lat), 4326);
  END IF;

  IF p_provider IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext(p_provider || ':' || p_provider_place_id)::bigint);
  ELSE
    PERFORM pg_advisory_xact_lock(hashtext(
      p_kind || '|' || v_norm || '|' || COALESCE(p_settlement_subtype,'') || '|' ||
      COALESCE(p_parent_geo_place_id::text,'') || '|' || COALESCE(p_search_region_id::text,''))::bigint);
  END IF;

  IF p_provider IS NOT NULL THEN
    SELECT geo_place_id INTO v_ref_place FROM public.geo_provider_refs
      WHERE provider = p_provider AND provider_place_id = p_provider_place_id;
    IF v_ref_place IS NOT NULL THEN
      SELECT kind INTO v_existing_kind FROM public.geo_places WHERE id = v_ref_place;
      IF v_existing_kind = p_kind THEN
        NULL;
      ELSIF v_existing_kind = 'city' AND p_kind IN ('search_region','settlement') THEN
        UPDATE public.geo_places SET kind = p_kind WHERE id = v_ref_place;
      ELSIF v_existing_kind = 'area' AND p_kind IN ('locality','road') THEN
        UPDATE public.geo_places SET kind = p_kind WHERE id = v_ref_place;
      ELSIF v_existing_kind = 'road' AND p_kind = 'road' THEN
        NULL;
      ELSE
        RAISE EXCEPTION 'provider identity points to kind % incompatible with requested %', v_existing_kind, p_kind;
      END IF;
      UPDATE public.geo_places SET
        settlement_subtype  = CASE WHEN kind = 'settlement' THEN COALESCE(settlement_subtype, p_settlement_subtype) ELSE settlement_subtype END,
        representative_point = COALESCE(representative_point, v_rep),
        anchor_quality      = COALESCE(anchor_quality, p_anchor_quality),
        parent_geo_place_id = COALESCE(parent_geo_place_id, p_parent_geo_place_id),
        search_region_id    = COALESCE(search_region_id, p_search_region_id)
      WHERE id = v_ref_place;
      UPDATE public.geo_provider_refs
        SET last_verified_at = now(), provider_type = COALESCE(provider_type, p_provider_type)
        WHERE provider = p_provider AND provider_place_id = p_provider_place_id;
      PERFORM public._geo_insert_aliases(v_ref_place, p_aliases);
      RETURN v_ref_place;
    END IF;
  END IF;

  v_cand_ids := ARRAY(
    SELECT g.id FROM public.geo_places g
    WHERE g.kind = p_kind
      AND g.parent_geo_place_id IS NOT DISTINCT FROM p_parent_geo_place_id
      AND g.search_region_id    IS NOT DISTINCT FROM p_search_region_id
      AND (p_kind <> 'settlement' OR g.settlement_subtype IS NOT DISTINCT FROM p_settlement_subtype)
      AND (
        g.normalized_name = v_norm
        OR EXISTS (SELECT 1 FROM public.geo_place_aliases al WHERE al.geo_place_id = g.id AND al.normalized_alias = v_norm)
      )
  );

  IF v_rep IS NOT NULL AND p_kind IN ('locality','road','settlement') THEN
    v_threshold := CASE WHEN p_kind = 'settlement' THEN 25000 ELSE 5000 END;
    v_cand_ids := ARRAY(
      SELECT g.id FROM public.geo_places g
      WHERE g.id = ANY(v_cand_ids)
        AND (g.representative_point IS NULL
             OR extensions.ST_DWithin(g.representative_point::geography, v_rep::geography, v_threshold))
    );
  END IF;

  v_count := COALESCE(array_length(v_cand_ids, 1), 0);
  IF v_count > 1 THEN
    RAISE EXCEPTION 'ambiguous canonical match for "%" (% candidates) — refusing silent merge', v_norm, v_count;
  ELSIF v_count = 1 THEN
    v_id := v_cand_ids[1];
    IF p_provider IS NOT NULL THEN
      SELECT geo_place_id INTO v_existing_ref FROM public.geo_provider_refs
        WHERE provider = p_provider AND provider_place_id = p_provider_place_id;
      IF v_existing_ref IS NULL THEN
        INSERT INTO public.geo_provider_refs (geo_place_id, provider, provider_place_id, provider_type, last_verified_at)
          VALUES (v_id, p_provider, p_provider_place_id, p_provider_type, now());
      ELSIF v_existing_ref <> v_id THEN
        RAISE EXCEPTION 'provider identity already maps to a different canonical place';
      END IF;
      IF p_provider = 'google' THEN
        UPDATE public.geo_places SET place_id = COALESCE(place_id, p_provider_place_id) WHERE id = v_id;
      END IF;
    END IF;
    PERFORM public._geo_insert_aliases(v_id, p_aliases);
    RETURN v_id;
  END IF;

  INSERT INTO public.geo_places (
    display_name, kind, normalized_name, settlement_subtype, representative_point,
    anchor_quality, parent_geo_place_id, search_region_id, place_id
  ) VALUES (
    btrim(p_display_name), p_kind, v_norm,
    CASE WHEN p_kind = 'settlement' THEN p_settlement_subtype END,
    v_rep, p_anchor_quality, p_parent_geo_place_id, p_search_region_id,
    CASE WHEN p_provider = 'google' THEN p_provider_place_id ELSE NULL END
  ) RETURNING id INTO v_id;

  IF p_provider IS NOT NULL THEN
    INSERT INTO public.geo_provider_refs (geo_place_id, provider, provider_place_id, provider_type, last_verified_at)
      VALUES (v_id, p_provider, p_provider_place_id, p_provider_type, now());
  END IF;
  PERFORM public._geo_insert_aliases(v_id, p_aliases);
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."resolve_canonical_geo_place"("p_kind" "text", "p_display_name" "text", "p_settlement_subtype" "text", "p_lat" double precision, "p_lng" double precision, "p_anchor_quality" "text", "p_parent_geo_place_id" "uuid", "p_search_region_id" "uuid", "p_provider" "text", "p_provider_place_id" "text", "p_provider_type" "text", "p_aliases" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_canonical_geo_place"("p_kind" "text", "p_display_name" "text", "p_settlement_subtype" "text", "p_lat" double precision, "p_lng" double precision, "p_anchor_quality" "text", "p_parent_geo_place_id" "uuid", "p_search_region_id" "uuid", "p_provider" "text", "p_provider_place_id" "text", "p_provider_type" "text", "p_aliases" "text"[]) IS 'Trusted final canonical get-or-create. Identity = geo_places.id via geo_provider_refs; final kinds only; idempotent (advisory lock); deterministic exact match + kind-scoped proximity net; never fuzzy-merges. Phase 2 calls this.';



CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_stale_listing_sweep"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r record; v_count integer := 0;
BEGIN
  PERFORM set_config('reeve.system_action', 'auto_unlist', true);
  FOR r IN
    WITH upd AS (
      UPDATE public.properties p
         SET status = 'unlisted'
       WHERE p.status = 'listed'
         AND (
           (p.listing_type = 'rent'
             AND COALESCE(p.availability_confirmed_at, p.current_listed_period_started_at, p.listed_at) < now() - interval '30 days')
           OR
           (p.listing_type = 'sale'
             AND COALESCE(p.sale_listing_confirmed_at, p.current_listed_period_started_at, p.listed_at) < now() - interval '60 days')
         )
      RETURNING p.id
    )
    SELECT id FROM upd
  LOOP
    INSERT INTO public.property_activity_log (property_id, actor_id, actor_role, action, payload, is_public)
    VALUES (r.id, NULL, 'system', 'auto_unlisted',
      jsonb_build_object(
        'summary', 'Your listing was automatically unlisted because its availability wasn''t confirmed in time. Re-list anytime to make it visible again.',
        'from_status', 'listed', 'to_status', 'unlisted', 'reason', 'stale_no_confirmation'),
      false);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."run_stale_listing_sweep"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_compact_properties_v3"("p_listing_type" "public"."property_listing_type", "p_property_type" "text" DEFAULT NULL::"text", "p_bhk" "text"[] DEFAULT '{}'::"text"[], "p_furnishing" "text"[] DEFAULT '{}'::"text"[], "p_min_price" numeric DEFAULT NULL::numeric, "p_max_price" numeric DEFAULT NULL::numeric, "p_available_by" "date" DEFAULT NULL::"date", "p_listed_within_days" integer DEFAULT NULL::integer, "p_availability_confirmed_within_days" integer DEFAULT NULL::integer, "p_max_deposit" numeric DEFAULT NULL::numeric, "p_max_lock_in_months" integer DEFAULT NULL::integer, "p_max_notice_days" integer DEFAULT NULL::integer, "p_max_annual_increase" numeric DEFAULT NULL::numeric, "p_max_move_in_charges" numeric DEFAULT NULL::numeric, "p_pet_policy" "text"[] DEFAULT '{}'::"text"[], "p_possession_status" "text"[] DEFAULT '{}'::"text"[], "p_possession_before" "date" DEFAULT NULL::"date", "p_negotiable" boolean DEFAULT NULL::boolean, "p_min_carpet_area" numeric DEFAULT NULL::numeric, "p_max_carpet_area" numeric DEFAULT NULL::numeric, "p_min_super_built_up" numeric DEFAULT NULL::numeric, "p_max_super_built_up" numeric DEFAULT NULL::numeric, "p_parking_4w" "text"[] DEFAULT '{}'::"text"[], "p_parking_2w" "text"[] DEFAULT '{}'::"text"[], "p_amenities" "text"[] DEFAULT '{}'::"text"[], "p_has_video_walkthrough" boolean DEFAULT NULL::boolean, "p_min_response_rate" numeric DEFAULT NULL::numeric, "p_has_experience_feedback" boolean DEFAULT NULL::boolean, "p_sort" "text" DEFAULT 'newest'::"text", "p_cursor_listed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid", "p_cursor_availability_confirmed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_price_amount" numeric DEFAULT NULL::numeric, "p_limit" integer DEFAULT 20, "p_zero_rent_brokerage" boolean DEFAULT NULL::boolean, "p_max_rent_brokerage_fixed" numeric DEFAULT NULL::numeric, "p_max_sale_brokerage_pct" numeric DEFAULT NULL::numeric, "p_rera_disclosed" boolean DEFAULT NULL::boolean, "p_khata_type" "text"[] DEFAULT '{}'::"text"[], "p_property_tax_paid" boolean DEFAULT NULL::boolean, "p_geo_place_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_distance_km" numeric DEFAULT NULL::numeric) RETURNS TABLE("property_id" "uuid", "listing_type" "text", "property_type" "text", "bhk" "text", "owner_id" "uuid", "primary_image_url" "text", "photo_count" integer, "price_kind" "text", "price_amount" numeric, "building_name" "text", "locality" "text", "city" "text", "location_mode" "text", "latitude" numeric, "longitude" numeric, "carpet_area_sqft" numeric, "super_built_up_sqft" numeric, "furnishing" "text", "bathrooms" smallint, "floor_number" smallint, "total_floors" smallint, "parking_4w" "text", "parking_2w" "text", "parking_4w_count" integer, "parking_2w_count" integer, "building_age_years" smallint, "possession_status" "text", "possession_date" "date", "lister_role" "text", "response_handled_count" integer, "response_rate_pct" numeric, "experience_feedback" "jsonb", "listed_at" timestamp with time zone, "availability_confirmed_at" timestamp with time zone, "rent_brokerage_type" "text", "rent_brokerage_fixed_amount" numeric, "rent_brokerage_months" numeric, "sale_brokerage_pct" numeric, "security_deposit_amount" numeric, "lock_in_months" integer, "notice_period_days" integer, "pet_policy" "text", "youtube_walkthrough_url" "text", "price_negotiable" boolean, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_sort NOT IN ('newest','availability_confirmed','price_asc','price_desc') THEN
    RAISE EXCEPTION 'invalid_sort' USING DETAIL = format('Unknown sort value: %s', p_sort);
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 20 THEN p_limit := 20; END IF;

  RETURN QUERY
  WITH base AS (
    SELECT
      p.id AS property_id, p.listing_type::text AS listing_type, p.property_type::text AS property_type,
      p.bhk::text AS bhk, p.owner_id AS owner_id, p.building_name::text AS building_name,
      p.locality::text AS locality, p.city::text AS city, p.latitude AS latitude, p.longitude AS longitude,
      p.square_footage AS carpet_area_sqft, p.super_built_up_area AS super_built_up_sqft,
      p.furnishing::text AS furnishing, p.bathrooms AS bathrooms, p.floor_number AS floor_number,
      p.total_floors AS total_floors, p.parking_4w::text AS parking_4w, p.parking_2w::text AS parking_2w,
      p.parking_4w_count AS parking_4w_count, p.parking_2w_count AS parking_2w_count,
      p.building_age_years AS building_age_years, p.possession_status AS possession_status,
      p.possession_date AS possession_date, p.lister_role AS lister_role,
      p.listed_at AS listed_at, p.availability_confirmed_at AS availability_confirmed_at,
      p.rent_brokerage_type AS rent_brokerage_type, p.rent_brokerage_fixed_amount AS rent_brokerage_fixed_amount,
      p.rent_brokerage_months AS rent_brokerage_months, p.sale_brokerage_pct AS sale_brokerage_pct,
      p.security_deposit_amount AS security_deposit_amount, p.lock_in_months AS lock_in_months,
      p.notice_period_days AS notice_period_days, p.pet_policy AS pet_policy,
      p.youtube_walkthrough_url AS youtube_walkthrough_url, p.price_negotiable AS price_negotiable,
      CASE WHEN p.listing_type='rent' AND p.listed_rent=0 THEN NULL
           WHEN p.listing_type='rent' AND p.maintenance_included_in_rent=true THEN 'rent_total'
           WHEN p.listing_type='rent' AND p.maintenance_included_in_rent=false AND p.society_maintenance_approx IS NOT NULL THEN 'rent_total'
           WHEN p.listing_type='rent' THEN 'rent_monthly'
           WHEN p.listing_type='sale' AND p.sale_price IS NOT NULL THEN 'sale'
           ELSE NULL END AS resolved_price_kind,
      CASE WHEN p.listing_type='rent' AND p.listed_rent=0 THEN NULL
           WHEN p.listing_type='rent' AND p.maintenance_included_in_rent=true THEN p.listed_rent
           WHEN p.listing_type='rent' AND p.maintenance_included_in_rent=false AND p.society_maintenance_approx IS NOT NULL THEN p.listed_rent+p.society_maintenance_approx
           WHEN p.listing_type='rent' THEN p.listed_rent
           WHEN p.listing_type='sale' THEN p.sale_price
           ELSE NULL END AS resolved_price_amount,
      CASE WHEN p.address_mode='google_place' THEN 'exact'
           WHEN p.address_mode='manual' THEN 'approximate'
           ELSE NULL END AS resolved_location_mode,
      (SELECT pi.url FROM public.property_images pi WHERE pi.property_id=p.id AND pi.is_primary=true AND pi.is_floor_plan=false LIMIT 1) AS primary_image_url,
      (SELECT COUNT(*)::integer FROM public.property_images pi WHERE pi.property_id=p.id AND pi.is_floor_plan=false) AS photo_count,
      (SELECT COUNT(*)::integer FROM public.contact_requests cr WHERE cr.owner_id=p.owner_id AND cr.status NOT IN ('withdrawn','auto_cancelled')) AS response_handled_count,
      (SELECT ROUND(COUNT(*) FILTER (WHERE cr.status IN ('approved','declined'))::numeric/NULLIF(COUNT(*) FILTER (WHERE cr.status NOT IN ('withdrawn','auto_cancelled')),0)*100) FROM public.contact_requests cr WHERE cr.owner_id=p.owner_id) AS response_rate_pct,
      (SELECT CASE WHEN COUNT(*) FILTER (WHERE ir.t_q3_deal_again IS NOT NULL)>=3 THEN jsonb_build_object('totalRatings',COUNT(*) FILTER (WHERE ir.t_q3_deal_again IS NOT NULL),'dealAgainPct',ROUND(COUNT(*) FILTER (WHERE ir.t_q3_deal_again='yes')::numeric/NULLIF(COUNT(*) FILTER (WHERE ir.t_q3_deal_again IS NOT NULL),0)*100),'reviewCount',COUNT(*) FILTER (WHERE ir.t_review_text IS NOT NULL AND trim(ir.t_review_text)!='')) ELSE NULL END FROM public.interaction_ratings ir WHERE ir.owner_id=p.owner_id AND ((ir.t_submitted_at IS NOT NULL AND ir.o_submitted_at IS NOT NULL) OR now()>ir.window_closes_at)) AS experience_feedback
    FROM public.properties p
    WHERE p.status IN ('listed','edit_pending_review') AND p.is_active=true AND p.listing_type=p_listing_type
      AND ((coalesce(array_length(p_geo_place_ids,1),0)=0 AND p_distance_km IS NULL)
           OR p.id IN (SELECT public.reeve_search_property_ids_v2(p_geo_place_ids, p_distance_km)))
      AND (p_property_type IS NULL OR (btrim(coalesce(p_property_type,'')) = '' OR p.property_type::text = ANY(string_to_array(p_property_type, ','))))
      AND (array_length(p_bhk,1) IS NULL OR p.bhk::text=ANY(p_bhk))
      AND (array_length(p_furnishing,1) IS NULL OR p.furnishing::text=ANY(p_furnishing))
      AND (p_available_by IS NULL OR p.available_from IS NULL OR p.available_from<=p_available_by)
      AND (p_listed_within_days IS NULL OR p.listed_at>=now()-(p_listed_within_days*interval '1 day'))
      AND (p_availability_confirmed_within_days IS NULL OR p.availability_confirmed_at>=now()-(p_availability_confirmed_within_days*interval '1 day'))
      AND (p_max_deposit IS NULL OR p.security_deposit_amount IS NULL OR p.security_deposit_amount<=p_max_deposit)
      AND (p_max_lock_in_months IS NULL OR p.lock_in_months IS NULL OR p.lock_in_months<=p_max_lock_in_months)
      AND (p_max_notice_days IS NULL OR p.notice_period_days IS NULL OR p.notice_period_days<=p_max_notice_days)
      AND (p_max_annual_increase IS NULL OR p.annual_rent_increase_pct IS NULL OR p.annual_rent_increase_pct<=p_max_annual_increase)
      AND (p_max_move_in_charges IS NULL OR p.move_in_charges_amount IS NULL OR p.move_in_charges_amount<=p_max_move_in_charges)
      AND (array_length(p_pet_policy,1) IS NULL OR p.pet_policy=ANY(p_pet_policy))
      AND (array_length(p_possession_status,1) IS NULL OR p.possession_status=ANY(p_possession_status))
      AND (p_possession_before IS NULL OR p.possession_date IS NULL OR p.possession_date<=p_possession_before)
      AND (p_negotiable IS NULL OR p.price_negotiable=p_negotiable)
      AND (p_min_carpet_area IS NULL OR p.square_footage IS NULL OR p.square_footage>=p_min_carpet_area)
      AND (p_max_carpet_area IS NULL OR p.square_footage IS NULL OR p.square_footage<=p_max_carpet_area)
      AND (p_min_super_built_up IS NULL OR p.super_built_up_area IS NULL OR p.super_built_up_area>=p_min_super_built_up)
      AND (p_max_super_built_up IS NULL OR p.super_built_up_area IS NULL OR p.super_built_up_area<=p_max_super_built_up)
      AND (array_length(p_parking_4w,1) IS NULL OR p.parking_4w::text=ANY(p_parking_4w))
      AND (array_length(p_parking_2w,1) IS NULL OR p.parking_2w::text=ANY(p_parking_2w))
      AND (array_length(p_amenities,1) IS NULL OR (SELECT bool_and(p.amenities ? elem) FROM unnest(p_amenities) AS elem))
      AND (p_has_video_walkthrough IS NULL OR (p_has_video_walkthrough=true AND p.youtube_walkthrough_url IS NOT NULL) OR (p_has_video_walkthrough=false AND p.youtube_walkthrough_url IS NULL))
      AND (p_listing_type <> 'rent' OR p_zero_rent_brokerage IS DISTINCT FROM TRUE OR p.rent_brokerage_type = 'none')
      AND (p_listing_type <> 'rent' OR p_max_rent_brokerage_fixed IS NULL OR (p.rent_brokerage_fixed_amount IS NOT NULL AND p.rent_brokerage_fixed_amount <= p_max_rent_brokerage_fixed))
      AND (p_listing_type <> 'sale' OR p_max_sale_brokerage_pct IS NULL OR (p.sale_brokerage_pct IS NOT NULL AND p.sale_brokerage_pct <= p_max_sale_brokerage_pct))
      AND (p_listing_type <> 'sale' OR p_rera_disclosed IS DISTINCT FROM TRUE OR NULLIF(btrim(p.rera_registration_number), '') IS NOT NULL)
      AND (p_listing_type <> 'sale' OR array_length(p_khata_type,1) IS NULL OR p.khata_type = ANY(p_khata_type))
      AND (p_listing_type <> 'sale' OR p_property_tax_paid IS DISTINCT FROM TRUE OR p.property_tax_paid_upto IS NOT NULL)
  ),
  filtered AS (
    SELECT base.*, COUNT(*) OVER()::bigint AS total_count
    FROM base
    WHERE (p_min_price IS NULL OR base.resolved_price_amount>=p_min_price)
      AND (p_max_price IS NULL OR base.resolved_price_amount<=p_max_price)
      AND (p_min_response_rate IS NULL OR base.response_rate_pct>=p_min_response_rate)
      AND (p_has_experience_feedback IS NULL OR (p_has_experience_feedback=true AND base.experience_feedback IS NOT NULL) OR (p_has_experience_feedback=false AND base.experience_feedback IS NULL))
  )
  SELECT
    filtered.property_id, filtered.listing_type, filtered.property_type, filtered.bhk, filtered.owner_id,
    filtered.primary_image_url, filtered.photo_count, filtered.resolved_price_kind, filtered.resolved_price_amount,
    filtered.building_name, filtered.locality, filtered.city, filtered.resolved_location_mode,
    filtered.latitude, filtered.longitude, filtered.carpet_area_sqft, filtered.super_built_up_sqft,
    filtered.furnishing, filtered.bathrooms, filtered.floor_number, filtered.total_floors,
    filtered.parking_4w, filtered.parking_2w, filtered.parking_4w_count, filtered.parking_2w_count,
    filtered.building_age_years, filtered.possession_status, filtered.possession_date,
    filtered.lister_role, filtered.response_handled_count, filtered.response_rate_pct,
    filtered.experience_feedback, filtered.listed_at, filtered.availability_confirmed_at,
    filtered.rent_brokerage_type, filtered.rent_brokerage_fixed_amount, filtered.rent_brokerage_months,
    filtered.sale_brokerage_pct, filtered.security_deposit_amount, filtered.lock_in_months,
    filtered.notice_period_days, filtered.pet_policy, filtered.youtube_walkthrough_url, filtered.price_negotiable,
    filtered.total_count
  FROM filtered
  WHERE p_cursor_id IS NULL
    OR (p_sort='newest' AND (
        (p_cursor_listed_at IS NOT NULL AND (filtered.listed_at<p_cursor_listed_at OR (filtered.listed_at=p_cursor_listed_at AND filtered.property_id<p_cursor_id) OR filtered.listed_at IS NULL))
        OR (p_cursor_listed_at IS NULL AND filtered.listed_at IS NULL AND filtered.property_id<p_cursor_id)))
    OR (p_sort='availability_confirmed' AND (
        (p_cursor_availability_confirmed_at IS NOT NULL AND (filtered.availability_confirmed_at<p_cursor_availability_confirmed_at OR (filtered.availability_confirmed_at=p_cursor_availability_confirmed_at AND (filtered.listed_at<p_cursor_listed_at OR (filtered.listed_at=p_cursor_listed_at AND filtered.property_id<p_cursor_id) OR filtered.listed_at IS NULL)) OR filtered.availability_confirmed_at IS NULL))
        OR (p_cursor_availability_confirmed_at IS NULL AND filtered.availability_confirmed_at IS NULL AND (filtered.listed_at<p_cursor_listed_at OR (filtered.listed_at=p_cursor_listed_at AND filtered.property_id<p_cursor_id) OR filtered.listed_at IS NULL))))
    OR (p_sort='price_asc' AND (
        (p_cursor_price_amount IS NOT NULL AND (filtered.resolved_price_amount>p_cursor_price_amount OR (filtered.resolved_price_amount=p_cursor_price_amount AND (filtered.listed_at<p_cursor_listed_at OR (filtered.listed_at=p_cursor_listed_at AND filtered.property_id<p_cursor_id) OR filtered.listed_at IS NULL)) OR filtered.resolved_price_amount IS NULL))
        OR (p_cursor_price_amount IS NULL AND filtered.resolved_price_amount IS NULL AND (filtered.listed_at<p_cursor_listed_at OR (filtered.listed_at=p_cursor_listed_at AND filtered.property_id<p_cursor_id)))))
    OR (p_sort='price_desc' AND (
        (p_cursor_price_amount IS NOT NULL AND (filtered.resolved_price_amount<p_cursor_price_amount OR (filtered.resolved_price_amount=p_cursor_price_amount AND (filtered.listed_at<p_cursor_listed_at OR (filtered.listed_at=p_cursor_listed_at AND filtered.property_id<p_cursor_id) OR filtered.listed_at IS NULL)) OR filtered.resolved_price_amount IS NULL))
        OR (p_cursor_price_amount IS NULL AND filtered.resolved_price_amount IS NULL AND (filtered.listed_at<p_cursor_listed_at OR (filtered.listed_at=p_cursor_listed_at AND filtered.property_id<p_cursor_id)))))
  ORDER BY
    CASE WHEN p_sort='availability_confirmed' THEN filtered.availability_confirmed_at END DESC NULLS LAST,
    CASE WHEN p_sort='price_asc' THEN filtered.resolved_price_amount END ASC NULLS LAST,
    CASE WHEN p_sort='price_desc' THEN filtered.resolved_price_amount END DESC NULLS LAST,
    filtered.listed_at DESC NULLS LAST,
    filtered.property_id DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."search_compact_properties_v3"("p_listing_type" "public"."property_listing_type", "p_property_type" "text", "p_bhk" "text"[], "p_furnishing" "text"[], "p_min_price" numeric, "p_max_price" numeric, "p_available_by" "date", "p_listed_within_days" integer, "p_availability_confirmed_within_days" integer, "p_max_deposit" numeric, "p_max_lock_in_months" integer, "p_max_notice_days" integer, "p_max_annual_increase" numeric, "p_max_move_in_charges" numeric, "p_pet_policy" "text"[], "p_possession_status" "text"[], "p_possession_before" "date", "p_negotiable" boolean, "p_min_carpet_area" numeric, "p_max_carpet_area" numeric, "p_min_super_built_up" numeric, "p_max_super_built_up" numeric, "p_parking_4w" "text"[], "p_parking_2w" "text"[], "p_amenities" "text"[], "p_has_video_walkthrough" boolean, "p_min_response_rate" numeric, "p_has_experience_feedback" boolean, "p_sort" "text", "p_cursor_listed_at" timestamp with time zone, "p_cursor_id" "uuid", "p_cursor_availability_confirmed_at" timestamp with time zone, "p_cursor_price_amount" numeric, "p_limit" integer, "p_zero_rent_brokerage" boolean, "p_max_rent_brokerage_fixed" numeric, "p_max_sale_brokerage_pct" numeric, "p_rera_disclosed" boolean, "p_khata_type" "text"[], "p_property_tax_paid" boolean, "p_geo_place_ids" "uuid"[], "p_distance_km" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_contact_request_event_timestamps"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'declined'       AND OLD.status <> 'declined'       THEN
    NEW.declined_at       := now();
  END IF;
  IF NEW.status = 'approved'       AND OLD.status <> 'approved'       THEN
    NEW.approved_at       := now();
  END IF;
  IF NEW.status = 'withdrawn'      AND OLD.status <> 'withdrawn'      THEN
    NEW.withdrawn_at      := now();
  END IF;
  IF NEW.status = 'auto_cancelled' AND OLD.status <> 'auto_cancelled' THEN
    NEW.auto_cancelled_at := now();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_contact_request_event_timestamps"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_contact_request_event_timestamps"() IS 'BEFORE UPDATE on contact_requests. Sets the appropriate event timestamp column when status transitions. Timestamps are set once and never overwritten (guarded by OLD.status check).';



CREATE OR REPLACE FUNCTION "public"."set_contact_requests_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_contact_requests_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_primary_property_photo"("p_image_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := (SELECT auth.uid());
  v_prop_id uuid; v_owner uuid; v_status property_status; v_is_admin boolean := public.is_admin();
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT pi.property_id, p.owner_id, p.status INTO v_prop_id, v_owner, v_status
    FROM public.property_images pi JOIN public.properties p ON p.id = pi.property_id
    WHERE pi.id = p_image_id FOR UPDATE OF p;
  IF v_prop_id IS NULL THEN RAISE EXCEPTION 'Image not found'; END IF;
  IF v_owner <> v_caller AND NOT v_is_admin THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF NOT v_is_admin AND v_status NOT IN ('listed','edit_pending_review') THEN
    RAISE EXCEPTION 'Cover changes are not allowed in % status', v_status;
  END IF;
  PERFORM set_config('reeve.system_action', 'photo_op', true);
  UPDATE public.property_images SET is_primary = false WHERE property_id = v_prop_id AND is_primary AND id <> p_image_id;
  UPDATE public.property_images SET is_primary = true WHERE id = p_image_id;
END;
$$;


ALTER FUNCTION "public"."set_primary_property_photo"("p_image_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_property_geo_associations"("p_property_id" "uuid", "p_actor_user_id" "uuid", "p_actor_type" "text", "p_associations" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_owner uuid; v_status text; v_lat double precision; v_lng double precision;
  v_elem jsonb; v_gp public.geo_places%ROWTYPE;
BEGIN
  IF p_actor_type NOT IN ('owner','admin') THEN RAISE EXCEPTION 'invalid actor_type %', p_actor_type; END IF;

  SELECT owner_id, status::text, latitude, longitude
    INTO v_owner, v_status, v_lat, v_lng
    FROM public.properties WHERE id = p_property_id FOR UPDATE;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'property not found'; END IF;

  IF p_actor_type = 'owner' THEN
    IF p_actor_user_id IS DISTINCT FROM v_owner THEN RAISE EXCEPTION 'actor does not own property'; END IF;
    IF v_status NOT IN ('draft','changes_requested') THEN
      RAISE EXCEPTION 'owner location edits are not allowed in status %', v_status;
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_actor_user_id AND role::text IN ('admin','super_admin')) THEN
      RAISE EXCEPTION 'actor is not an admin';
    END IF;
  END IF;

  PERFORM set_config('reeve.system_action', 'geo_assoc', true);

  DELETE FROM public.property_geo_associations WHERE property_id = p_property_id;

  IF p_associations IS NOT NULL AND jsonb_typeof(p_associations) = 'array' THEN
    FOR v_elem IN SELECT * FROM jsonb_array_elements(p_associations) LOOP
      SELECT * INTO v_gp FROM public.geo_places WHERE id = (v_elem->>'geo_place_id')::uuid;
      IF v_gp.id IS NULL THEN
        RAISE EXCEPTION 'geo_place % not found (no minting here)', v_elem->>'geo_place_id';
      END IF;

      IF (v_elem->>'source') = 'owner' AND (v_elem->>'relationship') = 'area_road' THEN
        IF NOT public.reeve_geo_is_plausible(
             v_lat, v_lng, v_gp.center_lat, v_gp.center_lng,
             v_gp.bbox_ne_lat, v_gp.bbox_ne_lng, v_gp.bbox_sw_lat, v_gp.bbox_sw_lng, v_gp.kind) THEN
          RAISE EXCEPTION 'owner-added % "%" is not geographically plausible for this property',
            v_gp.kind, v_gp.display_name;
        END IF;
      END IF;

      INSERT INTO public.property_geo_associations
        (property_id, geo_place_id, relationship, source, confidence)
      VALUES (
        p_property_id, v_gp.id, v_elem->>'relationship', v_elem->>'source',
        NULLIF(v_elem->>'confidence','')
      );
    END LOOP;
  END IF;
END;
$$;


ALTER FUNCTION "public"."set_property_geo_associations"("p_property_id" "uuid", "p_actor_user_id" "uuid", "p_actor_type" "text", "p_associations" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_property_edit_request"("p_property_id" "uuid", "p_field_changes" "jsonb", "p_photo_changes" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := (SELECT auth.uid());
  p_row public.properties%ROWTYPE;
  v_clean jsonb := '{}'::jsonb;
  v_base jsonb := '{}'::jsonb;
  v_photo_add jsonb := '[]'::jsonb;
  v_new_edit_request_id uuid;
  v_existing_pending_id uuid;
  v_key text; v_txt text; v_am_add jsonb; v_fd_add jsonb; v_elem jsonb;
  v_existing_amenities text[];
  ALLOWED_KEYS constant text[] := ARRAY['building_notes','building_rules','parking_notes','rera_registration_number','youtube_walkthrough_url','bhk','property_type','amenities','furnishing_detail'];
  TEXT_KEYS constant text[] := ARRAY['building_notes','building_rules','parking_notes','rera_registration_number','youtube_walkthrough_url'];
  PROPERTY_TYPES constant text[] := ARRAY['apartment','villa','independent_house','duplex_apartment','plot'];
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT * INTO p_row FROM public.properties WHERE id = p_property_id FOR UPDATE;
  IF p_row.id IS NULL THEN RAISE EXCEPTION 'Property not found'; END IF;
  IF p_row.owner_id <> v_caller AND NOT public.is_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF p_row.status NOT IN ('listed','edit_pending_review') THEN
    RAISE EXCEPTION 'Cannot submit edit request for property in status %', p_row.status;
  END IF;

  IF p_field_changes IS NOT NULL THEN
    FOR v_key IN SELECT jsonb_object_keys(p_field_changes) LOOP
      IF NOT (v_key = ANY (ALLOWED_KEYS)) THEN RAISE EXCEPTION 'Field % is not reviewable', v_key; END IF;
    END LOOP;
  END IF;

  FOREACH v_key IN ARRAY TEXT_KEYS LOOP
    IF p_field_changes ? v_key THEN
      v_txt := btrim(COALESCE(p_field_changes->>v_key, ''));
      IF v_txt <> '' AND v_txt IS DISTINCT FROM (
        SELECT btrim(COALESCE(CASE v_key
          WHEN 'building_notes' THEN p_row.building_notes
          WHEN 'building_rules' THEN p_row.building_rules
          WHEN 'parking_notes' THEN p_row.parking_notes
          WHEN 'rera_registration_number' THEN p_row.rera_registration_number
          WHEN 'youtube_walkthrough_url' THEN p_row.youtube_walkthrough_url END, ''))) THEN
        v_clean := v_clean || jsonb_build_object(v_key, v_txt);
        v_base := v_base || jsonb_build_object(v_key, CASE v_key
          WHEN 'building_notes' THEN to_jsonb(p_row.building_notes)
          WHEN 'building_rules' THEN to_jsonb(p_row.building_rules)
          WHEN 'parking_notes' THEN to_jsonb(p_row.parking_notes)
          WHEN 'rera_registration_number' THEN to_jsonb(p_row.rera_registration_number)
          WHEN 'youtube_walkthrough_url' THEN to_jsonb(p_row.youtube_walkthrough_url) END);
      END IF;
    END IF;
  END LOOP;

  IF p_field_changes ? 'bhk' THEN
    v_txt := p_field_changes->>'bhk';
    BEGIN PERFORM v_txt::bhk_type; EXCEPTION WHEN others THEN RAISE EXCEPTION 'Invalid bhk value: %', v_txt; END;
    IF v_txt IS DISTINCT FROM p_row.bhk::text THEN
      v_clean := v_clean || jsonb_build_object('bhk', v_txt);
      v_base := v_base || jsonb_build_object('bhk', to_jsonb(p_row.bhk::text));
    END IF;
  END IF;

  IF p_field_changes ? 'property_type' THEN
    v_txt := p_field_changes->>'property_type';
    IF NOT (v_txt = ANY (PROPERTY_TYPES)) THEN RAISE EXCEPTION 'Invalid property_type value: %', v_txt; END IF;
    IF v_txt IS DISTINCT FROM p_row.property_type THEN
      v_clean := v_clean || jsonb_build_object('property_type', v_txt);
      v_base := v_base || jsonb_build_object('property_type', to_jsonb(p_row.property_type));
    END IF;
  END IF;

  IF p_field_changes ? 'amenities' THEN
    SELECT COALESCE(array_agg(lower(btrim(b))), '{}'::text[]) INTO v_existing_amenities
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(p_row.amenities->'building')='array' THEN p_row.amenities->'building' ELSE '[]'::jsonb END) b;
    SELECT COALESCE(jsonb_agg(DISTINCT lower(btrim(val))), '[]'::jsonb) INTO v_am_add
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(p_field_changes->'amenities'->'building')='array' THEN p_field_changes->'amenities'->'building' ELSE '[]'::jsonb END) AS val
    WHERE lower(btrim(val)) = ANY (public.reeve_custom_building_amenities(p_field_changes->'amenities'))
      AND NOT (lower(btrim(val)) = ANY (v_existing_amenities));
    IF jsonb_array_length(v_am_add) > 0 THEN v_clean := v_clean || jsonb_build_object('amenities_building_add', v_am_add); END IF;
  END IF;

  IF p_field_changes ? 'furnishing_detail' THEN
    SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb) INTO v_fd_add
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_field_changes->'furnishing_detail')='array' THEN p_field_changes->'furnishing_detail' ELSE '[]'::jsonb END) AS elem
    WHERE lower(btrim(elem->>'item')) = ANY (public.reeve_custom_furnishing_names(p_field_changes->'furnishing_detail'))
      AND lower(btrim(elem->>'item')) <> ALL (public.reeve_custom_furnishing_names(p_row.furnishing_detail));
    IF jsonb_array_length(v_fd_add) > 0 THEN v_clean := v_clean || jsonb_build_object('furnishing_detail_add', v_fd_add); END IF;
  END IF;

  IF p_photo_changes ? 'delete' OR p_photo_changes ? 'update' THEN
    RAISE EXCEPTION 'Photo delete/update are instant operations, not review changes';
  END IF;
  IF p_photo_changes ? 'add' AND jsonb_typeof(p_photo_changes->'add')='array' THEN
    FOR v_elem IN SELECT * FROM jsonb_array_elements(p_photo_changes->'add') LOOP
      IF NOT ((v_elem->>'url') LIKE 'https://images.reeve.in/%' AND position(p_property_id::text IN COALESCE(v_elem->>'url','')) > 0) THEN
        RAISE EXCEPTION 'Staged photo URL is not under this property''s storage path';
      END IF;
    END LOOP;
    v_photo_add := p_photo_changes->'add';
  END IF;

  IF v_clean = '{}'::jsonb AND jsonb_array_length(v_photo_add) = 0 THEN RAISE EXCEPTION 'No reviewable changes'; END IF;

  SELECT id INTO v_existing_pending_id FROM public.property_edit_requests WHERE property_id = p_property_id AND status = 'pending' FOR UPDATE;
  IF v_existing_pending_id IS NOT NULL THEN
    UPDATE public.property_edit_requests SET status = 'superseded' WHERE id = v_existing_pending_id;
  END IF;

  INSERT INTO public.property_edit_requests (property_id, owner_id, status, payload)
  VALUES (p_property_id, p_row.owner_id, 'pending',
    jsonb_build_object('field_changes', v_clean, 'base_values', v_base, 'photo_changes', jsonb_build_object('add', v_photo_add)))
  RETURNING id INTO v_new_edit_request_id;

  IF p_row.status = 'listed' THEN
    UPDATE public.properties SET status = 'edit_pending_review' WHERE id = p_property_id;
  END IF;
  RETURN v_new_edit_request_id;
END;
$$;


ALTER FUNCTION "public"."submit_property_edit_request"("p_property_id" "uuid", "p_field_changes" "jsonb", "p_photo_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_rating"("p_contact_request_id" "uuid", "p_q1" "text", "p_q2" "text", "p_q3" "text", "p_review_text" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_caller_id      uuid := auth.uid();
  v_rating         public.interaction_ratings;
  v_is_owner       boolean;
  v_is_tenant      boolean;
  v_days_remaining numeric;
  v_other_submitted boolean;
  v_count          integer;
BEGIN
  -- Auth
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  -- Fetch rating row
  SELECT * INTO v_rating
  FROM public.interaction_ratings
  WHERE contact_request_id = p_contact_request_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RATING_NOT_FOUND';
  END IF;

  -- Participant check
  v_is_owner  := (v_rating.owner_id  = v_caller_id);
  v_is_tenant := (v_rating.tenant_id = v_caller_id);

  IF NOT (v_is_owner OR v_is_tenant) THEN
    RAISE EXCEPTION 'UNAUTHORIZED';
  END IF;

  -- Window open check
  IF now() < v_rating.window_opens_at THEN
    v_days_remaining := EXTRACT(EPOCH FROM (v_rating.window_opens_at - now())) / 86400;
    RAISE EXCEPTION 'WINDOW_NOT_OPEN:%.1f', v_days_remaining;
  END IF;

  -- Window closed check
  IF now() > v_rating.window_closes_at THEN
    RAISE EXCEPTION 'WINDOW_CLOSED';
  END IF;

  -- Already submitted check
  IF v_is_owner AND v_rating.o_submitted_at IS NOT NULL THEN
    RAISE EXCEPTION 'ALREADY_SUBMITTED';
  END IF;
  IF v_is_tenant AND v_rating.t_submitted_at IS NOT NULL THEN
    RAISE EXCEPTION 'ALREADY_SUBMITTED';
  END IF;

  -- Q3 mandatory
  IF p_q3 IS NULL OR trim(p_q3) = '' THEN
    RAISE EXCEPTION 'Q3_REQUIRED';
  END IF;

  -- Validate answer values
  IF p_q1 IS NOT NULL AND p_q1 NOT IN ('yes','partially','no') THEN
    RAISE EXCEPTION 'INVALID_Q1';
  END IF;
  IF p_q2 IS NOT NULL AND p_q2 NOT IN ('yes','rescheduled','didnt_happen','not_reached') THEN
    RAISE EXCEPTION 'INVALID_Q2';
  END IF;
  IF p_q3 NOT IN ('yes','maybe','no') THEN
    RAISE EXCEPTION 'INVALID_Q3';
  END IF;

  -- Review text filter suite (same rules as post_comment)
  IF p_review_text IS NOT NULL AND trim(p_review_text) != '' THEN

    -- English only
    IF p_review_text ~ '[^\x00-\x7F]' THEN
      IF EXISTS (
        SELECT 1 FROM regexp_split_to_table(p_review_text, '') AS ch
        WHERE ascii(ch) > 591
          AND ascii(ch) != 8377
          AND ascii(ch) NOT BETWEEN 8208 AND 8213
          AND ascii(ch) NOT BETWEEN 8216 AND 8223
      ) THEN
        RAISE EXCEPTION 'NON_ENGLISH';
      END IF;
    END IF;

    -- No emojis
    IF EXISTS (
      SELECT 1 FROM regexp_split_to_table(p_review_text, '') AS ch
      WHERE ascii(ch) BETWEEN 9728 AND 10175
        OR ascii(ch) BETWEEN 127744 AND 131071
        OR ascii(ch) BETWEEN 126976 AND 127743
        OR ascii(ch) BETWEEN 9000 AND 9999
    ) THEN
      RAISE EXCEPTION 'CONTAINS_EMOJI';
    END IF;

    -- No URLs
    IF p_review_text ~* 'https?://' OR p_review_text ~* 'www\.'
       OR p_review_text ~* '[a-z0-9-]+\.[a-z]{2,4}(\s|$|/)' THEN
      RAISE EXCEPTION 'CONTAINS_URL';
    END IF;

    -- No emails
    IF p_review_text ~* '[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}' THEN
      RAISE EXCEPTION 'CONTAINS_EMAIL';
    END IF;

    -- No phone numbers
    IF p_review_text ~ '(\+91|91)?[6-9][0-9]{9}' THEN
      RAISE EXCEPTION 'CONTAINS_PHONE';
    END IF;

    -- Blocklist
    IF EXISTS (
      SELECT 1
      FROM regexp_split_to_table(lower(p_review_text), '[^a-z]+') AS token
      JOIN public.comment_blocklist bl ON bl.word = token
      WHERE token != ''
    ) THEN
      RAISE EXCEPTION 'BLOCKED_WORD';
    END IF;

    -- Pattern spam
    IF p_review_text ~ '[A-Z]{21,}' OR p_review_text ~ '(.)\1{4,}' THEN
      RAISE EXCEPTION 'PATTERN_SPAM';
    END IF;
  END IF;

  -- UPDATE the appropriate side
  IF v_is_owner THEN
    UPDATE public.interaction_ratings SET
      o_q1_communication = p_q1,
      o_q2_visit         = p_q2,
      o_q3_deal_again    = p_q3,
      o_review_text      = NULLIF(trim(COALESCE(p_review_text, '')), ''),
      o_submitted_at     = now()
    WHERE contact_request_id = p_contact_request_id;
    v_other_submitted := (v_rating.t_submitted_at IS NOT NULL);
  ELSE
    UPDATE public.interaction_ratings SET
      t_q1_communication = p_q1,
      t_q2_visit         = p_q2,
      t_q3_deal_again    = p_q3,
      t_review_text      = NULLIF(trim(COALESCE(p_review_text, '')), ''),
      t_submitted_at     = now()
    WHERE contact_request_id = p_contact_request_id;
    v_other_submitted := (v_rating.o_submitted_at IS NOT NULL);
  END IF;

  RETURN jsonb_build_object(
    'success',         true,
    'other_submitted', v_other_submitted
  );
END;
$_$;


ALTER FUNCTION "public"."submit_rating"("p_contact_request_id" "uuid", "p_q1" "text", "p_q2" "text", "p_q3" "text", "p_review_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_rating_v2"("p_contact_request_id" "uuid", "p_reach" "text", "p_accuracy" "text", "p_progress" "text", "p_respect" "text", "p_trust" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller     uuid := auth.uid();
  v_rating     public.interaction_ratings;
  v_is_owner   boolean;
  v_is_tenant  boolean;
  v_approved   boolean;
  v_count      integer;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  SELECT * INTO v_rating FROM public.interaction_ratings WHERE contact_request_id = p_contact_request_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RATING_NOT_FOUND';
  END IF;

  v_is_owner  := (v_rating.owner_id  = v_caller);
  v_is_tenant := (v_rating.tenant_id = v_caller);
  IF NOT (v_is_owner OR v_is_tenant) THEN
    RAISE EXCEPTION 'UNAUTHORIZED';
  END IF;

  SELECT (approved_at IS NOT NULL) INTO v_approved FROM public.contact_requests WHERE id = p_contact_request_id;
  IF NOT COALESCE(v_approved, false) THEN
    RAISE EXCEPTION 'NOT_APPROVED';
  END IF;

  -- All five mandatory
  IF p_reach IS NULL OR p_accuracy IS NULL OR p_progress IS NULL OR p_respect IS NULL OR p_trust IS NULL THEN
    RAISE EXCEPTION 'MISSING_ANSWER';
  END IF;
  -- Enum validation
  IF p_reach    NOT IN ('easily','difficult','no_response')            THEN RAISE EXCEPTION 'INVALID_ANSWER'; END IF;
  IF p_accuracy NOT IN ('matched','minor','major')                     THEN RAISE EXCEPTION 'INVALID_ANSWER'; END IF;
  IF p_progress NOT IN ('next_step','discussed','no_progress','mutual_stop') THEN RAISE EXCEPTION 'INVALID_ANSWER'; END IF;
  IF p_respect  NOT IN ('yes','mostly','no')                           THEN RAISE EXCEPTION 'INVALID_ANSWER'; END IF;
  IF p_trust    NOT IN ('yes','maybe','no')                            THEN RAISE EXCEPTION 'INVALID_ANSWER'; END IF;

  IF v_is_owner THEN
    UPDATE public.interaction_ratings ir SET
      o_reach = p_reach, o_accuracy = p_accuracy, o_progress = p_progress,
      o_respect = p_respect, o_trust = p_trust, o_v2_submitted_at = now()
    WHERE ir.contact_request_id = p_contact_request_id
      AND ir.o_v2_submitted_at IS NULL
      AND EXISTS (SELECT 1 FROM public.contact_requests cr WHERE cr.id = ir.contact_request_id AND cr.approved_at IS NOT NULL);
  ELSE
    UPDATE public.interaction_ratings ir SET
      t_reach = p_reach, t_accuracy = p_accuracy, t_progress = p_progress,
      t_respect = p_respect, t_trust = p_trust, t_v2_submitted_at = now()
    WHERE ir.contact_request_id = p_contact_request_id
      AND ir.t_v2_submitted_at IS NULL
      AND EXISTS (SELECT 1 FROM public.contact_requests cr WHERE cr.id = ir.contact_request_id AND cr.approved_at IS NOT NULL);
  END IF;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count = 0 THEN
    RAISE EXCEPTION 'ALREADY_SUBMITTED';
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."submit_rating_v2"("p_contact_request_id" "uuid", "p_reach" "text", "p_accuracy" "text", "p_progress" "text", "p_respect" "text", "p_trust" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_verified_phone_from_auth"("p_user_id" "uuid", "p_expected_phone" "text") RETURNS TABLE("synced" boolean, "expected_phone_matches" boolean, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_auth           record;
  v_auth_norm      text;
  v_expected_norm  text;
  v_matches        boolean;
  v_rows           integer;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'user_id_required';
  END IF;

  SELECT u.id, u.phone, u.phone_confirmed_at
  INTO   v_auth
  FROM   auth.users u
  WHERE  u.id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'auth_user_not_found';
  END IF;

  IF v_auth.phone IS NULL OR pg_catalog.btrim(v_auth.phone) = '' THEN
    RAISE EXCEPTION 'auth_phone_missing';
  END IF;

  IF v_auth.phone_confirmed_at IS NULL THEN
    RAISE EXCEPTION 'auth_phone_unconfirmed';
  END IF;

  v_auth_norm     := pg_catalog.regexp_replace(v_auth.phone, '\D', '', 'g');
  v_expected_norm := pg_catalog.regexp_replace(COALESCE(p_expected_phone, ''), '\D', '', 'g');
  v_matches       := (v_auth_norm = v_expected_norm);

  UPDATE public.users
  SET    phone          = v_auth.phone,
         phone_verified = true,
         updated_at     = pg_catalog.now()
  WHERE  id = p_user_id;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'public_user_row_missing';
  END IF;

  RETURN QUERY SELECT
    true,
    v_matches,
    CASE WHEN v_matches THEN 'synced' ELSE 'concurrent_phone_change' END;
END;
$$;


ALTER FUNCTION "public"."sync_verified_phone_from_auth"("p_user_id" "uuid", "p_expected_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_comment_like"("p_comment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id   uuid := auth.uid();
  v_phone_ver boolean;
  v_email_ver boolean;
  v_liked     boolean;
  v_new_count integer;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  SELECT phone_verified, email_verified
  INTO v_phone_ver, v_email_ver
  FROM public.users WHERE id = v_user_id;

  IF NOT (v_phone_ver AND v_email_ver) THEN
    RAISE EXCEPTION 'VERIFICATION_INCOMPLETE';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.comment_likes
    WHERE comment_id = p_comment_id AND user_id = v_user_id
  ) THEN
    DELETE FROM public.comment_likes
    WHERE comment_id = p_comment_id AND user_id = v_user_id;
    v_liked := false;
  ELSE
    INSERT INTO public.comment_likes (comment_id, user_id)
    VALUES (p_comment_id, v_user_id);
    v_liked := true;
  END IF;

  SELECT like_count INTO v_new_count
  FROM public.property_comments WHERE id = p_comment_id;

  RETURN jsonb_build_object('liked', v_liked, 'like_count', v_new_count);
END;
$$;


ALTER FUNCTION "public"."toggle_comment_like"("p_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."touch_last_login"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  UPDATE public.users
     SET last_login_at = NOW()
   WHERE id = auth.uid();
END;
$$;


ALTER FUNCTION "public"."touch_last_login"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."track_property_view"("p_property_id" "uuid", "p_visitor_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_owner_id uuid;
BEGIN
  SELECT owner_id INTO v_owner_id
  FROM public.properties WHERE id = p_property_id;

  IF v_user_id IS NOT NULL AND v_user_id = v_owner_id THEN
    RETURN;
  END IF;

  -- 30-second cooldown
  IF EXISTS (
    SELECT 1 FROM public.property_views
    WHERE property_id = p_property_id
      AND (
        (v_user_id IS NOT NULL AND user_id = v_user_id)
        OR
        (v_user_id IS NULL AND visitor_id = p_visitor_id)
      )
      AND created_at > now() - interval '30 seconds'
  ) THEN
    RETURN;
  END IF;

  INSERT INTO public.property_views
    (property_id, user_id, visitor_id, viewed_date)
  VALUES (
    p_property_id,
    v_user_id,
    CASE WHEN v_user_id IS NULL THEN p_visitor_id ELSE NULL END,
    CURRENT_DATE
  )
  ON CONFLICT DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."track_property_view"("p_property_id" "uuid", "p_visitor_id" "text") OWNER TO "postgres";


