CREATE OR REPLACE FUNCTION "public"."trg_fn_auto_hide_on_reports"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  SELECT COUNT(DISTINCT reporter_id) INTO v_count
  FROM public.comment_reports
  WHERE comment_id = NEW.comment_id AND resolution IS NULL;

  IF v_count >= 3 THEN
    UPDATE public.property_comments
    SET is_deleted = true, hidden_reason = 'auto_hidden_reports'
    WHERE id = NEW.comment_id AND is_deleted = false;
  END IF;
  RETURN NULL;
END;
$$;


