CREATE OR REPLACE FUNCTION "public"."trg_fn_create_rating_on_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_opens_at  timestamptz;
  v_closes_at timestamptz;
BEGIN
  IF NEW.status::text = 'approved'
     AND (OLD.status IS NULL OR OLD.status::text != 'approved')
  THEN
    -- approved_at may be null if set asynchronously; fall back to now()
    v_opens_at  := COALESCE(NEW.approved_at, now()) + interval '3 days';
    v_closes_at := v_opens_at + interval '10 days';

    INSERT INTO public.interaction_ratings (
      contact_request_id,
      property_id,
      owner_id,
      tenant_id,
      window_opens_at,
      window_closes_at
    ) VALUES (
      NEW.id,
      NEW.property_id,
      NEW.owner_id,
      NEW.tenant_id,
      v_opens_at,
      v_closes_at
    )
    ON CONFLICT (contact_request_id) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_fn_create_rating_on_approval"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_fn_update_like_count"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.property_comments
    SET like_count = like_count + 1
    WHERE id = NEW.comment_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.property_comments
    SET like_count = GREATEST(like_count - 1, 0)
    WHERE id = OLD.comment_id;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."trg_fn_update_like_count"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_profile_bio"("p_bio" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_user_id uuid := auth.uid();
  v_bio     text;
BEGIN
  -- 1. Auth
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  -- 2. Normalize: strip leading/trailing whitespace -> NULL if empty
  v_bio := nullif(
    regexp_replace(p_bio, '^[[:space:]]+|[[:space:]]+$', '', 'g'),
    ''
  );

  -- 3-4. Delegate all validation to validate_short_text (length + content checks).
  --      Re-raise TEXT_TOO_LONG as BIO_TOO_LONG to preserve the existing RPC contract.
  BEGIN
    PERFORM public.validate_short_text(v_bio, 200);
  EXCEPTION
    WHEN OTHERS THEN
      IF SQLERRM = 'TEXT_TOO_LONG' THEN
        RAISE EXCEPTION 'BIO_TOO_LONG';
      END IF;
      RAISE;
  END;

  -- 5. Upsert — only bio column, all others preserved
  INSERT INTO public.profiles (user_id, bio)
  VALUES (v_user_id, v_bio)
  ON CONFLICT ON CONSTRAINT uq_profiles_user
  DO UPDATE SET bio = EXCLUDED.bio;

  RETURN v_bio;
END;
$_$;


ALTER FUNCTION "public"."update_profile_bio"("p_bio" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_property_building_name"("p_property_id" "uuid", "p_actor_user_id" "uuid", "p_actor_type" "text", "p_building_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_owner uuid; v_status text; v_ptype text; v_mode text; v_place text; v_src text;
  v_trimmed text; v_optional boolean; v_geom_present boolean; v_confirmed timestamptz;
BEGIN
  IF p_actor_type NOT IN ('owner','admin') THEN RAISE EXCEPTION 'invalid actor_type %', p_actor_type; END IF;
  SELECT owner_id, status::text, property_type, address_mode, place_id, building_name_source,
         (geom_exact IS NOT NULL), location_confirmed_at
    INTO v_owner, v_status, v_ptype, v_mode, v_place, v_src, v_geom_present, v_confirmed
    FROM public.properties WHERE id = p_property_id FOR UPDATE;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'property not found'; END IF;

  IF p_actor_type = 'owner' THEN
    IF p_actor_user_id IS DISTINCT FROM v_owner THEN RAISE EXCEPTION 'actor does not own property'; END IF;
    IF v_status NOT IN ('draft','changes_requested') THEN RAISE EXCEPTION 'owner edits not allowed in %', v_status; END IF;
    IF NOT (v_src IS NULL OR v_src = 'owner') THEN
      RAISE EXCEPTION 'building identity is % — use Search again', v_src;
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_actor_user_id AND role::text IN ('admin','super_admin')) THEN
      RAISE EXCEPTION 'actor is not an admin';
    END IF;
  END IF;

  IF NOT (
    (v_mode = 'google_place' AND NULLIF(btrim(COALESCE(v_place,'')), '') IS NOT NULL)
    OR (v_mode = 'manual' AND v_geom_present AND v_confirmed IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'location not confirmed';
  END IF;

  v_optional := v_ptype IN ('independent_house','villa','plot');
  v_trimmed := NULLIF(btrim(COALESCE(p_building_name,'')), '');
  IF v_trimmed IS NULL AND NOT v_optional THEN
    RAISE EXCEPTION 'building_name_required';
  END IF;

  PERFORM set_config('reeve.system_action', 'building_name', true);
  UPDATE public.properties SET
    building_name = v_trimmed,
    building_name_source = CASE WHEN v_trimmed IS NULL THEN NULL
                                WHEN p_actor_type = 'admin' THEN 'admin' ELSE 'owner' END
  WHERE id = p_property_id;
END;
$$;


