CREATE OR REPLACE FUNCTION "public"."upsert_geo_place"("p_place_id" "text", "p_display_name" "text", "p_kind" "text", "p_center_lat" double precision, "p_center_lng" double precision, "p_bbox_ne_lat" double precision DEFAULT NULL::double precision, "p_bbox_ne_lng" double precision DEFAULT NULL::double precision, "p_bbox_sw_lat" double precision DEFAULT NULL::double precision, "p_bbox_sw_lng" double precision DEFAULT NULL::double precision) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_existing_kind text;
  v_is_final boolean;
  v_ref_place uuid;
BEGIN
  IF p_place_id IS NULL OR btrim(p_place_id) = '' THEN RAISE EXCEPTION 'place_id required'; END IF;
  IF p_kind NOT IN ('city','area','road') THEN RAISE EXCEPTION 'invalid kind %', p_kind; END IF;

  SELECT geo_place_id INTO v_ref_place FROM public.geo_provider_refs
    WHERE provider = 'google' AND provider_place_id = p_place_id;
  IF v_ref_place IS NOT NULL THEN
    v_id := v_ref_place;
  ELSE
    SELECT id INTO v_id FROM public.geo_places WHERE place_id = p_place_id;
  END IF;

  IF v_id IS NOT NULL THEN
    SELECT kind INTO v_existing_kind FROM public.geo_places WHERE id = v_id;
    v_is_final := v_existing_kind IN ('search_region','settlement','locality','road');

    IF v_is_final THEN
      IF NOT (
        (p_kind = 'city' AND v_existing_kind IN ('search_region','settlement')) OR
        (p_kind = 'area' AND v_existing_kind IN ('locality','road')) OR
        (p_kind = 'road' AND v_existing_kind = 'road')
      ) THEN
        RAISE EXCEPTION 'legacy kind % incompatible with canonical final kind % for place_id %',
          p_kind, v_existing_kind, p_place_id;
      END IF;
      UPDATE public.geo_places SET
        display_name = COALESCE(display_name, p_display_name),
        center_lat   = COALESCE(center_lat, p_center_lat),
        center_lng   = COALESCE(center_lng, p_center_lng),
        bbox_ne_lat  = COALESCE(bbox_ne_lat, p_bbox_ne_lat),
        bbox_ne_lng  = COALESCE(bbox_ne_lng, p_bbox_ne_lng),
        bbox_sw_lat  = COALESCE(bbox_sw_lat, p_bbox_sw_lat),
        bbox_sw_lng  = COALESCE(bbox_sw_lng, p_bbox_sw_lng),
        place_id     = COALESCE(place_id, p_place_id)
      WHERE id = v_id;
    ELSE
      IF v_existing_kind <> p_kind THEN
        RAISE EXCEPTION 'geo_place % already exists as kind % — refusing silent reclassify to %',
          p_place_id, v_existing_kind, p_kind;
      END IF;
      UPDATE public.geo_places SET
        display_name = p_display_name,
        center_lat = p_center_lat, center_lng = p_center_lng,
        bbox_ne_lat = p_bbox_ne_lat, bbox_ne_lng = p_bbox_ne_lng,
        bbox_sw_lat = p_bbox_sw_lat, bbox_sw_lng = p_bbox_sw_lng,
        place_id = COALESCE(place_id, p_place_id)
      WHERE id = v_id;
    END IF;
  ELSE
    INSERT INTO public.geo_places (place_id, display_name, kind, center_lat, center_lng,
                                   bbox_ne_lat, bbox_ne_lng, bbox_sw_lat, bbox_sw_lng)
    VALUES (p_place_id, p_display_name, p_kind, p_center_lat, p_center_lng,
            p_bbox_ne_lat, p_bbox_ne_lng, p_bbox_sw_lat, p_bbox_sw_lng)
    RETURNING id INTO v_id;
  END IF;

  DECLARE v_existing_ref uuid;
  BEGIN
    SELECT geo_place_id INTO v_existing_ref FROM public.geo_provider_refs
      WHERE provider = 'google' AND provider_place_id = p_place_id;
    IF v_existing_ref IS NULL THEN
      INSERT INTO public.geo_provider_refs (geo_place_id, provider, provider_place_id, last_verified_at)
        VALUES (v_id, 'google', p_place_id, now());
    ELSIF v_existing_ref <> v_id THEN
      RAISE EXCEPTION 'google place_id % already mapped to a different canonical place', p_place_id;
    ELSE
      UPDATE public.geo_provider_refs SET last_verified_at = now()
        WHERE provider = 'google' AND provider_place_id = p_place_id;
    END IF;
  END;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."upsert_geo_place"("p_place_id" "text", "p_display_name" "text", "p_kind" "text", "p_center_lat" double precision, "p_center_lng" double precision, "p_bbox_ne_lat" double precision, "p_bbox_ne_lng" double precision, "p_bbox_sw_lat" double precision, "p_bbox_sw_lng" double precision) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_geo_place"("p_place_id" "text", "p_display_name" "text", "p_kind" "text", "p_center_lat" double precision, "p_center_lng" double precision, "p_bbox_ne_lat" double precision, "p_bbox_ne_lng" double precision, "p_bbox_sw_lat" double precision, "p_bbox_sw_lng" double precision) IS 'LEGACY compatibility bridge (Edge Function). Provider-ref-first identity; maintains google geo_provider_refs; never demotes/overwrites promoted canonical rows. Not the final resolver.';



CREATE OR REPLACE FUNCTION "public"."validate_property_field_text"("p_field" "text", "p_text" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_max integer;
BEGIN
  v_max := CASE p_field
    WHEN 'parking_notes'  THEN 80
    WHEN 'building_rules' THEN 200
    WHEN 'building_notes' THEN 300
    ELSE NULL
  END;

  IF v_max IS NULL THEN
    RAISE EXCEPTION 'UNKNOWN_FIELD';
  END IF;

  RETURN public.validate_short_text(p_text, v_max);
END;
$$;


ALTER FUNCTION "public"."validate_property_field_text"("p_field" "text", "p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_short_text"("p_text" "text", "p_max_length" integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_text       text;
  v_normalized text;
BEGIN
  -- Guard: sane max_length
  IF p_max_length IS NULL OR p_max_length < 1 THEN
    RAISE EXCEPTION 'INVALID_MAX_LENGTH';
  END IF;

  -- 1. Null/empty is always valid
  v_text := nullif(regexp_replace(p_text, '^[[:space:]]+|[[:space:]]+$', '', 'g'), '');
  IF v_text IS NULL THEN RETURN NULL; END IF;

  -- 2. Length (authoritative; char_length counts Unicode code points)
  IF char_length(v_text) > p_max_length THEN
    RAISE EXCEPTION 'TEXT_TOO_LONG';
  END IF;

  -- 3a. URL: http(s):// or www.
  IF v_text ~* 'https?://' OR v_text ~* 'www\.' THEN
    RAISE EXCEPTION 'CONTAINS_URL';
  END IF;

  -- 3b. Email — MUST run BEFORE bare-domain check so that reach@me.com raises
  --     CONTAINS_EMAIL rather than CONTAINS_URL (me.com matches the TLD list).
  IF v_text ~* '[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}' THEN
    RAISE EXCEPTION 'CONTAINS_EMAIL';
  END IF;

  -- 3c. Domain detection: per-candidate extraction, then check each individually.
  DECLARE
    v_dom_candidate text;
  BEGIN
    FOR v_dom_candidate IN
      SELECT (regexp_matches(
        v_text,
        '(([a-z0-9][a-z0-9\-]*\.)+[a-z]{2,63})([^a-z0-9\-]|$)',
        'gi'
      ))[1]
    LOOP
      IF v_dom_candidate IS NULL THEN CONTINUE; END IF;
      IF v_dom_candidate IN (
           'B.Tech', 'M.Tech',
           'B.Sc',   'M.Sc',
           'B.Com',  'M.Com',
           'B.Ed'
         )
         OR lower(v_dom_candidate) IN ('sq.ft', 'sq.yd') THEN
        CONTINUE;
      END IF;
      RAISE EXCEPTION 'CONTAINS_URL';
    END LOOP;

    -- Defence-in-depth: short social domains
    IF v_text ~* '\m(wa|t|fb|ig|tg|ly|bit|goo)\.(com|me|in|io|gg|ly)([^a-z0-9\-]|$)' THEN
      RAISE EXCEPTION 'CONTAINS_URL';
    END IF;
  END;

  -- 3d. Social handles (@username format, >=2 chars after @).
  IF v_text ~ '@[a-zA-Z0-9._\-]{2,30}' THEN
    RAISE EXCEPTION 'CONTAINS_SOCIAL_HANDLE';
  END IF;

  -- 3e. Phone checks
  DECLARE
    v_stripped text;
    v_phone_candidate text;
  BEGIN
    -- Pattern A: Explicit Indian mobile formats (subscriber starts 6-9)
    IF v_text ~ '\m[6-9][0-9]{9}\M'
       OR v_text ~ '\m[6-9][0-9]{4}[[:space:]][0-9]{5}\M'
       OR v_text ~ '\m[6-9][0-9]{4}[-][0-9]{5}\M'
       OR v_text ~ '\m[6-9][0-9]{4}[.][0-9]{5}\M'
       OR v_text ~ '\m[6-9][0-9]{3}[[:space:]][0-9]{6}\M'
       OR v_text ~ '\m[6-9][0-9]{3}[-][0-9]{6}\M'
       OR v_text ~ '\m[6-9][0-9]{2}[-][0-9]{3}[-][0-9]{4}\M'
       OR v_text ~ '\m[6-9][0-9]{2}[.][0-9]{3}[.][0-9]{4}\M'
       OR v_text ~ '\m[6-9][0-9]{2}[[:space:]][0-9]{3}[[:space:]][0-9]{4}\M'
       OR v_text ~ '(^|[^0-9])(\+91|91)[[:space:]\-]?[6-9][0-9]{9}([^0-9]|$)'
       OR v_text ~ '(^|[^0-9])(\+91|91)[[:space:]\-]?[6-9][0-9]{4}[[:space:]][0-9]{5}([^0-9]|$)'
       OR v_text ~ '(^|[^0-9])(\+91|91)[[:space:]\-]?[6-9][0-9]{4}[-][0-9]{5}([^0-9]|$)'
       OR v_text ~ '(^|[^0-9])(\+91|91)[[:space:]\-]?[6-9][0-9]{4}[.][0-9]{5}([^0-9]|$)'
       OR v_text ~ '(^|[^0-9])(\+91|91)[[:space:]\-]?[6-9][0-9]{3}[[:space:]][0-9]{6}([^0-9]|$)'
       OR v_text ~ '(^|[^0-9])(\+91|91)[[:space:]\-]?[6-9][0-9]{3}[-][0-9]{6}([^0-9]|$)'
       OR v_text ~ '(^|[^0-9])(\+91|91)[[:space:]\-]?[6-9][0-9]{2}[-][0-9]{3}[-][0-9]{4}([^0-9]|$)'
       OR v_text ~ '(^|[^0-9])(\+91|91)[[:space:]\-]?[6-9][0-9]{2}[[:space:]][0-9]{3}[[:space:]][0-9]{4}([^0-9]|$)'
       OR v_text ~ '(^|[^0-9])(\+91|91)[[:space:]\-]?[6-9][0-9]{2}[.][0-9]{3}[.][0-9]{4}([^0-9]|$)'
    THEN
      RAISE EXCEPTION 'CONTAINS_PHONE';
    END IF;

    -- Pattern B: any number starting with + (international dialling prefix)
    FOR v_phone_candidate IN
      SELECT (regexp_matches(v_text,
        '(\+[0-9][0-9[:space:]\-(). ]{6,20}[0-9])',
        'g'))[1]
    LOOP
      IF v_phone_candidate IS NULL THEN CONTINUE; END IF;
      v_stripped := regexp_replace(v_phone_candidate, '[^0-9]', '', 'g');
      IF char_length(v_stripped) >= 10 THEN
        RAISE EXCEPTION 'CONTAINS_PHONE';
      END IF;
    END LOOP;

    -- Pattern C: North American formats
    IF v_text ~ '[(][0-9]{3}[)][[:space:]\-]?[0-9]{3}[[:space:]\-][0-9]{4}'
       OR v_text ~ '\m[0-9]{3}[-][0-9]{3}[-][0-9]{4}\M'
       OR v_text ~ '\m[0-9]{3}[[:space:]][0-9]{3}[[:space:]][0-9]{4}\M'
       OR v_text ~ '\m[0-9]{3}[.][0-9]{3}[.][0-9]{4}\M'
       OR v_text ~ '\m[2-9][0-9]{2}[2-9][0-9]{6}\M'
    THEN
      RAISE EXCEPTION 'CONTAINS_PHONE';
    END IF;
  END;

  -- 3f. WhatsApp/Telegram contact solicitation.
  IF v_text ~* '\m(whatsapp|telegram)\M[[:space:]]*(me\M|number\M|no\M|num\M|contact\M|chat\M|call\M|msg\M|message\M|@)'
     OR v_text ~* '\m(contact|reach|call|message|text|msg|ping|find|send)\M[[:space:]]+((me|us)[[:space:]]+)?(on|via|through|at)[[:space:]]+\m(whatsapp|telegram)\M'
     OR v_text ~* '\mmy\M[[:space:]]+\m(whatsapp|telegram)\M[[:space:]]*(is\M|:|=|number\M|id\M|username\M|handle\M)'
     OR v_text ~* '\m(whatsapp|telegram)\M[[:space:]]*(:|=)[[:space:]]*\S'
     OR v_text ~* '\m(whatsapp|telegram)\M[[:space:]]+(username|handle|id|number|no|num)\M' THEN
    RAISE EXCEPTION 'BLOCKED_CONTENT';
  END IF;

  -- 4a. Tier A blocklist (exact word-boundary)
  IF EXISTS (
    SELECT 1 FROM public.comment_blocklist bl
    WHERE bl.tier = 'A' AND lower(v_text) ~ ('\m' || bl.word || '\M')
  ) THEN
    RAISE EXCEPTION 'BLOCKED_WORD';
  END IF;

  -- 4b. Normalization pipeline for Tier B
  v_normalized := v_text;
  v_normalized := regexp_replace(v_normalized, E'[\xe2\x80\x8b\xe2\x80\x8c\xe2\x80\x8d\xef\xbb\xbf]', '', 'g');
  v_normalized := lower(v_normalized);
  v_normalized := translate(v_normalized, '013457@$+', 'oieats ast');
  v_normalized := replace(v_normalized, chr(1072), 'a');
  v_normalized := replace(v_normalized, chr(1077), 'e');
  v_normalized := replace(v_normalized, chr(1086), 'o');
  v_normalized := replace(v_normalized, chr(1088), 'r');
  v_normalized := replace(v_normalized, chr(1089), 'c');
  v_normalized := replace(v_normalized, chr(1091), 'y');
  v_normalized := replace(v_normalized, chr(1093), 'x');
  v_normalized := replace(v_normalized, chr(1110), 'i');
  v_normalized := replace(v_normalized, chr(1068), 'b');
  v_normalized := regexp_replace(v_normalized, '([a-z])\1{2,}', '\1\1', 'g');
  v_normalized := regexp_replace(v_normalized, '(?<=[a-z])[^a-z](?=[a-z])', '', 'g');
  v_normalized := regexp_replace(v_normalized, '(?<=[a-z])[^a-z](?=[a-z])', '', 'g');

  -- 4c. Tier B blocklist
  IF EXISTS (
    SELECT 1 FROM public.comment_blocklist bl
    WHERE bl.tier = 'B'
      AND v_normalized ~ bl.word
      AND NOT EXISTS (
        SELECT 1 FROM public.comment_allowlist al
        WHERE v_normalized ~ al.word AND al.word ~ bl.word
      )
  ) THEN
    RAISE EXCEPTION 'BLOCKED_WORD';
  END IF;

  RETURN v_text;
END;
$_$;


ALTER FUNCTION "public"."validate_short_text"("p_text" "text", "p_max_length" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."callback_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "intent" "text" NOT NULL,
    "name" character varying NOT NULL,
    "phone" character varying,
    "is_international" boolean DEFAULT false NOT NULL,
    "contact_channel" "text" DEFAULT 'phone'::"text" NOT NULL,
    "contact_handle" character varying,
    "timezone" character varying,
    "preferred_date" "date" NOT NULL,
    "preferred_slot" "text" NOT NULL,
    "preferred_datetime_ist" timestamp with time zone,
    "property_id" "uuid",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "admin_notes" "text",
    "called_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "callback_requests_contact_channel_check" CHECK (("contact_channel" = ANY (ARRAY['phone'::"text", 'whatsapp'::"text", 'telegram'::"text", 'botim'::"text"]))),
    CONSTRAINT "callback_requests_intent_check" CHECK (("intent" = ANY (ARRAY['owner'::"text", 'tenant'::"text"]))),
    CONSTRAINT "callback_requests_preferred_slot_check" CHECK (("preferred_slot" = ANY (ARRAY['asap'::"text", '09_10'::"text", '10_11'::"text", '11_12'::"text", '12_13'::"text", '13_14'::"text", '14_15'::"text", '15_16'::"text", '16_17'::"text", '17_18'::"text", '18_19'::"text", '19_20'::"text", '02_03'::"text"]))),
    CONSTRAINT "callback_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'called'::"text", 'completed'::"text", 'missed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "phone_required_when_domestic" CHECK ((("is_international" = true) OR ("phone" IS NOT NULL)))
);


