);


ALTER TABLE "public"."geo_place_aliases" OWNER TO "postgres";


COMMENT ON TABLE "public"."geo_place_aliases" IS 'Alternate/normalized names (e.g. Bangalore->Bengaluru) per canonical geo_place. UNIQUE per (place, normalized_alias) only — same name may legitimately exist for different places. Service-role writes only.';



CREATE TABLE IF NOT EXISTS "public"."geo_places" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "place_id" "text",
    "display_name" "text" NOT NULL,
    "kind" "text" NOT NULL,
    "center_lat" double precision,
    "center_lng" double precision,
    "bbox_ne_lat" double precision,
    "bbox_ne_lng" double precision,
    "bbox_sw_lat" double precision,
    "bbox_sw_lng" double precision,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "normalized_name" "text",
    "settlement_subtype" "text",
    "representative_point" "extensions"."geometry"(Point,4326),
    "anchor_quality" "text",
    "parent_geo_place_id" "uuid",
    "search_region_id" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "geo_places_anchor_quality_check" CHECK ((("anchor_quality" IS NULL) OR ("anchor_quality" = ANY (ARRAY['provider_centroid'::"text", 'verified_point'::"text", 'polygon_available'::"text"])))),
    CONSTRAINT "geo_places_bbox_complete" CHECK (("num_nonnulls"("bbox_ne_lat", "bbox_ne_lng", "bbox_sw_lat", "bbox_sw_lng") = ANY (ARRAY[0, 4]))),
    CONSTRAINT "geo_places_bbox_ordered" CHECK ((("bbox_ne_lat" IS NULL) OR (("bbox_sw_lat" <= "bbox_ne_lat") AND ("bbox_sw_lng" <= "bbox_ne_lng") AND ("bbox_ne_lat" >= ('-90'::integer)::double precision) AND ("bbox_ne_lat" <= (90)::double precision) AND ("bbox_sw_lat" >= ('-90'::integer)::double precision) AND ("bbox_sw_lat" <= (90)::double precision) AND ("bbox_ne_lng" >= ('-180'::integer)::double precision) AND ("bbox_ne_lng" <= (180)::double precision) AND ("bbox_sw_lng" >= ('-180'::integer)::double precision) AND ("bbox_sw_lng" <= (180)::double precision)))),
    CONSTRAINT "geo_places_center_pair" CHECK ((("center_lat" IS NULL) = ("center_lng" IS NULL))),
    CONSTRAINT "geo_places_center_range" CHECK ((("center_lat" >= ('-90'::integer)::double precision) AND ("center_lat" <= (90)::double precision) AND ("center_lng" >= ('-180'::integer)::double precision) AND ("center_lng" <= (180)::double precision))),
    CONSTRAINT "geo_places_display_name_nonblank" CHECK (("btrim"("display_name") <> ''::"text")),
    CONSTRAINT "geo_places_kind_check" CHECK (("kind" = ANY (ARRAY['search_region'::"text", 'settlement'::"text", 'locality'::"text", 'road'::"text", 'city'::"text", 'area'::"text"]))),
    CONSTRAINT "geo_places_no_self_parent" CHECK ((("parent_geo_place_id" IS NULL) OR ("parent_geo_place_id" <> "id"))),
    CONSTRAINT "geo_places_no_self_region" CHECK ((("search_region_id" IS NULL) OR ("search_region_id" <> "id"))),
    CONSTRAINT "geo_places_settlement_subtype_check" CHECK ((("settlement_subtype" IS NULL) OR (("kind" = 'settlement'::"text") AND ("settlement_subtype" = ANY (ARRAY['city'::"text", 'town'::"text", 'village'::"text"])))))
);


ALTER TABLE "public"."geo_places" OWNER TO "postgres";


COMMENT ON TABLE "public"."geo_places" IS 'Canonical Google place entities (city/area/road). Minted only via trusted upsert_geo_place (service role). Never owner-writable.';



COMMENT ON COLUMN "public"."geo_places"."normalized_name" IS 'lower(btrim(display_name)); lookup key. NOT globally unique (same name may exist in different contexts).';



COMMENT ON COLUMN "public"."geo_places"."anchor_quality" IS 'Factual anchor source of representative_point: provider_centroid | verified_point | polygon_available.';



