CREATE TABLE IF NOT EXISTS "public"."interaction_ratings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "contact_request_id" "uuid" NOT NULL,
    "property_id" "uuid" NOT NULL,
    "owner_id" "uuid" NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "window_opens_at" timestamp with time zone NOT NULL,
    "window_closes_at" timestamp with time zone NOT NULL,
    "t_submitted_at" timestamp with time zone,
    "t_q1_communication" "text",
    "t_q2_visit" "text",
    "t_q3_deal_again" "text",
    "t_review_text" "text",
    "o_submitted_at" timestamp with time zone,
    "o_q1_communication" "text",
    "o_q2_visit" "text",
    "o_q3_deal_again" "text",
    "o_review_text" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "o_reach" "text",
    "t_reach" "text",
    "o_accuracy" "text",
    "t_accuracy" "text",
    "o_progress" "text",
    "t_progress" "text",
    "o_respect" "text",
    "t_respect" "text",
    "o_trust" "text",
    "t_trust" "text",
    "o_v2_submitted_at" timestamp with time zone,
    "t_v2_submitted_at" timestamp with time zone,
    CONSTRAINT "interaction_ratings_o_q1_communication_check" CHECK (("o_q1_communication" = ANY (ARRAY['yes'::"text", 'partially'::"text", 'no'::"text"]))),
    CONSTRAINT "interaction_ratings_o_q2_visit_check" CHECK (("o_q2_visit" = ANY (ARRAY['yes'::"text", 'rescheduled'::"text", 'didnt_happen'::"text", 'not_reached'::"text"]))),
    CONSTRAINT "interaction_ratings_o_q3_deal_again_check" CHECK (("o_q3_deal_again" = ANY (ARRAY['yes'::"text", 'maybe'::"text", 'no'::"text"]))),
    CONSTRAINT "interaction_ratings_o_review_text_check" CHECK ((("o_review_text" IS NULL) OR ("char_length"("o_review_text") <= 500))),
    CONSTRAINT "interaction_ratings_t_q1_communication_check" CHECK (("t_q1_communication" = ANY (ARRAY['yes'::"text", 'partially'::"text", 'no'::"text"]))),
    CONSTRAINT "interaction_ratings_t_q2_visit_check" CHECK (("t_q2_visit" = ANY (ARRAY['yes'::"text", 'rescheduled'::"text", 'didnt_happen'::"text", 'not_reached'::"text"]))),
    CONSTRAINT "interaction_ratings_t_q3_deal_again_check" CHECK (("t_q3_deal_again" = ANY (ARRAY['yes'::"text", 'maybe'::"text", 'no'::"text"]))),
    CONSTRAINT "interaction_ratings_t_review_text_check" CHECK ((("t_review_text" IS NULL) OR ("char_length"("t_review_text") <= 500))),
    CONSTRAINT "ir_o_accuracy_chk" CHECK ((("o_accuracy" IS NULL) OR ("o_accuracy" = ANY (ARRAY['matched'::"text", 'minor'::"text", 'major'::"text"])))),
    CONSTRAINT "ir_o_progress_chk" CHECK ((("o_progress" IS NULL) OR ("o_progress" = ANY (ARRAY['next_step'::"text", 'discussed'::"text", 'no_progress'::"text", 'mutual_stop'::"text"])))),
    CONSTRAINT "ir_o_reach_chk" CHECK ((("o_reach" IS NULL) OR ("o_reach" = ANY (ARRAY['easily'::"text", 'difficult'::"text", 'no_response'::"text"])))),
    CONSTRAINT "ir_o_respect_chk" CHECK ((("o_respect" IS NULL) OR ("o_respect" = ANY (ARRAY['yes'::"text", 'mostly'::"text", 'no'::"text"])))),
    CONSTRAINT "ir_o_trust_chk" CHECK ((("o_trust" IS NULL) OR ("o_trust" = ANY (ARRAY['yes'::"text", 'maybe'::"text", 'no'::"text"])))),
    CONSTRAINT "ir_o_v2_complete_chk" CHECK ((("o_v2_submitted_at" IS NULL) OR (("o_reach" IS NOT NULL) AND ("o_accuracy" IS NOT NULL) AND ("o_progress" IS NOT NULL) AND ("o_respect" IS NOT NULL) AND ("o_trust" IS NOT NULL)))),
    CONSTRAINT "ir_t_accuracy_chk" CHECK ((("t_accuracy" IS NULL) OR ("t_accuracy" = ANY (ARRAY['matched'::"text", 'minor'::"text", 'major'::"text"])))),
    CONSTRAINT "ir_t_progress_chk" CHECK ((("t_progress" IS NULL) OR ("t_progress" = ANY (ARRAY['next_step'::"text", 'discussed'::"text", 'no_progress'::"text", 'mutual_stop'::"text"])))),
    CONSTRAINT "ir_t_reach_chk" CHECK ((("t_reach" IS NULL) OR ("t_reach" = ANY (ARRAY['easily'::"text", 'difficult'::"text", 'no_response'::"text"])))),
    CONSTRAINT "ir_t_respect_chk" CHECK ((("t_respect" IS NULL) OR ("t_respect" = ANY (ARRAY['yes'::"text", 'mostly'::"text", 'no'::"text"])))),
    CONSTRAINT "ir_t_trust_chk" CHECK ((("t_trust" IS NULL) OR ("t_trust" = ANY (ARRAY['yes'::"text", 'maybe'::"text", 'no'::"text"])))),
    CONSTRAINT "ir_t_v2_complete_chk" CHECK ((("t_v2_submitted_at" IS NULL) OR (("t_reach" IS NOT NULL) AND ("t_accuracy" IS NOT NULL) AND ("t_progress" IS NOT NULL) AND ("t_respect" IS NOT NULL) AND ("t_trust" IS NOT NULL))))
);


