    "geom_exact" "extensions"."geometry"(Point,4326),
    "country_code" character varying,
    "location_confirmed_at" timestamp with time zone,
    "discovery_confirmed_at" timestamp with time zone,
    "discovery_finalized_at" timestamp with time zone,
    "owner_pin_adjusted_at" timestamp with time zone,
    "owner_pin_adjustment_distance_m" numeric,
    CONSTRAINT "chk_availability_confirmed_rent_only" CHECK ((("listing_type" = 'rent'::"public"."property_listing_type") OR ("availability_confirmed_at" IS NULL))),
    CONSTRAINT "chk_owner_pin_dist_nonneg" CHECK ((("owner_pin_adjustment_distance_m" IS NULL) OR ("owner_pin_adjustment_distance_m" >= (0)::numeric))),
    CONSTRAINT "properties_address_mode_check" CHECK ((("address_mode")::"text" = ANY ((ARRAY['google_place'::character varying, 'manual'::character varying])::"text"[]))),
    CONSTRAINT "properties_annual_rent_increase_pct_range" CHECK ((("annual_rent_increase_pct" IS NULL) OR (("annual_rent_increase_pct" >= (0)::numeric) AND ("annual_rent_increase_pct" <= (100)::numeric)))),
    CONSTRAINT "properties_building_name_source_check" CHECK (("building_name_source" = ANY (ARRAY['google'::"text", 'owner'::"text", 'admin'::"text"]))),
    CONSTRAINT "properties_expected_price_per_sqft_nonneg" CHECK ((("expected_price_per_sqft" IS NULL) OR ("expected_price_per_sqft" >= (0)::numeric))),
    CONSTRAINT "properties_gas_type_check" CHECK (("gas_type" = ANY (ARRAY['pipeline'::"text", 'cylinder'::"text"]))),
    CONSTRAINT "properties_khata_type_check" CHECK ((("khata_type" IS NULL) OR ("khata_type" = ANY (ARRAY['A'::"text", 'B'::"text", 'not_applicable'::"text"])))),
    CONSTRAINT "properties_latlng_pair" CHECK ((("latitude" IS NULL) = ("longitude" IS NULL))),
    CONSTRAINT "properties_lister_flat_number_check" CHECK ((("lister_flat_number")::"text" ~ '^[A-Za-z0-9 /-]{1,10}$'::"text")),
    CONSTRAINT "properties_lister_role_check" CHECK (("lister_role" = ANY (ARRAY['owner'::"text", 'broker'::"text", 'property_manager'::"text", 'builder'::"text"]))),
    CONSTRAINT "properties_main_door_lock_type_check" CHECK ((("main_door_lock_type")::"text" = ANY ((ARRAY['standard'::character varying, 'godrej_manual'::character varying, 'digital_keypad'::character varying, 'smart_lock'::character varying])::"text"[]))),
    CONSTRAINT "properties_move_in_charges_amount_nonneg" CHECK ((("move_in_charges_amount" IS NULL) OR ("move_in_charges_amount" >= (0)::numeric))),
    CONSTRAINT "properties_notice_period_months_nonneg" CHECK ((("notice_period_months" IS NULL) OR ("notice_period_months" >= 0))),
    CONSTRAINT "properties_owner_diet_preference_check" CHECK ((("owner_diet_preference")::"text" = ANY ((ARRAY['no_preference'::character varying, 'prefer_vegetarian'::character varying, 'vegetarian_only'::character varying])::"text"[]))),
    CONSTRAINT "properties_owner_pet_preference_check" CHECK ((("owner_pet_preference")::"text" = ANY ((ARRAY['no_preference'::character varying, 'prefer_no_pets'::character varying, 'no_pets_strictly'::character varying])::"text"[]))),
    CONSTRAINT "properties_owner_tenant_type_preference_check" CHECK ((("owner_tenant_type_preference")::"text" = ANY ((ARRAY['no_preference'::character varying, 'prefer_family'::character varying, 'family_only'::character varying])::"text"[]))),
    CONSTRAINT "properties_parking_2w_count_nonneg" CHECK ((("parking_2w_count" IS NULL) OR ("parking_2w_count" >= 0))),
    CONSTRAINT "properties_parking_4w_count_nonneg" CHECK ((("parking_4w_count" IS NULL) OR ("parking_4w_count" >= 0))),
    CONSTRAINT "properties_possession_status_check" CHECK ((("possession_status" IS NULL) OR ("possession_status" = ANY (ARRAY['ready_to_move'::"text", 'under_construction'::"text", 'new_launch'::"text"])))),
    CONSTRAINT "properties_rent_brokerage_fixed_amount_nonneg" CHECK ((("rent_brokerage_fixed_amount" IS NULL) OR ("rent_brokerage_fixed_amount" >= (0)::numeric))),
    CONSTRAINT "properties_rent_brokerage_months_nonneg" CHECK ((("rent_brokerage_months" IS NULL) OR ("rent_brokerage_months" >= (0)::numeric))),
    CONSTRAINT "properties_rent_brokerage_type_check" CHECK ((("rent_brokerage_type" IS NULL) OR ("rent_brokerage_type" = ANY (ARRAY['none'::"text", 'fixed'::"text", 'months'::"text"])))),
    CONSTRAINT "properties_sale_brokerage_pct_range" CHECK ((("sale_brokerage_pct" IS NULL) OR (("sale_brokerage_pct" >= (0)::numeric) AND ("sale_brokerage_pct" <= (10)::numeric)))),
    CONSTRAINT "properties_sale_price_nonneg" CHECK ((("sale_price" IS NULL) OR ("sale_price" >= (0)::numeric))),
    CONSTRAINT "properties_water_storage_check" CHECK ((("water_storage" IS NULL) OR ("water_storage" = ANY (ARRAY['sump_only'::"text", 'overhead_only'::"text", 'both'::"text", 'none'::"text"]))))
);


ALTER TABLE "public"."properties" OWNER TO "postgres";


COMMENT ON COLUMN "public"."properties"."flat_number" IS 'Hidden from public view. Revealed only when visit is scheduled OR confirmation payment is received';



COMMENT ON COLUMN "public"."properties"."amenities" IS 'JSONB array e.g. ["gym","pool","power_backup","lift","security","cctv"]';



COMMENT ON COLUMN "public"."properties"."flat_number_revealed" IS 'Runtime flag set when flat_number is permitted to be shown to a specific user (checked at API layer)';



COMMENT ON COLUMN "public"."properties"."board_qr_code" IS 'Unique token embedded in QR code; links to /external-query?property=<token>';



COMMENT ON COLUMN "public"."properties"."auto_accept_enabled" IS 'Mirrors owner screening_opt_out; platform auto-accepts best eligible application';



COMMENT ON COLUMN "public"."properties"."owner_diet_preference" IS 'Owner dietary preference for tenants. Internal only — never exposed to tenants. Captured during inspection call.';



COMMENT ON COLUMN "public"."properties"."owner_pet_preference" IS 'Owner pet preference for tenants. Internal only — never exposed to tenants.';



COMMENT ON COLUMN "public"."properties"."owner_tenant_type_preference" IS 'Owner tenant type preference. Internal only — never exposed to tenants. Ops handles live-in/unmarried couple cases manually.';



COMMENT ON COLUMN "public"."properties"."security_deposit_amount" IS 'Exact deposit amount in INR. Owner-set. Alongside security_deposit_months for backward compatibility.';



COMMENT ON COLUMN "public"."properties"."building_notes" IS 'Owner-supplied description of the building / neighborhood. Separate from building_rules (house rules).';



COMMENT ON COLUMN "public"."properties"."parking_2w_count" IS 'Number of two-wheeler parking spots. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."parking_4w_count" IS 'Number of four-wheeler parking spots. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."parking_notes" IS 'Free-text parking notes (e.g., stack parking, visitor parking rules). Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."landmark" IS 'Section 1 location hint, e.g., "Near XYZ mall". Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."notice_period_months" IS 'Notice period before vacating, in months. Rent listings only. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."annual_rent_increase_pct" IS 'Annual rent increase percent (8 = 8%). Always public per D-136. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."water_storage" IS 'Water storage type: sump_only | overhead_only | both | none. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."listing_type" IS 'rent | sale. Default rent for backward compatibility. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."sale_price" IS 'Total sale price (₹). Sale listings only. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."price_negotiable" IS 'Whether the sale price is negotiable. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."expected_price_per_sqft" IS 'Manual per-sqft price (₹). NOT auto-calculated. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."possession_status" IS 'ready_to_move | under_construction | new_launch. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."possession_date" IS 'When the property is ready. Sale equivalent of available_from (D-135). Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."rera_registration_number" IS 'RERA registration number. Nudged for new construction. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."khata_type" IS 'A | B | not_applicable. Bangalore property classification. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."property_tax_paid_upto" IS 'Date property tax is paid up to. Phase 1.5.';



COMMENT ON COLUMN "public"."properties"."move_in_charges_amount" IS 'One-time move-in charges (rupees). Rent only. Phase 1.5 addendum.';



COMMENT ON COLUMN "public"."properties"."rent_brokerage_type" IS 'none | fixed | months. Discriminator for rent_brokerage_amount. Phase 1.5 addendum.';



COMMENT ON COLUMN "public"."properties"."sale_brokerage_pct" IS 'Sale brokerage % (0-10). Sale only. Phase 1.5 addendum.';



COMMENT ON COLUMN "public"."properties"."rent_brokerage_fixed_amount" IS 'Fixed brokerage amount in rupees. Set when rent_brokerage_type=fixed; NULL otherwise. Phase 1.5 Sync P3.';



COMMENT ON COLUMN "public"."properties"."rent_brokerage_months" IS 'Brokerage as number of months rent. Set when rent_brokerage_type=months; NULL otherwise. Phase 1.5 Sync P3.';



COMMENT ON COLUMN "public"."properties"."lock_in_months" IS 'Minimum tenancy in months before tenant can exit without penalty. Rent listings only. Null = not specified by owner.';



COMMENT ON COLUMN "public"."properties"."notice_period_days" IS 'Notice period in days before tenant vacates. Replaces notice_period_months for display. notice_period_months retained for legacy reads.';



COMMENT ON COLUMN "public"."properties"."super_built_up_area" IS 'Super built-up area in sqft. Optional companion to square_footage (carpet area).';



COMMENT ON COLUMN "public"."properties"."water_source" IS 'Water supply sources. Multi-select array. Valid values: municipal, borewell, tanker, rainwater_harvesting, packaged, open_well.';



COMMENT ON COLUMN "public"."properties"."availability_confirmed_at" IS 'Last time the owner explicitly confirmed this rental is still available. Rent-only: NULL for sale listings and non-public properties. Initialized to listed_at when a rental first becomes publicly listed. Reconfirmable once every 7 days via confirm_availability_of_rental().';



COMMENT ON COLUMN "public"."properties"."building_name_source" IS 'Provenance of building_name: google | owner | admin | NULL. Owner may set only owner/NULL; google/admin via trusted path.';



COMMENT ON COLUMN "public"."properties"."geom_exact" IS 'Authoritative confirmed property point (SRID 4326), kept in sync with latitude/longitude by trg_geom_sync. Public for all property types. Prompt 2 makes this the primary spatial anchor for Search.';



COMMENT ON COLUMN "public"."properties"."country_code" IS 'ISO country code (e.g. IN). Nullable, no default (guarded on INSERT). Populated by the trusted location resolver in Prompt 2.';



COMMENT ON COLUMN "public"."properties"."location_confirmed_at" IS 'When the exact pin was confirmed (trusted path). Wired in Prompt 2.';



COMMENT ON COLUMN "public"."properties"."discovery_confirmed_at" IS 'When the owner confirmed discovery geography (trusted path). Wired in Prompt 2.';



COMMENT ON COLUMN "public"."properties"."discovery_finalized_at" IS 'When admin finalized discovery geography (trusted path). Wired in Prompt 2.';



