    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "property_activity_log_actor_role_check" CHECK (("actor_role" = ANY (ARRAY['owner'::"text", 'admin'::"text", 'system'::"text"])))
);


ALTER TABLE "public"."property_activity_log" OWNER TO "postgres";


COMMENT ON TABLE "public"."property_activity_log" IS 'Append-only audit log for property state changes. Written by triggers/RPCs only.';



