CREATE TABLE IF NOT EXISTS "public"."property_geo_associations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "property_id" "uuid" NOT NULL,
    "geo_place_id" "uuid" NOT NULL,
    "relationship" "text",
    "source" "text" NOT NULL,
    "confidence" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_primary" boolean DEFAULT false NOT NULL,
    "evidence_type" "text",
    "distance_m" double precision,
    CONSTRAINT "property_geo_assoc_distance_nonneg" CHECK ((("distance_m" IS NULL) OR ("distance_m" >= (0)::double precision))),
    CONSTRAINT "property_geo_assoc_evidence_type_check" CHECK ((("evidence_type" IS NULL) OR ("evidence_type" = ANY (ARRAY['provider_address'::"text", 'provider_descriptor'::"text", 'provider_route'::"text", 'formatted_address_alias'::"text", 'curated_search_region'::"text", 'nearby_canonical'::"text", 'owner_added'::"text", 'admin_override'::"text"])))),
    CONSTRAINT "property_geo_assoc_owner_source" CHECK ((("source" <> 'owner'::"text") OR ("relationship" = 'area_road'::"text"))),
    CONSTRAINT "property_geo_associations_confidence_check" CHECK (("confidence" = ANY (ARRAY['high'::"text", 'medium'::"text", 'low'::"text"]))),
    CONSTRAINT "property_geo_associations_relationship_check" CHECK (("relationship" = ANY (ARRAY['primary_city'::"text", 'secondary_city'::"text", 'area_road'::"text"]))),
    CONSTRAINT "property_geo_associations_source_check" CHECK (("source" = ANY (ARRAY['google'::"text", 'system'::"text", 'owner'::"text", 'admin'::"text"])))
);


ALTER TABLE "public"."property_geo_associations" OWNER TO "postgres";


COMMENT ON TABLE "public"."property_geo_associations" IS 'Property to geo_place associations (primary/secondary city, area/road). Written only via trusted set_property_geo_associations (service role).';



COMMENT ON COLUMN "public"."property_geo_associations"."is_primary" IS 'Final-model primary flag (replaces relationship=primary_city in Prompt 2).';



COMMENT ON COLUMN "public"."property_geo_associations"."evidence_type" IS 'Factual provenance of this association. Populated by the trusted resolver in Prompt 2.';



COMMENT ON COLUMN "public"."property_geo_associations"."distance_m" IS 'Optional distance (m) from property pin to the canonical place, when evidence is proximity-based.';



