    CONSTRAINT "property_service_enquiries_property_type_check" CHECK (("property_type" = ANY (ARRAY['apartment'::"text", 'villa_row_house'::"text", 'independent_house'::"text", 'plot_land'::"text"]))),
    CONSTRAINT "property_service_enquiries_service_choice_check" CHECK (("service_choice" = ANY (ARRAY['property_management'::"text", 'vacant_property_care'::"text", 'find_tenant'::"text", 'nri_property_sale'::"text", 'nri_rent_tds'::"text", 'khata_mutation'::"text", 'not_sure'::"text"]))),
    CONSTRAINT "property_service_enquiries_status_check" CHECK (("status" = ANY (ARRAY['new'::"text", 'contacted'::"text", 'qualified'::"text", 'closed'::"text"])))
);


