CREATE OR REPLACE VIEW "public"."public_profiles" AS
 SELECT "u"."id" AS "user_id",
    "u"."full_name",
    "p"."profile_photo_url",
    "p"."bio",
    "p"."display_name",
    "p"."is_public"
   FROM ("public"."users" "u"
     LEFT JOIN "public"."profiles" "p" ON (("p"."user_id" = "u"."id")));


ALTER VIEW "public"."public_profiles" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."rental_preferences" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "preferred_city" "text",
    "preferred_localities" "text"[],
    "move_in_by" "date",
    "number_of_occupants" integer DEFAULT 1,
    "age" integer,
    "gender" "text",
    "marital_status" "text",
    "occupation" "text",
    "occupation_other" "text",
    "diet_preference" "text",
    "has_pets" boolean DEFAULT false,
    "pet_types" "text"[],
    "expected_stay_duration" "text",
    "is_foreign_citizen" boolean,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "preference_mode" "text" DEFAULT 'rent'::"text" NOT NULL,
    "buying_purpose" "text",
    "purchase_timeline" "text",
    "funding_stage" "text",
    CONSTRAINT "rental_preferences_age_check" CHECK ((("age" >= 16) AND ("age" <= 100))),
    CONSTRAINT "rental_preferences_buying_purpose_check" CHECK ((("buying_purpose" IS NULL) OR ("buying_purpose" = ANY (ARRAY['self_use'::"text", 'investment'::"text", 'family_member'::"text", 'still_deciding'::"text"])))),
    CONSTRAINT "rental_preferences_diet_preference_check" CHECK (("diet_preference" = ANY (ARRAY['veg'::"text", 'non_veg'::"text"]))),
    CONSTRAINT "rental_preferences_expected_stay_duration_check" CHECK (("expected_stay_duration" = ANY (ARRAY['less_than_6_months'::"text", '6_to_11_months'::"text", '1_year'::"text", '2_years'::"text", '3_years_plus'::"text", 'flexible'::"text"]))),
    CONSTRAINT "rental_preferences_funding_stage_check" CHECK ((("funding_stage" IS NULL) OR ("funding_stage" = ANY (ARRAY['self_funded'::"text", 'loan_pre_approved'::"text", 'planning_home_loan'::"text", 'savings_and_home_loan'::"text", 'still_evaluating'::"text", 'prefer_not_to_disclose'::"text"])))),
    CONSTRAINT "rental_preferences_gender_check" CHECK (("gender" = ANY (ARRAY['male'::"text", 'female'::"text", 'other'::"text"]))),
    CONSTRAINT "rental_preferences_marital_status_check" CHECK (("marital_status" = ANY (ARRAY['single'::"text", 'married'::"text", 'family'::"text", 'live_in'::"text"]))),
    CONSTRAINT "rental_preferences_number_of_occupants_check" CHECK ((("number_of_occupants" >= 1) AND ("number_of_occupants" <= 20))),
    CONSTRAINT "rental_preferences_occupation_check" CHECK (("occupation" = ANY (ARRAY['salaried'::"text", 'self_employed'::"text", 'student'::"text", 'retired'::"text", 'other'::"text"]))),
    CONSTRAINT "rental_preferences_preference_mode_check" CHECK (("preference_mode" = ANY (ARRAY['rent'::"text", 'buy'::"text", 'both'::"text"]))),
    CONSTRAINT "rental_preferences_purchase_timeline_check" CHECK ((("purchase_timeline" IS NULL) OR ("purchase_timeline" = ANY (ARRAY['as_soon_as_possible'::"text", 'within_1_month'::"text", 'within_1_to_3_months'::"text", 'within_3_to_6_months'::"text", 'more_than_6_months'::"text", 'still_exploring'::"text"]))))
);


