CREATE POLICY "rental_preferences_select_own" ON "public"."rental_preferences" FOR SELECT USING (("user_id" = "auth"."uid"()));



CREATE POLICY "rental_preferences_update_own" ON "public"."rental_preferences" FOR UPDATE USING (("user_id" = "auth"."uid"())) WITH CHECK (("user_id" = "auth"."uid"()));



CREATE POLICY "reports_insert_verified" ON "public"."comment_reports" FOR INSERT WITH CHECK ((("auth"."uid"() = "reporter_id") AND ( SELECT ("users"."phone_verified" AND "users"."email_verified")
   FROM "public"."users"
  WHERE ("users"."id" = "auth"."uid"()))));



CREATE POLICY "reports_select" ON "public"."comment_reports" FOR SELECT USING ((("reporter_id" = "auth"."uid"()) OR ( SELECT "public"."is_admin"() AS "is_admin")));



ALTER TABLE "public"."search_location_preferences" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "slp_insert_own" ON "public"."search_location_preferences" FOR INSERT TO "authenticated" WITH CHECK (("user_id" = "auth"."uid"()));



CREATE POLICY "slp_select_own" ON "public"."search_location_preferences" FOR SELECT TO "authenticated" USING (("user_id" = "auth"."uid"()));



CREATE POLICY "slp_update_own" ON "public"."search_location_preferences" FOR UPDATE TO "authenticated" USING (("user_id" = "auth"."uid"())) WITH CHECK (("user_id" = "auth"."uid"()));



ALTER TABLE "public"."users" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "users_insert_own" ON "public"."users" FOR INSERT WITH CHECK (("id" = "auth"."uid"()));



CREATE POLICY "users_select_own" ON "public"."users" FOR SELECT USING ((("id" = "auth"."uid"()) OR "public"."is_admin"()));



CREATE POLICY "users_update_own" ON "public"."users" FOR UPDATE USING ((("id" = "auth"."uid"()) OR "public"."is_admin"())) WITH CHECK ((("id" = "auth"."uid"()) OR "public"."is_admin"()));



CREATE POLICY "views_select_owner_admin" ON "public"."property_views" FOR SELECT USING (((( SELECT "properties"."owner_id"
   FROM "public"."properties"
  WHERE ("properties"."id" = "property_views"."property_id")) = "auth"."uid"()) OR ( SELECT "public"."is_admin"() AS "is_admin")));



